മറ്റൊരു റിപ്പോർട്ടിൽ: അനസ്(റ) പറഞ്ഞു: നിശ്ചയം, നബി(സ) നിസ്കാരത്തിന് വന്നാൽ വലത് കയ്യിൽ വടി പിടിച്ചശേഷം തിരിഞ്ഞുനോക്കിപ്പറയും: "നേരെ നിന്ന് അണികൾ ശരിപ്പെടുത്തുക." പിന്നെ ഇടതു കയ്യിൽ പിടിച്ച് തിരിഞ്ഞു നോക്കിപ്പറയും. "നേരെ നിന്ന് അണികൾ ശരിപ്പെടുത്തുക." (ദ)', 'مُحَمَّدِ بْنِ مُسْلِمِ بْنِ السَّائِبِ', 'മുഹമ്മദുബ്നു മുസ്ലിമിബ്നുസാഇബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 422, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
