insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلَاةُ الرَّجُلِ فِي جَمَاعَةٍ تَفْضُلُ عَلَى صَلَاةِ الرَّجُلِ وَحْدَهُ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً". (ق,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ജമാഅത്തായി നിർവ്വഹിക്കുന്ന നിസ്കാരം, അയാൾ ഒറ്റക്ക് നിർവ്വഹിക്കുന്ന നിസ്കാരത്തേക്കാൾ ഇരുപത്തിയേഴ് ഇരട്ടി പ്രതിഫലാർമായതാണ്." (ബു,മു,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 393, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عن أبي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا مَثَلَ الْمُهَجِّرِ إِلَى الصَّلَاةِ كَمَثَلِ الَّذِي يُهْدِي الْبَدَنَةَ، ثُمَّ الَّذِي عَلَى إِثْرِهِ كَالَّذِي يُهْدِي الْبَقَرَةَ، ثُمَّ الَّذِي عَلَى إِثْرِهِ كَالَّذِي يُهْدِي الْكَبْشَ، ثُمَّ الَّذِي عَلَى إِثْرِهِ كَالَّذِي يُهْدِي الدَّجَاجَةَ، ثُمَّ الَّذِي عَلَى إِثْرِهِ كَالَّذِي يُهْدِي الْبَيْضَةَ". (ن)', 'അബൂഹുറയ്റ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: നിസ്കാരത്തിനുവേണ്ടി ആദ്യമായെത്തുന്നവൻ ഒരു ഒട്ടകത്തിനെ ദാനം ചെയ്തവനെപ്പോലെയാണ്. പിന്നെ വരുന്നവൻ ഒരു പശുവിനെ ബലിയർപ്പിച്ചവനെപ്പോലെയും, ശേഷം എത്തുന്നവൻ ഒരാടിനെ ബലികഴിപ്പിച്ചവനെപ്പോലെയും അതുകഴിഞ്ഞ് വരുന്നവൻ ഒരു പിടക്കോഴിയെ ബലി നൽകിയവനെപ്പോലെയും, പിന്നീട് വരുന്നവൻ ഒരു മുട്ട ദാനം ചെയ്തവനെപ്പോലെയുമാണ്. (ന)', 'أبي هُرَيْرَةَ', 'അബൂഹുറയ്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 393, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ صَلَاةَ الرَّجُلِ فِي الْجَمَاعَةِ تَزِيدُ عَلَى صَلَاتِهِ وَحْدَهُ بِخَمْسَةٍ وَعِشْرِينَ جُزْءًا". (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാളുടെ ജമാഅത്ത് നിസ്കാരത്തിന് അയാൾ ഒറ്റക്കു നിർവ്വഹിക്കുന്ന നിസ്കാരത്തേക്കാൾ ഇരുപത്തഞ്ച് ഇരട്ടി പുണ്യം കൂടുതലുണ്ട്." (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 393, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الصَّلَاةُ الْخَمْسُ وَالْجُمْعَةُ إِلَى الْجُمْعَةِ كَفَّارَةٌ لِمَا بَيْنَهُنَّ مَا لَمْ تُغْشَ الْكَبَائِرُ". (م,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വൻ പാപങ്ങൾ പ്രവർത്തിക്കപ്പെടാത്ത കാലത്തോളം അഞ്ച് സമയത്തെ നിസ്കാരങ്ങൾ അവയ്ക്കിടയിൽ സംഭവിക്കുന്ന പാപങ്ങൾക്കും, ഒരു ജുമുഅഃ അടുത്ത ജുമുഅവരേക്കുമുള്ള പാപങ്ങൾക്കും ഉള്ള പ്രായശ്ചിത്തമാകുന്നു." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 393, 393, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ مُجَاهِدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ ابْنُ عَبَّاسٍ عَنْ رَجُلٍ يَصُومُ النَّهَارَ وَيَقُومُ اللَّيْلَ، لَا يَشْهَدُ جُمْعَةً وَلَا جَمَاعَةً، قَالَ: هُوَ فِي النَّارِ – قَالَ الترمذي: وَمَعْنَى الْحَدِيثِ أَنْ لَا يَشْهَدَ الْجَمَاعَةَ وَالْجُمْعَةَ رَغْبَةً عَنْهَا وَاسْتِخْفَافًا بِحَقِّهَا وَتَهَاوُنًا بِهَا. (ت)', 'മുജാഹിദ്(റ): പകലിൽ നോമ്പനുഷ്ഠിക്കുകയും രാത്രി നിന്ന് നിസ്കരിക്കുകയും ചെയ്യുന്ന, എന്നാൽ ജുമുഅക്കോ ജമാഅത്തുകൾക്കോ പങ്കെടുക്കാത്ത ഒരാളെക്കുറിച്ച് ഇബ്നുഅബ്ബാസ്(റ) ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: "അയാൾ നരകത്തിലാണ്." തുർമുദി പറയുന്നു: ജമാഅത്തിലും ജുമുഅയിലും വിരക്തി കാണിക്കുകയും അവയുടെ ബാധ്യതയെ ലാഘവത്തോടെ വീക്ഷിക്കുകയും, അവയെ നിസ്സാരവൽക്കരിക്കുകയും ചെയ്ത് അതിൽ പങ്കെടുക്കാതിരിക്കൽ എന്നാണ് ഈ ഹദീസിൽ ഉദ്ദേശിച്ചിട്ടുള്ളത്. (തു)', 'مُجَاهِدٍ', 'മുജാഹിദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 393, 394, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بنا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمًا الصُّبْحَ، فَقَالَ: "أَشَاهِدٌ فُلَانٌ؟" قَالُوا: لَا، قَالَ: "أَشَاهِدٌ فُلَانٌ؟" قَالُوا: لَا، قَالَ: "إِنَّ هَاتَيْنِ الصَّلَاتَيْنِ أَثْقَلُ الصَّلَوَاتِ عَلَى الْمُنَافِقِينَ، وَلَوْ تَعْلَمُونَ مَا فِيهِمَا لَأَتَيْتُمُوهُمَا وَلَوْ حَبْوًا عَلَى الرُّكَبِ، وَإِنَّ الصَّفَّ الْأَوَّلَ عَلَى مِثْلِ صَفِّ الْمَلَائِكَةِ، وَلَوْ عَلِمْتُمْ مَا فضيلتُهُ لَابْتَدَرْتُمُوهُ، وَإِنَّ صَلَاةَ الرَّجُلِ مَعَ الرَّجُلِ أَزْكَى مِنْ صَلَاتِهِ وَحْدَهُ، وَصَلَاتُهُ مَعَ الرَّجُلَيْنِ أَزْكَى مِنْ صَلَاتِهِ مَعَ الرَّجُلِ، وَمَا كَثُرَ فَهُوَ أَحَبُّ إِلَى اللهِ تَعَالَى". (د,ن,جه)', 'ഉബയ്യുബ്നു കഅബ്(റ): നബി(സ) ഒരു ദിവസം ഞങ്ങളോടൊപ്പം സുബ്ഹ് നിസ്കരിച്ചു. പിന്നെ ചോദിച്ചു: "ഇന്ന ആൾ ഇവിടെയുണ്ടോ?" അവർ പറഞ്ഞു: ഇല്ല. "ഇന്ന ആൾ വന്നിട്ടുണ്ടോ?" അവർ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "ഈ രണ്ടു നിസ്കാരങ്ങളും മുനാഫിഖുകൾക്ക് ഏറ്റവും ഭാരമുള്ളവയാണ്. അവ രണ്ടിലുമുള്ള (മഹത്വങ്ങൾ) നിങ്ങൾ അറിഞ്ഞിരുന്നെങ്കിൽ മുട്ടിലിഴഞ്ഞെങ്കിലും നിങ്ങൾ വരുമായിരുന്നു. ഒന്നാമത്തെ അണി മാലാഖമാരുടെ അണിക്കു തുല്യമാണ്. അതിന്റെ ശ്രേഷ്ഠത മനസ്സിലാക്കിയിരുന്നുവെങ്കിൽ നിങ്ങൾ അതിനു വേണ്ടി മത്സരിക്കുമായിരുന്നു. ഒരാൾ മറ്റൊരാളോടൊപ്പം നിസ്കരിക്കുന്നത് ഒറ്റക്കുള്ള നിസ്കാരത്തേക്കാൾ കൂടുതൽ പരിശുദ്ധി കൈവരിക്കുവാൻ പര്യാപ്തമായതാണ്. രണ്ടു പേർക്കൊപ്പം നിർവ്വഹിക്കുന്ന നമസ്കാരം ഒരാളോടൊപ്പം നിർവ്വഹിക്കുന്ന നിസ്കാരത്തേക്കാൾ ഉത്തമമായതാണ്. ആളുകളുടെ എണ്ണം എത്ര വർദ്ധിക്കുന്നുവോ അല്ലാഹുവിന് അതാണ് പ്രിയങ്കരം." (ദ,ന,ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅബ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 394, 394, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الصَّلَاةُ فِي جَمَاعَةٍ تَعْدِلُ خَمْسًا وَعِشْرِينَ صَلَاةً، فَإِذَا صَلَّاهَا فِي فَلَاةٍ فَأَتَمَّ رُكُوعَهَا وَسُجُودَهَا بَلَغَتْ خَمْسِينَ صَلَاةً". وَفِي رِوَايَةٍ: "صَلَاةُ الرَّجُلِ فِي الْفَلَاةِ تُضَاعَفُ عَلَى صَلَاتِهِ فِي الْجَمَاعَةِ". (د,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "ജമാഅത്തായുള്ള നിസ്കാരം ഇരുപത്തിയഞ്ച് നിസ്കാരങ്ങൾക്കു തുല്യമാണ്. സുജൂദുകളും റുകൂഉകളും പൂർണ്ണമാക്കിക്കൊണ്ട് അത് മരുഭൂമിയിലൽ വെച്ചാണ് നിർവ്വഹിക്കുന്നത് എങ്കിൽ അമ്പത് നിസ്കാരങ്ങൾക്ക് തുല്യമാണ്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=7), 1, 'وَفِي رِوَايَةٍ: "صَلَاةُ الرَّجُلِ فِي الْفَلَاةِ تُضَاعَفُ عَلَى صَلَاتِهِ فِي الْجَمَاعَةِ". (د,جه)', 'മറ്റൊരു നിവേദനിൽ: മരുഭൂമിയിൽ വെച്ചുള്ള ഒരാളുടെ നിസ്കാരം അയാളുടെ ജമാഅത്ത് നിസ്കാരത്തേക്കാൾ (പ്രതിഫലത്തിൽ) ഇരട്ടിയാക്കപ്പെടും. (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلَاةُ الرَّجُلِ فِي جَمَاعَةٍ تَزِيدُ عَلَى صَلَاةِ الرَّجُلِ وَحْدَهُ أَرْبَعًا وَعِشْرِينَ أَوْ خَمْسًا وَعِشْرِينَ دَرَجَةً". (د,ن,جه)', 'ഉബയ്യുബ്നു കഅബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാളുടെ ജമാഅത്ത് നിസ്കാരം അയാളുടെ ഒറ്റക്കുള്ള നിസ്കാരത്തേക്കാൾ ഇരുപത്തിനാലോ ഇരുപത്തിയഞ്ചോ ഇരട്ടി മഹത്തരമാണ്." (ദ,ന,ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅബ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 394, 394, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَتَعَاقَبُونَ فِيكُمْ مَلَائِكَةٌ بِاللَّيْلِ وَمَلَائِكَةٌ بِالنَّهَارِ، وَيَجْتَمِعُونَ فِي صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ، ثُمَّ يَعْرُجُ الَّذِينَ بَاتُوا فِيكُمْ، فَيَسْأَلُهُمْ – وَهُوَ أَعْلَمُ بِهِمْ – كَيْفَ تَرَكْتُمْ عِبَادِي؟ فَيَقُولُونَ: تَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ، وَأَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "രാത്രിയിലെ മലക്കുകളും പകലിലെ മലക്കുകളും തുടരെ തുടരെയായി നിങ്ങളിലെത്തും. അവർ സുബ്ഹ്, അസ്ർ നിസ്കാരങ്ങൾക്ക് പങ്കെടുക്കും. പിന്നെ രാത്രി നിങ്ങൾക്കൊപ്പമുണ്ടായിരുന്ന മലക്കുകൾ ആകാശത്തേക്കുയരും. അപ്പോൾ അല്ലാഹു അവരോട് ചോദിക്കും: (അല്ലാഹു അവരെക്കുറിച്ച് നന്നായി അറിയുന്നവൻ തന്നെ) ഏതവസ്ഥയിലാണ് നിങ്ങൾ എന്റെ അടിമകളോട് വിട വാങ്ങിയത്? മലക്കുകൾ പറയും: ഞങ്ങളവരെ സമീപിച്ചപ്പോഴും പിരിഞ്ഞപ്പോഴും അവർ നിസ്കരിക്കുകയാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 394, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَبْدِاللهِ بْنِ مَالِكٍ ابْنِ بُحَيْنَةَ رَضِيَ اللهُ عَنْهُمْ – رَجُلٍ مِنَ الْأَزْدِ – قَالَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا – وَقَدْ أُقِيمَتِ الصَّلَاةُ – يُصَلِّي رَكْعَتَيْنِ، فَلَمَّا انْصَرَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَاثَ بِهِ النَّاسُ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الصُّبْحَ أَرْبَعًا؟ الصُّبْحَ أَرْبَعًا؟". (خ)', 'അബ്ദുല്ലാഹിബ്നു മാലിക്(റ): ഇഖാമത്ത് വിളിക്കപ്പെട്ട ശേഷം രണ്ട് റക്അത്ത് നിസ്കരിച്ച ഒരാളെ നബി(സ) കണ്ടു. നബി(സ) നിസ്കരിച്ചു കഴിഞ്ഞപ്പോൾ ആളുകൾ ആ മനുഷ്യനു ചുറ്റും കൂടി. നബി(സ) അദ്ദേഹത്തോട് ചോദിച്ചു: "സുബ്ഹ് നാല് റക്അത്ത് നിസ്കരിക്കുകയോ? സുബ്ഹ് നാല് റക്അത്ത് നിസ്കരിക്കുകയോ?" (ബു)', 'عَبْدِاللهِ بْنِ مَالِكٍ ابْنِ بُحَيْنَةَ', 'അബ്ദുല്ലാഹിബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَهِدَ الْعِشَاءَ فِي جَمَاعَةٍ كَانَ لَهُ قِيَامُ نِصْفِ لَيْلَةٍ، وَمَنْ صَلَّى الْعِشَاءَ وَالْفَجْرَ فِي جَمَاعَةٍ كَانَ لَهُ كَقِيَامِ لَيْلَةٍ". (ق,ت)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): നബി(സ) പറഞ്ഞു: "ആർ ഇശാഇന്റെ ജമാഅത്തിൽ പങ്കെടുത്തുവോ, അയാൾക്ക് രാത്രിയുടെ പകുതി നിസ്കരിച്ചതിന്റെ പ്രതിഫലമുണ്ട്. ഒരാൾ ഇശാഉം ഫജ്റും ജമാഅത്തായി നിർവ്വഹിച്ചാൽ അയാൾക്ക് രാത്രി മുഴുവൻ നിസ്കരിച്ചതിന്റെ പ്രതിഫലമുണ്ട്." (ബു,മു,തു)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ جُنْدَبِ بْنِ سُفْيَانَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللهِ، فَلَا تُخْفِرُوا اللهَ فِي ذِمَّتِهِ". (م,ت)', 'ജുൻദുബുബ്നു സുഫ്യാൻ(റ): നബി(സ) പറഞ്ഞു: "വല്ലവനും സുബ്ഹ് നിസ്കരിച്ചാൽ അവൻ അല്ലാഹുവിന്റെ സംരക്ഷണത്തിലാണ്. അല്ലാഹു ഏറ്റെടുത്തിരിക്കുന്ന സംരക്ഷണ ബാദ്ധ്യതയെ നിങ്ങൾ ലംഘിക്കാതിരിക്കുക." (മു,തു)', 'جُنْدَبِ بْنِ سُفْيَانَ', 'ജുൻദുബുബ്നു സുഫ്യാൻ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ يَعْلَمُ النَّاسُ مَا فِي صَلَاةِ الْعِشَاءِ وَصَلَاةِ الفجر لَأَتَوْهُمَا وَلَوْ حَبْوًا". (جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ഇശാഇലും ഫജ്റിലുമുള്ള പ്രതിഫലങ്ങൾ ജനങ്ങൾ മനസ്സിലാക്കിയിരുന്നുവെങ്കിൽ മുട്ടിലിഴഞ്ഞെങ്കിലും അവർ അതിന് വരുമായിരുന്നു." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَثْقَلَ الصَّلَاةِ عَلَى الْمُنَافِقِينَ صَلَاةُ الْعِشَاءِ وَصَلَاةُ الْفَجْرِ، وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لَأَتَوْهُمَا وَلَوْ حَبْوًا". (ق,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "കപടവിശ്വാസികൾക്ക് ഏറ്റവും ഭാരമേറിയ നിസ്കാരമാണ് ഇശാഉം ഫജ്റും. അവ രണ്ടിലുമുള്ള പ്രതിഫലങ്ങൾ അവർ മനസ്സിലാക്കിയിരുന്നുവെങ്കിൽ മുട്ടിലിഴഞ്ഞെങ്കിലും അവർ അതിന് വരുമായിരുന്നു." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 395, 395, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عن أنس بن مالك رَضِيَ اللهُ عَنْهُمَا، وَعَنْ عُمَرَ بْنِ الْخَطَّابِ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَقُولُ: "من صَلَّى فِي مَسْجِدٍ جَمَاعَةً أَرْبَعِينَ لَيْلَةً، لَا تَفُوتُهُ الرَّكْعَةُ الْأُولَى مِنْ صَلَاةِ الْعِشَاءِ، كَتَبَ اللهُ لَهُ بِهَا عِتْقًا مِنَ النَّارِ". (جه)', 'അനസുബ്നു മാലിക്, ഉമറുബ്നുൽഖത്വാബ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ഇശാഇന്റെ ആദ്യ റക്അത്ത് നഷ്ടപ്പെടാത്തവിധം നാൽപത് രാത്രി പള്ളിയിൽ വെച്ച് ജമാഅത്തായി നിസ്കരിച്ചാൽ അതുമുഖേന അല്ലാഹു അയാൾക്ക് നരക വിമുക്തി രേഖപ്പെടുത്തും." (ജ)', 'أنس بن مالك', 'അനസുബ്നു മാലിക്, ഉമറുബ്നുൽഖത്വാബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 396, 396, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سمعتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "تفضُلُ صَلَاةُ الْجَمِيعِ صَلَاةَ أَحَدِكُمْ وَحْدَهُ، بِخَمْسٍ وَعِشْرِينَ جُزْءًا. وَتَجْتَمِعُ مَلَائِكَةُ اللَّيْلِ، وَمَلَائِكَةُ النَّهَارِ فِي صَلَاةِ الْفَجْرِ". ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ: فَاقْرَءُوا إِنْ شِئْتُمْ {إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا}. (خ,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "സംഘടിത നിസ്കാരത്തിന് ഒറ്റക്കുള്ള നിസ്കാരത്തേക്കാൾ ഇരുപത്തിയേഴ് ഇരട്ടി പ്രതിഫലമുണ്ട്. ഫജ്ർ നിസ്കാര സമയത്ത് രാത്രിയിലെയും പകലിലെയും മലക്കുകൾ ഒരുമിച്ചുകൂടും." ശേഷം അബൂഹുറൈറ പറഞ്ഞു: നിങ്ങൾ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നിങ്ങൾക്ക് ഈ ഖുർആൻ വാക്യം ഓതാം: "നിശ്ചയം, ഫജ്റിലെ ഖുർആൻ പാരായണം സാക്ഷ്യം വഹിക്കപ്പെടുന്നതാണ്." (17:78) (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 396, 396, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْظَمُ النَّاسِ أَجْرًا فِي الصَّلَاةِ أَبْعَدُهُمْ، فَأَبْعَدُهُمْ مَمْشًى، وَالَّذِي يَنْتَظِرُ الصَّلَاةَ حَتَّى يُصَلِّيَهَا مَعَ الْإِمَامِ أَعْظَمُ أَجْرًا، من الَّذِي يُصَلِّي ثُمَّ يَنَامُ". (خ)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ ഏറ്റവും പ്രതിഫലം ലഭിക്കുന്ന വ്യക്തി ഏറ്റവും വിദൂരത്തു നിന്ന് പള്ളിയിലേക്കു നടന്നു വരുന്നവനാണ്. ശേഷം അതിൽ കുറഞ്ഞ ദൂരത്തുനിന്ന് നടന്നു വരുന്നവനാണ്. നിസ്കാരത്തെ പ്രതീക്ഷിച്ചിരുന്ന് ഇമാമിനോടൊപ്പം നിസ്കരിക്കുന്നവന്നാണ്, നിസ്കരിക്കുകയും പിന്നെ ഉറങ്ങുകയും ചെയ്യുന്നവനേക്കാൾ പ്രതിഫലം." (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 396, 396, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: سمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ ثَلَاثَةٍ فِي قَرْيَةٍ وَلَا بَدْوٍ لَا تُقَامُ فِيهِمُ الصَّلَاةُ إِلَّا قَدِ اسْتَحْوَذَ عَلَيْهِمُ الشَّيْطَانُ، فَعَلَيْكَ بِالْجَمَاعَةِ، فَإِنَّمَا يَأْكُلُ الذِّئْبُ الْقَاصِيَةَ". (د,ن)', 'അബുദ്ദർദാഅ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു ഗ്രമാത്തിലോ ഉൾപ്രദേശത്തോ മൂന്നു പേരെങ്കിലും ഉണ്ടായിട്ട് അവിടെ ജമാഅത്ത് നിർവ്വഹിക്കപ്പെടാത്തപക്ഷം അവരെ പിശാച് അധീനപ്പെടുത്തുന്നതാണ്. സംഘകൂട്ടായ്മ നിനക്ക് നിർബന്ധമാണ്. ഒറ്റപ്പെട്ടതിനെയാണ് ചെന്നായ തിന്നുക." (ദ,ന)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 396, 396, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ هَمَمْتُ أَنْ آمُرَ بِالصَّلَاةِ فَتُقَامَ، ثُمَّ آمُرَ رَجُلًا فَيُصَلِّيَ بِالنَّاسِ، ثُمَّ أَنْطَلِقَ مَعِي بِرِجَالٍ مَعَهُمْ حُزَمٌ من حَطَب إِلَى قَوْمٍ لَا يَشْهَدُونَ الصَّلَاةَ، فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ بِالنَّارِ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിനായി ഇഖാമത്ത് വിളിക്കാനും ഒരാളോട് ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കാനും കൽപിക്കാൻ ഞാനുദ്ദേശിച്ചു. പിന്നെ വിറക് കെട്ടുമായി കുറച്ചാളുകളോടൊപ്പം നിസ്കാരത്തിന് വരാത്ത ജനതയിലേക്ക് ചെന്ന് അവരെ വീടുകളോടൊന്നിച്ച് കരിച്ച് കളയുകയും ചെയ്താലോ എന്നെനിക്ക് തോന്നി." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 396, 396, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ، وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ، فَأَخَّرَهُ، فَشَكَرَ اللهُ، لَهُ فَغَفَرَ لَهُ". ثُمَّ قَالَ: "الشُّهَدَاءُ خَمْسَةٌ: الْمَطْعُونُ، وَالْمَبْطُونُ، وَالْغَرِيقُ، وَصَاحِبُ الْهَدْمِ، وَالشَّهِيدُ فِي سَبِيلِ اللهِ......". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ഒരു വഴിയിലൂടെ നടക്കുമ്പോൾ മുള്ളുകളുള്ള ഒരു കൊമ്പ് കാണുകയും, അത് വഴിയിൽ നിന്ന് മാറ്റുകയും ചെയ്തു. അപ്പോൾ അല്ലാഹു അവന്റെ ഈ പ്രവർത്തനം സ്വീകരിക്കുകയും അവന് പൊറുത്തുകൊടുക്കുകയും ചെയ്തു." ശേഷം നബി(സ) പറഞ്ഞു: "രക്തസാക്ഷികൾ അഞ്ചു വിധമുണ്ട്: പ്ലേഗ് ബാധിച്ചു മരിച്ചവൻ, ഉദരരോഗം മൂലം മരിച്ചവൻ, മുങ്ങി മരിച്ചവൻ, കെട്ടിടം തകർന്ന് മരിച്ചവൻ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ രക്തസാക്ഷിയായവൻ..........." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ هَمَمْتُ أَنْ آمُرَ فِتْيَتِي فَيَجْمَعُوا حُزَمًا من حطبٍ،ثُمَّ آتِيَ قَوْمًا يُصَلُّونَ فِي بُيُوتِهِمْ لَيْسَتْ بِهِمْ عِلَّةٌ، فَأُحَرِّقَهَا عَلَيْهِمْ". (م,د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ കൂടെയുള്ള യുവാക്കളോട് ഒരു കെട്ട് വിറക് കൊണ്ടുവരാൻ കൽപിക്കാനും കാരണമില്ലാതെ വീട്ടിൽ വെച്ച് നിസ്കരിക്കുന്നവരുടെ അടുത്തു ചെന്ന് അത് അവരുടെമേൽ കത്തിക്കാനും ഞാൻ കരുതിപ്പോയി." (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ ابْنِ أُمِّ مَكْتُومٍ رَضِيَ اللهُ عَنْهُ قَالَ: يَا رَسُولَ اللهِ! إِنَّ الْمَدِينَةَ كَثِيرَةُ الْهَوَامِّ وَالسِّبَاعِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَتَسْمَعُ حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ؟ فَحَيَّ هَلًّا". (د,ن,جه)', 'ഇബ്നുഉമ്മിമക്തൂം(റ): അദ്ദേഹം ചോദിച്ചു: നബിയേ! മദീനയിൽ (ഞാൻ പള്ളിയിലേക്കു വരുന്ന വഴിയിൽ) ഉപദ്രവകാരികളായ ഇഴജന്തുക്കളും വന്യമൃഗങ്ങളും ധാരാളമുണ്ട് (എനിക്ക് ജമാഅത്തിൽ പങ്കെടുക്കൽ നിർബ്ബന്ധമുണ്ടോ)? നബി(സ) പറഞ്ഞു: "നീ ''ഹയ്യഅലസ്സ്വലാത്'', ''ഹയ്യഅലൽ ഫലാഹ്'' എന്നു കേൾക്കുന്നുണ്ടോ? എങ്കിൽ അതിലേക്കു മുന്നോട്ട് വരിക." (ദ,ന,ജ)', 'ابْنِ أُمِّ مَكْتُومٍ', 'ഇബ്നുഉമ്മിമക്തൂം(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ أُمِّ مَكْتُومٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنِّي كَبِيرٌ ضَرِيرٌ شَاسِعُ الدَّارِ، وَلَيْسَ لِي قَائِدٌ يُلَاوِمُنِي، فَهَلْ تَجِدُ لِي مِنْ رُخْصَةٍ؟ قَالَ: "هَلْ تَسْمَعُ النِّدَاءَ؟" قُلْتُ: نَعَمْ، قَالَ: "مَا أَجِدُ لَكَ رُخْصَةً". (د,جه)', 'ഇബ്നുഉമ്മിമക്തൂം(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: നബിയേ! ഞാൻ അന്ധനും വയോധികനും വീട് അകലത്തുള്ളവനുമാണ്. എന്നോടൊപ്പം വഴി നയിക്കാൻ ആരുമില്ല. എനിക്ക് വല്ല ഇളവുമുണ്ടോ? നബി(സ) ചോദിച്ചു: "നീ ബാങ്ക് കേൾക്കുന്നുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "എങ്കിൽ നിനക്ക് ഒരിളവും ഞാൻ കാണുന്നില്ല." (ദ,ജ)', 'ابْنِ أُمِّ مَكْتُومٍ', 'ഇബ്നുഉമ്മിമക്തൂം(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "من سَمِعَ النِّدَاءَ فَلَمْ يَأْتِهِ فَلَا صَلَاةَ لَهُ إِلَّا من عُذْرٍ". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ബാങ്ക് കേൾക്കുകയും ജമാഅത്തിന്ന് എത്താതിരിക്കുകയും ചെയ്താൽ അയാൾക്ക് നിസ്കാരമില്ല. കാരണമുള്ളവർക്കൊഴികെ." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 397, 397, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنِ ابْنِ عَبَّاسٍ وَابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمْ أَنَّهُمَا سَمِعَا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَلَى أَعْوَادِهِ: "لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ وَدْعِهِمُ الْجُمَاعَاتِ، أَوْ لَيَخْتِمَنَّ اللهُ عَلَى قُلُوبِهِمْ، ثُمَّ لَيَكُونُنَّ مِنَ الْغَافِلِينَ". (م,ن,جه)', 'ഇബ്നുഅബ്ബാസ്, ഇബ്നുഉമർ(റ): നബി(സ) പറയുന്നത് അവർ കേട്ടു: "ആളുകൾ ജമാഅത്തിൽ നിന്ന് പിന്മാറുന്നത് ഒഴിവാക്കണം. അല്ലാത്ത പക്ഷം അല്ലാഹു അവരുടെ ഹൃദയങ്ങൾക്ക് സീൽ ചെയ്യും. പിന്നീട് അവർ അശ്രദ്ധരായിത്തീരും." (മു,ന,ജ)', 'ابْنِ عَبَّاسٍ وَابْنِ عُمَرَ', 'ഇബ്നുഅബ്ബാസ്, ഇബ്നുഉമർ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 397, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيَنْتَهِيَنَّ رِجَالٌ عَنْ تَرْكِ الْجَمَاعَةِ أَوْ لَأُحَرِّقَنَّ بُيُوتَهُمْ". (جه)', 'ഉസാമത്തുബ്നു സൈദ്(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം, ജനങ്ങൾ ജമാഅത്ത് ഒഴിവാക്കുന്നതിൽ നിന്ന് പിന്തിരിയട്ടെ. അല്ലെങ്കിൽ ഞാനവരുടെ വീടുകൾ ചുട്ടെരിക്കുകതന്നെചെയും." (ജ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമത്തുബ്നു സൈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 398, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَقَدْ هَمَمْتُ أَنْ آمُرَ بحطب فيُحطَبَ، ثُمَّ آمُرَ بِالصَّلَاةِ فَيُؤَذَّنَ لَهَا، ثُمَّ آمُرَ رَجُلًا فيؤُمَّ النَّاسَ، ثُمَّ أُخَالِفَ إِلَى رجال، فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ. وَالَّذِي نَفْسِي بِيَدِهِ، لَوْ يَعْلَمُ أَحَدُهُمْ أَنَّهُ يَجِدُ عَرْقًا سَمِينًا، أَوْ مِرْمَاتَيْنِ حَسَنَتَيْنِ لَشَهِدَ الْعِشَاءَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനിൽ സത്യം, ഞാൻ ഇങ്ങനെ ഉദ്ദേശിച്ചു. കുറച്ച് വിറക് ശേഖരിക്കുവാൻ ഞാൻ കൽപ്പിക്കുക; പിന്നീട് നിസ്കരിക്കുവാൻ കൽപ്പിക്കുക; നമസ്കാരത്തിന് ബാങ്ക് വിളിക്കുക; ഒരാളെ വിളിച്ച് ജനങ്ങൾക്ക് ഇമാമായി നിന്ന് നിസ്കരിക്കുവാൻ കൽപ്പിക്കുക. അന്തരം ചില ആളുകളുടെ വീടുളിലേക്ക് ഞാൻ പോവുക. എന്നിട്ട് (ജമാഅത്തിൽ പങ്കെടുക്കാത്ത) ആളുകളെ അകപ്പെടുത്തി അവരുടെ വീടുകൾ കത്തിച്ചു കളയുക. എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനിൽ സത്യം, അവരിലാർക്കെങ്കിലും തടിച്ച മാംസമുള്ള എല്ലോ, ആടിന്റെ കുളമ്പിലുള്ള മാസമോ കിട്ടുമെന്നറിയുകയാണെങ്കിൽ അവൻ ഇശാ നിസ്കാരത്തിൽ പങ്കെടുക്കുമായിരുന്നു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 398, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْأَبْعَدُ فَالْأَبْعَدُ مِنَ الْمَسْجِدِ أَعْظَمُ أَجْرًا". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പള്ളിയിൽ നിന്ന് ഏറ്റവും അകലെയുള്ളവർക്ക് ഏറ്റവും കൂടുതൽ പ്രതിഫലം, പിന്നെ അതിൽ കുറഞ്ഞ അകലെയുള്ളവർക്ക്, എന്നിങ്ങനെയാണ് ഫ്രതിഫലം ലഭിക്കുക." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 398, 398, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَجُلٌ لَا أَعْلَمُ أَحَدًا مِنَ النَّاسِ مِمَّنْ يُصَلِّي الْقِبْلَةَ مِنْ أَهْلِ الْمَدِينَةِ أَبْعَدَ مَنْزِلًا مِنَ الْمَسْجِدِ مِنْ ذَلِكَ الرَّجُلِ، وَكَانَ لَا تُخْطِئُهُ صَلَاةٌ فِي الْمَسْجِدِ، فَقُلْتُ: لَوِ اشْتَرَيْتَ حِمَارًا تَرْكَبُهُ فِي الرَّمْضَاءِ وَالظُّلْمَةِ؟ فَقَالَ: مَا أُحِبُّ أَنَّ مَنْزِلِي إِلَى جَنْبِ الْمَسْجِدِ، فَنُمِيَ الْحَدِيثُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُ عَنْ قَوْلِهِ ذَلِكَ، فَقَالَ: أَرَدْتُ يَا رَسُولَ اللهِ! أَنْ يُكْتَبَ لِي إِقْبَالِي إِلَى الْمَسْجِدِ وَرُجُوعِي إِلَى أَهْلِي إِذَا رَجَعْتُ، فَقَالَ: "أَعْطَاكَ اللهُ ذَلِكَ كُلَّهُ، أَنْطَاكَ اللهُ جَلَّ وَعَزَّ مَا احْتَسَبْتَ كُلَّهُ أَجْمَعَ". (م,د,جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): ഖിബ്ലക്ക് നേരേ നിസ്കരിക്കുന്ന മദീനാ നിവാസികളിൽപ്പെട്ട ഒരാൾ, അദ്ദേഹത്തേക്കാൾ പള്ളിയിൽ നിന്നും വീട് വിദൂരമായ ആരേയും എനിക്കറിയില്ല. അദ്ദേഹമാകട്ടെ പള്ളിയിലെ ഒരു നിസ്കാരത്തിലും വീഴ്ച വരുത്താറുമില്ല. അപ്പോൾ ഞാൻ പറഞ്ഞു: നിങ്ങൾക്ക് ചരൽപ്രദേശത്തും, രാത്രിയിലും യാത്രക്കു വേണ്ടി ഒരു കഴുതയെ വാങ്ങാമല്ലോ? അയാൾ പറഞ്ഞു: എന്റെ വീട് പള്ളിക്കരികിലാകുന്നത് തന്നെ എനിക്കിഷ്ടമല്ല. ഇക്കാര്യം റസൂലിന്റെ അടുക്കലെത്തി. അതിനെക്കുറിച്ച് നബി(സ) അയാളോട് അന്വേഷിച്ചു. അയാൾ പറഞ്ഞു: എന്റെ പള്ളിയിലേക്കുള്ള വരവും തിരിച്ച് കുടുംബത്തിലേക്കുള്ള പോക്കും പ്രതിഫലത്തിനർഹമായിത്തീരാനാണ് ഞാൻ ആഗ്രഹിക്കുന്നത്. നബി(സ) പറഞ്ഞു: "താങ്കൾക്ക് അല്ലാഹു അത് പൂർണ്ണമായും നൽകട്ടെ, നീ പ്രതിഫലം ആഗ്രഹിക്കുന്നത് മുഴുവനായും പ്രതാപവാനായ അല്ലാഹു നിനക്ക് നൽകട്ടെ." (മു,ദ,ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 398, 399, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "من خَرَجَ مِنْ بَيْتِهِ مُتَطَهِّرًا إِلَى صَلَاةٍ مكتوبة فَأَجْرُهُ كَأَجْرِ الْحَاجِّ الْمُحْرِمِ، وَمَنْ خَرَجَ إِلَى تَسْبِيحِ الضُّحَى لَا يَنْصِبُهُ إِلَّا إِيَّاهُ فَأَجْرُهُ كَأَجْرِ الْمُعْتَمِرِ، وَصَلَاةٌ عَلَى أَثَرِ صَلَاةٍ لَا لَغْوَ بَيْنَهُمَا كِتَابٌ فِي عِلِّيِّينَ". (د)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "വല്ലവനും വീട്ടിൽ നിന്നും വുദുചെയ്ത് ഒരു നിർബന്ധ നിസ്കാരം നിർവ്വഹിക്കാൻ വേണ്ടി പുറപ്പെട്ടാൽ അയാളുടെ പ്രതിഫലം ഇഹ്റാം ചെയ്ത ഒരു ഹാജിയുടേതിന് തുല്യമാണ്. വല്ലവനും ളുഹാ നിസ്കരിക്കാൻ വേണ്ടി മാത്രമായി പുറപ്പെട്ടാൽ അയാൾക്ക് ഉംറ ചെയ്തവന്റെ പ്രതിഫലമുണ്ട്. ഒരു നിസ്കാരത്തിനു ശേഷം അടുത്ത നിസ്കാരം വരെ വ്യർത്ഥ കാര്യങ്ങളൊന്നുമില്ലെങ്കിൽ അത് ഇല്ലിയ്യീനിൽ¹ ഒരു രേഖയായിരിക്കും." (ദ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', '¹. സ്വർഗ്ഗക്കാരുടെ സ്ഥാനം.', null, array['د']::text[], array['ദ']::text[], null, null, 399, 399, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عن أنس بن مالك رَضِيَ اللهُ عَنْهُمَا قَالَ: أَرَادَتْ بنو سلمة أن يتحَوَّلُوا من دِيَارِهِمْ إِلَى قُرْبِ الْمَسْجِدِ، فَكَرِهَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعْرُوا الْمَدِينَةَ، فَقَالَ: "يَا بني سلمة! أَلَا تَحْتَسِبُونَ آثَارَكُمْ؟" فَأَقَامُوا. (جه)', 'അനസുബ്നു മാലിക്(റ): സലമ ഗോത്രക്കാർ അവരുടെ വീടുകൾ പള്ളിയുടെ സമീപത്തേക്ക് മാറ്റാൻ ഉദ്ദേശിച്ചു. നബി(സ) മദീന വിജനമാക്കിയിടുന്നത് വെറുത്തു. അവിടുന്ന് പറഞ്ഞു: "ബനൂസലമ നിങ്ങളുടെ കാലടികൾക്ക് നിങ്ങൾ പ്രതിഫലമാഗ്രഹിക്കുന്നില്ലേ?" അപ്പോൾ അവർ അവിടെത്തന്നെ താമസമാക്കി. (ജ)', 'أنس بن مالك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 399, 399, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلَاةُ الرَّجُلِ فِي جَمَاعَةٍ تزيد عَلَى صَلَاتِهِ فِي بيته وصلاته في سوقه خَمْسًا وَعِشْرِينَ دَرَجَةً، وَذَلِكَ أَنَّ أحدهم إذا توضَّأً فَأَحْسَنَ الْوُضُوءَ، ثُمَّ أَتَى الْمَسْجِدَ، لَا يُرِيدُ إِلَّا الصَّلَاةَ وَلَا يَنْهَزُهُ إِلَّا الصَّلَاةُ، فَلَمْ يخطُ خَطْوَةً إِلَّا رُفِعَ لَهُ بِهَا دَرَجَةٌ،وَحُطَّ عَنْهُ بِهَا خَطِيئَةٌ حَتَّى يَدْخُلَ الْمَسْجِدَ، فَإِذَا دَخَلَ الْمَسْجِدَ كَانَ فِي صَلَاةٍ مَا كَانَتِ الصَّلَاةُ هِيَ تَحْبِسُهُ، وَالْمَلَائِكَةُ يُصَلُّونَ عَلَى أَحَدِكُمْ مَا دَامَ فِي مجلسه الَّذِي صَلَّى فِيهِ، يَقُولُونَ: اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ارْحَمْهُ، اللَّهُمَّ تُبْ عَلَيْهِ، مَا لَمْ يُؤْذِ فِيهِ، مَا لَمْ يُحْدِثْ فِيهِ". (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ജമാഅത്തായി നിർവ്വഹിക്കുന്ന നിസ്കാരം അയാൾ വീട്ടിൽ നിന്നോ അങ്ങാടിയിൽ നിന്നോ നിസ്കരിക്കുന്നതിനേക്കാൾ ഇരുപത്തിയഞ്ചിരട്ടി പ്രതിഫലമുള്ളതാണ്. നിങ്ങളിലൊരാൾ നന്നായി വുദു ചെയ്ത് പള്ളിയിലേക്ക് പുറപ്പെടുകയും നിസ്കാരമല്ലാതെ മറ്റൊന്നും അയാൾ ലക്ഷ്യമാക്കാതിരിക്കുകയും ചെയ്താൽ ഓരോ കാലടിക്കും ഓരോ പദവി അവൻ ഉയരുകയും ഒരു പാപം നീങ്ങുകയും ചെയ്യും, പള്ളിയിൽ പ്രവേശിക്കുംവരെ. പള്ളിയിൽ അയാൾ നിസ്കാരം പ്രതീക്ഷിച്ചിരിക്കുന്ന ഓരോ സമയവും അയാൾ നിസ്കാരത്തിലാണ്. അയാൾ നിസ്കാരശേഷം അവിടെത്തന്നെ ഇരിക്കുന്നേടത്തോളം സമയം മലക്കുകൾ അയാൾക്ക് വേണ്ടി പ്രാർത്ഥിക്കും. അവർ പറയും: അല്ലാഹൂവേ ഇയാൾക്ക് പൊറുത്തുകൊടുക്കേണ! കാരുണ്യം നൽകണമേ! പാപമോചനം നൽകണേ!, അവന്ന് ബുദ്ധിമുട്ട് തോന്നാതെയും വുദൂ നഷ്ടപ്പെടാതെയും ഇരിക്കുന്ന സമയത്തോളം (ഇപ്രകാരം പറഞ്ഞുകൊണ്ടിരിക്കും)." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 399, 399, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتِ الْأَنْصَارُ بَعِيدَةً مَنَازِلُهُمْ مِنَ الْمَسْجِدِ، فَأَرَادُوا أَنْ يَقْتَرِبُوا، فَنَزَلَتْ: {وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ} [يس: ١٢] قَالَ: فَثَبَتُوا. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അൻസാറുകളുടെ വീടുകൾ പള്ളിയിൽനിന്നും വളരെ ദൂരെയായിരുന്നു. അവർ വീടുകൾ പള്ളിയുടെ അടുത്ത് നിർമ്മിക്കുവാൻ ഉദ്ദേശിച്ചു. അപ്പോഴാണ് "അവർ പ്രവർത്തിച്ചതും അവരുടെ (കർമ്മങ്ങളുടെ) അനന്തരഫലങ്ങളും നാം രേഖപ്പെടുത്തും" (യാസീൻ:12) എന്ന വചനമിറങ്ങിയത്. ഇബ്നുഅബ്ബാസ് പറയുന്നു: അപ്പോൾ അവർ അവിടെത്തന്നെ സ്ഥിരമാക്കി. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'يس: ١٢', null, 399, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَبْعَةٌ يُظِلُّهُمُ اللهُ فِي ظِلِّهِ، يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: الْإِمَامُ الْعَادِلُ، وَشَابٌّ نَشَأَ فِي عبادة ربِّه، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسَاجِدِ، وَرَجُلَانِ تَحَابَّا فِي اللهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ طَلَبَتْهُ امْرَأَةٌ ذَاتُ منصب وجمال فَقَالَ: إِنِّي أَخَافُ اللهَ، وَرَجُلٌ تَصَدَّقَ أَخْفَى حَتَّى لَا تعلم شماله ما تُنفق يمينه، وَرَجُلٌ ذَكَرَ اللهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു തണലും ലഭിക്കാത്ത അന്ത്യദിനത്തിൽ അല്ലാഹു ഏഴാളുകൾക്ക് തണൽ നൽകും: നീതിമാനായ ഭരണാധികാരി, അല്ലാഹുവിനെ ആരാധിച്ചുകൊണ്ട് വളർന്ന യുവാവ്, പള്ളികളുമായി ഹൃദയം ബന്ധിച്ചിരിക്കുന്ന യുവാവ്, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പരസ്പരം സ്നേഹിക്കുകയും, അതിന്റെപേരിൽ ഒത്തുകൂടുകയും പിരിഞ്ഞു പോവുകയും ചെയ്ത രണ്ട് വ്യക്തികൾ, മഹിമയും സൗന്ദര്യവുമുള്ള ഒരു സ്ത്രീ ലൈംഗികവേഴ്ചക്കു ക്ഷണിച്ചപ്പോൾ ഞാൻ അല്ലാഹുവിനെ ഭയപ്പെടുന്നുവെന്നു പറയുന്ന വ്യക്തി, വലതുകൈ ചിലവഴിക്കുന്നത് ഇടതുകൈ അറിയാത്ത വിധം രഹസ്യമായി ദാനധർമ്മം ചെയ്യുന്ന വ്യക്തി, ഒഴിഞ്ഞിരുന്ന് അല്ലാഹുവിനെ സ്മരിക്കുകയും അങ്ങനെ കണ്ണീരൊഴുക്കുകയും ചെയ്യുന്ന വ്യക്തി എന്നിവരാണവർ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 400, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا تَوَطَّنَ رَجُلٌ مُسْلِمٌ الْمَسَاجِدَ لِلصَّلَاةِ وَالذِّكْرِ إِلَّا تَبَشْبَشَ اللهُ لَهُ كَمَا يَتَبَشْبَشُ أَهْلُ الْغَائِبِ بِغَائِبِهِمْ إِذَا قَدِمَ عَلَيْهِمْ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം നിസ്കാരവും ദൈവസ്മരണയുമായി പള്ളിയിൽ ഇരിക്കുന്നതിൽ അല്ലാഹു വളരെയധികം സന്തോഷിക്കുന്നു. യാത്ര പോയവൻ തിരിച്ചുവരുമ്പോൾ കുടുംബക്കാർ സന്തോഷിക്കുന്നതുപോലെ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 400, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "من غدا إِلَى الْمَسْجِدِ وَرَاحَ أَعَدَّ اللهُ لَهُ نُزُلَهُ مِنَ الْجَنَّةِ كُلَّمَا غَدَا أَوْ رَاحَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ പള്ളിയിലേക്ക് രാവിലെയും വൈകുന്നേരവും പോകുന്നുവെന്നിരിക്കട്ടെ, എങ്കിൽ അവൻ രാവിലെ പോകുമ്പോഴും വൈകുന്നേരം പോകുമ്പോഴുമെല്ലാം അല്ലാഹു അവനു വേണ്ടി സ്വർഗ്ഗത്തിൽ വിരുന്നൊരുക്കുന്നതാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 400, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "من توضأً فَأَحْسَنَ الْوُضُوءَ، ثُمَّ خَرَجَ عَامِدًا إِلَى الْمَسْجِدِ، فَوَجَدَ النَّاسَ قَدْ صَلَّوْا، كَتَبَ اللهُ لَهُ مثل أجر مَنْ حَضَرَهَا وَلَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ നന്നായി വുദു ചെയ്ത് പള്ളിയിലേക്ക് പുറപ്പെട്ടാൽ ജനങ്ങളുടെ നിസ്കാരം കഴിഞ്ഞെന്ന് കണ്ടാലും അവിടെ എത്തിയവരുടേതിന് തുല്യമായ പ്രതിഫലം അല്ലാഹു അയാൾക്ക് രേഖപ്പെടുത്തും. അത് മറ്റുള്ളവരുടെ പ്രതിഫലത്തിൽ യാതൊരു കുറവും വരുത്തുകയില്ല." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 400, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أُقِيمَتِ الصَّلَاةُ فَلَا تَأْتُوهَا وَأَنْتُمْ تَسْعَوْنَ، وَأْتُوهَا تَمْشُونَ، وَعَلَيْكُمُ السَّكِينَةُ، فَمَا أَدْرَكْتُمْ فَصَلُّوا، وَمَا فَاتَكُمْ فَأَتِمُّوا". (ق,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിക്കപ്പെട്ടാൽ നിങ്ങൾ ധൃതിയിൽ അതിനെ സമീപിക്കേണ്ടതില്ല. നിങ്ങൾ നടന്നുവരിക. ശാന്തത പാലിക്കുക. നിങ്ങൾക്ക് (ഒന്നിച്ച്) ലഭിക്കുന്നത് നിസ്കരിക്കുക. നഷ്ടപ്പെട്ടത് പൂർത്തീകരിക്കുക." (ബു,മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 400, 400, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عن أبي سعيد الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سمعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَلَا أَدُلُّكُمْ عَلَى مَا يُكَفِّرُ اللهُ بِهِ الْخَطَايَا وَيَزِيدُ بِهِ الْحَسَنَاتِ". قَالُوا: بَلَى، يَا رَسُولَ اللهِ! قَالَ: "إِسْبَاغُ الْوُضُوءِ عِنْدَ الْمَكَارِهِ، وَكَثْرَةُ الْخُطَى إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ". (جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "അല്ലാഹു നിങ്ങളുടെ പാപങ്ങൾ പൊറുക്കുകയും നന്മകൾ വർദ്ധിപ്പിക്കുകയും ചെയ്യുന്ന ഒരുകാര്യം ഞാൻ നിങ്ങൾക്ക് അറിയിച്ചുതരട്ടെയോ?" അവർ പറഞ്ഞു: അതെ പ്രവാചകരേ! നബി(സ) പറഞ്ഞു: "പ്രയാസകരമായ സമയങ്ങളിൽ പൂർണ്ണമായി വുദു ചെയ്യുക. പള്ളികളിലേക്ക് കാലടികൾ വർദ്ധിപ്പിക്കുക. ഒരു നിസ്കാരശേഷം അടുത്തതിനെ പ്രതീക്ഷിക്കുക." (ജ)', 'أبي سعيد الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 401, 401, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَنْ سَرَّهُ أَنْ يَلْقَى اللهَ عَزَّ وَجَلَّ غَدًا مُسْلِمًا فَلْيُحَافِظْ عَلَى هَؤُلَاءِ الصَّلَوَاتِ الْخَمْسِ حَيْثُ يُنَادَى بِهِنَّ، فَإِنَّهُنَّ مِنْ سُنَنِ الْهُدَى، وَإِنَّ اللهَ شَرَعَ لِنَبِيِّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُنَنَ الْهُدَى، وَلَعَمْرِي! لَوْ أَنَّ كُلَّكُمْ صَلَّى فِي بَيْتِهِ لَتَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ، وَلَوْ تَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ لَضَلَلْتُمْ، وَلَقَدْ رَأَيْتُنَا وَمَا يَتَخَلَّفُ عَنْهَا إِلَّا مُنَافِقٌ مَعْلُومُ النِّفَاقِ، وَلَقَدْ رَأَيْتُ الرَّجُلَ يُهَادَى بَيْنَ الرَّجُلَيْنِ حَتَّى يَدْخُلَ فِي الصَّفِّ، وَمَا مِنْ رَجُلٍ يَتَطَهَّرُ فَيُحْسِنُ الطُّهُورَ فَيَعْمِدُ إِلَى الْمَسْجِدِ فَيُصَلِّيَ فِيهِ، فَمَا يَخْطُو خَطْوَةً إِلَّا رَفَعَ اللهُ لَهُ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ بِهَا خَطِيئَةً. (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നാളെ മുസ്ലിമായി അല്ലാഹുവിനെ കണ്ടുമുട്ടുന്നതിൽ സന്തോഷിക്കുന്നവർ അഞ്ച് നേരത്തെ നിസ്കാരങ്ങൾ അതിന് വിളിക്കപ്പെടുമ്പോൾ നിലനിർത്തട്ടെ (അതിന്റേതായ സമയത്തു തന്നെ പതിവായി നിർവ്വഹിക്കട്ടെ). അതാണ് സന്മാർഗ്ഗ ചര്യ. അല്ലാഹു നിങ്ങളുടെ പ്രവാചകന് സന്മാർഗ്ഗചര്യകൾ നിയമമാക്കിയിരിക്കുന്നു. എന്റെ ജീവിതമാണ് സത്യം! നിങ്ങളെല്ലാവരും സ്വന്തം ഭവനങ്ങളിലാണ് നിസ്കരിക്കുന്നതെങ്കിൽ നിങ്ങൾ നിങ്ങളുടെ പ്രവാചക ചര്യ ഉപേക്ഷിച്ചു. നിങ്ങളുടെ പ്രവാചകന്റെ ചര്യ ഉപേക്ഷിച്ചാൽ നിങ്ങൾ വഴികേടിലായി. കാപട്യം വ്യക്തമായ കപട വിശ്വാസിയല്ലാതെ അതിൽ (ജമാഅത്തിൽ) നിന്നും വിട്ടുനിൽക്കില്ലെന്നാണ് നമ്മുടെ അനുഭവം. ഒരാൾ രണ്ടാളുകൾക്കിടയിൽ അകലമുണ്ടാക്കി അണിയിൽ പ്രവേശിക്കുന്നത് ഞാൻ കാണുന്നു. ഒരാൾ നന്നായി ശുദ്ധി വരുത്തുകയും പള്ളിയിൽ പോയി നിസ്കരിക്കുകയും ചെയ്യുമ്പോൾ അവന്റെ ഓരോ കാലടിക്കും പകരമായി അവനു വേണ്ടി പദവി ഉയർത്തപ്പെടുകയും അവന്റെ ഒരു തെറ്റ് മായ്ക്കപ്പെടുകയും ചെയ്യും." (ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 401, 401, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "من خَرَجَ من بَيْتِهِ إِلَى الصَّلَاةِ فَقَالَ: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِحَقِّ السَّائِلِينَ عَلَيْكَ، وَأَسْأَلُكَ بِحَقِّ مَمْشَايَ هَذَا، فَإِنِّي لَمْ أَخْرُجْ أَشَرًا وَلَا بَطَرًا وَلَا رِيَاءً وَلَا سُمْعَةً، وَخَرَجْتُ اتِّقَاءَ سُخْطِكَ وَابْتِغَاءَ مَرْضَاتِكَ، فَأَسْأَلُكَ أَنْ تُعيذَني من النَّارِ، وَأَنْ تَغْفِرَ لِي ذُنُوبِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، أَقْبَلَ اللهُ عَلَيْهِ بوجهه، وَاسْتَغْفَرَ لَهُ سَبْعُونَ أَلْفَ مَلَك". (جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ വീട്ടിൽ നിന്ന് നിസ്കാരത്തിന് പുറപ്പെടുകയും ''അല്ലാഹുവേ! ചോദിക്കുന്നവർക്ക് നിന്നിൽ നിന്നുള്ള അവകാശം മുഖേനയും എന്റെ ഈ നടത്തത്തിന്റെ അവകാശം മുഖേനയും ഞാൻ നിന്നോട് ചോദിക്കുന്നു. ഞാൻ തിന്മക്കോ ഗർവ്വിനോ പ്രദർശനാർത്ഥമോ പ്രശസ്തിക്കോ വേണ്ടി പുറപ്പെട്ടിട്ടില്ല. നിന്റെ കോപത്തെ സൂക്ഷിച്ചും നിന്റെ തൃപ്തി തേടിയുമാണ് ഞാൻ പുറപ്പെട്ടത്. നീ എന്നെ നരകത്തിൽ നിന്ന് രക്ഷിക്കണമെന്നും, എന്റെ പാപങ്ങൾ പൊറുത്തു തരണമെന്നും ഞാൻ നിന്നോട് അപേക്ഷിക്കുന്നു. പാപങ്ങൾ പൊറുക്കുന്നവനായി നീ മാത്രമേയുള്ളൂ.'' എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്താൽ അല്ലാഹു അവനിലേക്ക് മുന്നിടുകയും ആയിരം മലക്കുകൾ അവന് വേണ്ടി പാപമോചനത്തിന് അർത്ഥിക്കുകയും ചെയ്യുന്നതാണ്." (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 401, 401, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمَشَّاءُونَ إِلَى الْمَسَاجِدِ فِي الظُّلَمِ أُولَئِكَ الْخَوَّاضُونَ فِي رحمة الله". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇരുളിൽ പള്ളിയിലേക്ക് നടക്കുന്നവർ, അവരാണ് അല്ലാഹുവിന്റെ കാരുണ്യത്തിൽ പ്രവേശിച്ചവർ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 402, 402, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِيُبَشِّرِ الْمَشَّاءُونَ فِي الظُّلَمِ إِلَى الْمَسَاجِدِ بِنُورٍ تَامٍّ يَوْمَ الْقِيَامَةِ". (د,ت,جه)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ): നബി(സ) പറഞ്ഞു: "ഇരുളിൽ പള്ളിയിലേക്ക് പതിവായി നടക്കുന്നവർ അന്ത്യനാളിൽ തങ്ങൾക്ക് പൂർണ്ണ പ്രകാശം ലഭിക്കുമെന്ന് സന്തോഷിക്കട്ടെ!" (ദ,തു,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 402, 402, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: سمعتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "من توضأً للصلاة فأسبغ الْوُضُوءَ، ثُمَّ مشى إِلَى الصَّلَاةِ الْمَكْتُوبَةِ، فَصَلَّاهَا مَعَ النَّاسِ أَوْ مَعَ الْجَمَاعَةِ أَوْ فِي الْمَسْجِدِ غَفَرَ اللهُ لَهُ ذُنُوبَهُ". (ن)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരാൾ നിസ്കാരത്തിന് വുദു നന്നാക്കിയ (പൂർണ്ണമാക്കിയ) ശേഷം നിർബന്ധ നിസ്കാരത്തിന് നടന്നു പോകുകയും ജനങ്ങളോടൊപ്പം - സംഘമായി - പള്ളിയിൽ വെച്ച് - നിസ്കരിക്കുകയും ചെയ്താൽ അയാളുടെ പാപങ്ങൾ അല്ലാഹു പൊറുത്തുകൊടുക്കും." (ന)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 402, 402, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ – مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى الْعَصْرَ ذَهَبَ إِلَى بَنِي عَبْدِ الْأَشْهَلِ، فَيَتَحَدَّثُ عِنْدَهُمْ حَتَّى يَنْحَدِرَ لِلْمَغْرِبِ، قَالَ أَبُو رَافِعٍ: فَبَيْنَمَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُسْرِعُ إِلَى الْمَغْرِبِ مَرَرْنَا بِالْبَقِيعِ، فَقَالَ: "أُفٍّ لَكَ، أُفٍّ لَكَ". قَالَ: فَكَبُرَ ذَلِكَ فِي ذَرْعِي، فَاسْتَأْخَرْتُ وَظَنَنْتُ أَنَّهُ يُرِيدُنِي، فَقَالَ: "مَا لَكَ، امْشِ". فَقُلْتُ: أَحْدَثْتُ حَدَثًا؟ قَالَ: "مَا ذَاكَ". قُلْتُ: أَفَّفْتَ بِي. قَالَ: "لَا، وَلَكِنْ هَذَا فُلَانٌ بَعَثْتُهُ سَاعِيًا عَلَى بَنِي فُلَانٍ، فَغَلَّ نَمِرَةً، فَدُرِّعَ الْآنَ مِثْلَهَا مِنْ نَارٍ". (ن)', 'നബി(സ)യുടെ ഭൃത്യനായ അബൂറാഫിഅ്(റ): റസൂൽ(സ) അസ്റ് നിസ്കരിച്ചു കഴിഞ്ഞാൽ അബ്ദുൽ അശ്ഹൽ ഗോത്രക്കാരിലേക്ക് പോകുകയും സംസാരിക്കുകയും, മഗ്രിബാകുമ്പോൾ അവിടുന്ന് ഇറങ്ങിപ്പോരുകയും ചെയ്യും. അബൂറാഫിഅ് പറയുന്നു: അങ്ങനെ ഒരിക്കൽ നബി(സ) മഗ്രിബ് നിസ്കരിക്കുവാൻ വേണ്ടി ധൃതിപ്പെട്ട് പോയപ്പോൾ ഞങ്ങൾ ബഖീഇന്റെ അരികിലൂടെ കടന്നുപോയി. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിനക്ക് നാശം, നിനക്ക്നാശം" അദ്ദേഹം പറയുന്നു. എനിക്കതിൽ വലിയ വിഷമം അനുഭവപ്പെട്ടു. അങ്ങനെ ഞാൻ (നടക്കുന്നതിനിടെ) പിന്തിനിന്നു. തിരുമേനി(സ) എന്നെയാണുദ്ദേശിക്കുന്നത് എന്നു ഞാൻ ധരിച്ചു അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിനക്കെന്തുപറ്റി! നടക്കൂ!". ഞാൻ പറഞ്ഞു: തിരുദൂതരേ എന്നിൽ നിന്ന് എന്തെങ്കിലും (പിഴവ്) സംഭവിച്ചിട്ടുണ്ടോ? അവിടുന്ന് ചോദിച്ചു. "എന്താണുണ്ടായത്?". ഞാൻ പറഞ്ഞു: അങ്ങ് എന്നോട് ''നാശം!'' എന്നു പറഞ്ഞുവല്ലോ. തിരുമേനി(സ) പറഞ്ഞു: ഇല്ല, ഇയാൾ ഇന്ന വ്യക്തിയാണ്. ഞാൻ ഇന്ന ഗോത്രത്തിന്റെ സകാത്ത് ശേഖരിക്കാൻ ഇയാളെ നിയോഗിച്ചു. അപ്പോൾ അദ്ദേഹം അതിൽ നിന്നും തേൽവസ്ത്രം വഞ്ചിച്ചെടുത്തു. ഇപ്പോൾ അതിന് സമാനമായ തീകൊണ്ടുള്ള ഒരു അങ്കി അദ്ദേഹത്തിന് അണിയിക്കപ്പെട്ടിരിക്കുന്നു (ന)', 'أَبِي رَافِعٍ', 'നബി(സ)യുടെ ഭൃത്യനായ അബൂറാഫിഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 402, 402, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عن يزيد بن الأسود العامري رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَجَّتَهُ، فَصَلَّيْتُ مَعَهُ صَلَاةَ الصُّبْحِ فِي مَسْجِدِ الخَيْفِ، قَالَ: فَلَمَّا قَضَى صَلَاتَهُ وَانْحَرَفَ إِذَا هُوَ بِرَجُلَيْنِ فِي أُخْرَى الْقَوْمِ لَمْ يُصَلِّيَا مَعَهُ، فَقَالَ: "عَلَيَّ بِهِمَا" فَجِيءَ بِهِمَا، تُرْعَدُ فَرَائِصُهُمَا، فَقَالَ: "مَا مَنَعَكُمَا أَنْ تُصَلِّيَا مَعَنَا؟" فَقَالَا: يَا رَسُولَ اللهِ! إِنَّا كُنَّا قَدْ صَلَّيْنَا فِي رِحَالِنَا، قَالَ: "فَلَا تَفْعَلَا، إِذَا صَلَّيْتُمَا فِي رِحَالِكُمَا ثُمَّ أَتَيْتُمَا مَسْجِدَ جَمَاعَةٍ فَصَلِّيَا مَعَهُمْ، فَإِنَّهَا لَكُمَا نَافِلَةٌ". (د,ت,ن)', 'യസീദുബ്നുൽ അസ്വദിൽ ആമിരി(റ): ഞാൻ നബി(സ)യോടൊപ്പം അവിടുത്തെ ഹജ്ജിൽ പങ്കെടുത്തിരുന്നു. നബിയോടൊപ്പം ഞാൻ ഖൈഫിൽ വെച്ച് സുബ്ഹി നിസ്കരിച്ചു. നബി(സ) യോടൊപ്പം നിസ്കാരം നിർവ്വഹിക്കാത്ത രണ്ട് പേർ തിരുനബി(സ)യുടെ നിസ്കാരം കഴിഞ്ഞപ്പോൾ അവിടെയുണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു: "അവരെ രണ്ട് പേരെയും കൊണ്ടുവരൂ." അവർ ഹാജരാക്കപ്പെട്ടു. ഭയത്താൽ അവരുടെ പിരടികൾ വിറക്കുന്നുണ്ടായിരുന്നു. നബി(സ) ചോദിച്ചു: "ഞങ്ങളോടൊപ്പം നിസ്കരിക്കുന്നതിന് നിങ്ങൾക്കുള്ള തടസ്സം എന്താണ്?" അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! ഞങ്ങൾ യാത്രയിലായിരിക്കെ നിസ്കരിച്ചിട്ടുണ്ട്. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അങ്ങനെ ചെയ്യരുത്. നിങ്ങൾ യാത്രയിൽ നിസ്കരിക്കുകയും പിന്നെ ജമാഅത്ത് നടക്കുന്ന പള്ളിയിൽ എത്തുകയും ചെയ്താൽ നിങ്ങൾ അവരോടൊപ്പം നിസ്കരിക്കുക. അത് നിങ്ങൾക്ക് സുന്നത്ത് നിസ്കാരമായി ഗണിക്കപ്പെടും." (ദ,തു,ന)', 'يزيد بن الأسود العامري', 'യസീദുബ്നുൽ അസ്വദിൽ ആമിരി(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 403, 403, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ وَقَدْ صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَيُّكُمْ يَتَّجِرُ عَلَى هَذَا؟" فَقَامَ رَجُلٌ، فَصَلَّى مَعَهُ. (د,ت)', 'അബൂസഈദ്(റ): നബി(സ) നിസ്കരിച്ച് കഴിഞ്ഞ നേരം ഒരാൾ വന്നു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു. "നിങ്ങളിലാരാണ് ഇദ്ദേഹത്തിന്റെ കൂടെ വ്യാപാരത്തിലേർപ്പെടുക? അപ്പോൾ ഒരാൾ എഴുന്നേറ്റുനിന്ന് അദ്ദേഹത്തിന്റെ കൂടെ നിസ്കരിച്ചു." (ദ,തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 403, 403, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ مِحْجَنِ بْنِ أَبِي مِحْجَنٍ الدِّيلِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ فِي مَجْلِسٍ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَذَّنَ بِالصَّلَاةِ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ رَجَعَ وَمِحْجَنٌ فِي مَجْلِسِهِ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مَنَعَكَ أَنْ تُصَلِّيَ؟ أَلَسْتَ بِرَجُلٍ مُسْلِمٍ؟" قَالَ: بَلَى، وَلَكِنِّي كُنْتُ قَدْ صَلَّيْتُ فِي أَهْلِي، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا جِئْتَ فَصَلِّ مَعَ النَّاسِ وَإِنْ كُنْتَ قَدْ صَلَّيْتَ". (ن)', 'മിഹ്ജനുബ്നു അബീ മിഹ്ജൻ(റ): അദ്ദേഹം നബി(സ)യോടൊപ്പം ഒരു സദസ്സിലായിരിക്കെ ബാങ്ക് വിളിച്ചു. നബി(സ) നിസ്കാരം നിർവ്വഹിച്ച് മടങ്ങിയെത്തിയപ്പോഴും മിഹ്ജൻ ആ സദസ്സിൽ തന്നെയുണ്ട്. പ്രവാചകൻ അദ്ദേഹത്തോട് ചോദിച്ചു: "നീ നിസ്കരിക്കാതിരുന്നത് എന്താണ്? നീ ഒരു മുസ്ലിമല്ലേ?" അദ്ദേഹം പറഞ്ഞു: അതെ! പക്ഷെ ഞാൻ വീട്ടിൽ നിന്നും നിസ്കരിച്ചിരുന്നു. നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നീ ഇവിടെ വന്നാൽ ജനങ്ങളോടൊപ്പം നിസ്കരിക്കുക. നീ നിസ്കാരം നിർവ്വഹിച്ചിട്ടുണ്ടെങ്കിലും." (ന)', 'مِحْجَنِ بْنِ أَبِي مِحْجَنٍ الدِّيلِيِّ', 'മിഹ്ജനുബ്നു അബീ മിഹ്ജൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 403, 403, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ يَزِيدَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: جِئْتُ وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الصَّلَاةِ، فَجَلَسْتُ وَلَمْ أَدْخُلْ مَعَهُمْ فِي الصَّلَاةِ، قَالَ: فَانْصَرَفَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَأَى يَزِيدَ جَالِسًا، فَقَالَ: "أَلَمْ تُسْلِمْ يَا يَزِيدُ؟" قَالَ: بَلَى، يَا رَسُولَ اللهِ! قَدْ أَسْلَمْتُ، قَالَ: "فَمَا مَنَعَكَ أَنْ تَدْخُلَ مَعَ النَّاسِ فِي صَلَاتِهِمْ؟" قَالَ: إِنِّي كُنْتُ قَدْ صَلَّيْتُ فِي مَنْزِلِي، وَأَنَا أَحْسَبُ أَنْ قَدْ صَلَّيْتُمْ، فَقَالَ: "إِذَا جِئْتَ إِلَى الصَّلَاةِ فَوَجَدْتَ النَّاسَ فَصَلِّ مَعَهُمْ، وَإِنْ كُنْتَ قَدْ صَلَّيْتَ، تَكُنْ لَكَ نَافِلَةً وَهَذِهِ مَكْتُوبَةً". (د)', 'യസീദ്ബ്നു ആമിർ(റ): നബി(സ) നിസ്കാരത്തിലായിരിക്കേ ഞാൻ അവിടെ ചെന്നു. അവരോടൊപ്പം നിസ്കാരത്തിൽ ചേരാതെ ഞാൻ അവിടെ ഇരുന്നു. നിസ്കാരശേഷം യസീദ് ഒഴിഞ്ഞുമാറി ഇരിക്കുന്നത് പ്രവാചകൻ(സ) കണ്ടു. പ്രവാചകൻ ചോദിച്ചു: "യസീദ്! നീ ഇസ്ലാമിൽ വിശ്വസിച്ചിട്ടില്ലേ?" യസീദ് പറഞ്ഞു: അതെ! അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ ഇസ്ലാമിൽ വിശ്വസിച്ചിട്ടുണ്ട്. നബി(സ) പറഞ്ഞു: "ജനങ്ങളോടൊപ്പം നിസ്കരിക്കുന്നതിൽ നിന്നും നിന്നെ തടഞ്ഞതെന്താണ്?" യസീദ് പറഞ്ഞു: ഞാൻ വീട്ടിൽ വെച്ച് നിസ്കരിച്ചു. നിങ്ങൾ നിസ്കരിച്ച് കഴിഞ്ഞിരിക്കുമെന്നാണ് ഞാൻ കരുതിയത്. നബി(സ) പറഞ്ഞു: "നീ നിസ്കാര സ്ഥലത്ത് വന്ന് ജനങ്ങളെ കാണുകയാണെങ്കിൽ അവരോടൊപ്പം നിസ്കരിക്കുക. നീ ആദ്യം നിസ്കരിച്ചിട്ടുണ്ടെങ്കിൽ അത് ഐഛികമായും ഇത് നിർബന്ധ നിസ്കാരമായും ഗണിക്കപ്പെടും." (ദ)', 'يَزِيدَ بْنِ عَامِرٍ', 'യസീദ്ബ്നു ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 403, 404, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: وَقَدْ سَأَلَهُ رَجُلٌ فَقَالَ: يُصَلِّي أَحَدُنَا فِي مَنْزِلِهِ الصَّلَاةَ، ثُمَّ يَأْتِي الْمَسْجِدَ وَتُقَامُ الصَّلَاةُ، فَأُصَلِّي مَعَهُمْ، فَأَجِدُ فِي نَفْسِي مِنْ ذَلِكَ شَيْئًا، فَقَالَ أَبُو أَيُّوبَ: سَأَلْنَا عَنْ ذَلِكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "ذلك لَهُ سَهْمُ جَمْعٍ". (د)', 'അബൂഅയ്യൂബൽ അൻസ്വാരി(റ): ഒരാൾ അദ്ദേഹത്തോട് ചോദിച്ചു: ഞങ്ങളിൽ ഒരാൾ വീട്ടിൽ വെച്ച് നിസ്കരിച്ചു. പിന്നെ പള്ളിയിൽ വന്നപ്പോൾ അവിടെ നിസ്കാരം നിർവ്വഹിക്കുന്നുണ്ട്. അപ്പോൾ ഞാനവരുടെ കൂടെയും നിസ്കരിച്ചു. പിന്നീട് എനിക്കതിൽ എന്തോ പ്രയാസം തോന്നി. അപ്പോൾ അബൂഅയ്യൂബ് പറഞ്ഞു: ഞങ്ങൾ ഇത് നബി(സ)യോട് അന്വേഷിച്ചു. അവിടുന്ന് പറഞ്ഞു: "അതവന്ന് രണ്ട് പുണ്യങ്ങൾ ഒന്നിപ്പിച്ചു." (ദ)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബൽ അൻസ്വാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 404, 404, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَضَرَبَ فخذي: "كَيْفَ أَنْتَ إِذَا بَقِيتَ فِي قَوْمٍ يُؤَخِّرُونَ الصَّلَاةَ عَنْ وَقْتِهَا؟" قَالَ: مَا تَأْمُرُ؟ قَالَ: "صَلِّ الصَّلَاةَ لِوَقْتِهَا، ثُمَّ اذْهَبْ لِحَاجَتِكَ، فَإِنْ أُقِيمَتِ الصَّلَاةُ وَأَنْتَ فِي الْمَسْجِدِ فَصَلِّ". (ن)', 'അബൂദർറ്(റ): നബി(സ) എന്റെ തുടയിലടിച്ച് പറഞ്ഞു: "നിസ്കാരം അതിന്റെ സമയത്തിൽ നിന്നും പിന്തിക്കുന്ന ഒരു സമൂഹത്തിൽ നീ അവശേഷിച്ചാൽ നിന്റെ നിലപാടെന്തായിരിക്കും?" ഞാൻ ചോദിച്ചു: അങ്ങെന്താണ് കൽപിക്കുന്നത്? നബി(സ) പറഞ്ഞു: "നീ നിസ്കാരം അതിന്റെ സമയത്ത് നിർവ്വഹിക്കുക. പിന്നെ നിന്റെ കാര്യങ്ങളിൽ ഏർപ്പെടാം. എന്നാൽ നീ പള്ളിയിലുണ്ടായിരിക്കേ ആ നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിക്കപ്പെട്ടാൽ (അവരോടൊപ്പം) നിസ്കരിക്കുക." (ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 404, 404, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'حَدِيثُ عَلَى رَأْسِ مائة سنة تَقَدَّمَ، وَفِي رِوَايَةٍ هُنَا عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ". يُرِيدُ بِذَلِكَ أَنَّهَا تَخْرِمُ ذَلِكَ الْقَرْنَ. (خ)', 'ഇബ്നുഉമർ(റ): ''ഇന്ന് ഭൂ മുഖത്തുള്ള ഒരുത്തനും തന്നെ (അന്ന്) അവശേഷിക്കുകയില്ല'' എന്ന വാക്യം കൊണ്ട് തിരുമേനി(സ) ഉദ്ദേശിച്ചത് നൂറു വർഷത്തിനുള്ളിൽ ഈ തലമുറ മുഴുവനും നശിച്ചു പോകുമെന്നാണ്. (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 404, 404, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=52), 1, 'وَفِي رِوَايَةٍ هُنَا عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ". يُرِيدُ بِذَلِكَ أَنَّهَا تَخْرِمُ ذَلِكَ الْقَرْنَ. (خ)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَبْدِالرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ أَصْحَابَ الصُّفَّةِ كَانُوا أُنَاسًا فُقَرَاءَ، وَأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ كَانَ عِنْدَهُ طَعَامُ اثْنَيْنِ فَلْيَذْهَبْ بِثَالِثٍ وَإِنْ أَرْبَعٌ فَخَامِسٌ أَوْ سَادِسٌ وَأَنَّ أَبَا بَكْرٍ جَاءَ بِثَلَاثَةٍ، فَانطَلَقَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِعَشَرَة قَالَ: فَهُوَ أَنَا وَأَبِي وَأُمِّي، فَلَا أَدْرِي قَالَ وَامْرَأَتِي وَخَادِمٌ بَيْنَنَا وَبَيْنَ بَيْتِ أَبِي بَكْرٍ، وَإِنَّ أَبَا بَكْرٍ تَعَشَّى عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ لَبِثَ حَيْثُ صُلِّيَتِ الْعِشَاءُ ثُمَّ رَجَعَ فَلَبِثَ حَتَّى تَعَشَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ بَعْدَ مَا مَضَى مِنَ اللَّيْلِ مَا شَاءَ اللهُ قَالَتْ لَهُ امْرَأَتُهُ وَمَا حَبَسَكَ عَنْ أَضْيَافِكَ أَوْ قَالَتْ ضَيْفِكَ. قَالَ: أَوَمَا عَشَّيْتِيهِمْ؟ قَالَتْ: أَبَوْا حَتَّى تَجِيءَ قَدْ عُرِضُوا فَأَبَوْا، قَالَ: فَذَهَبْتُ أَنَا فَاخْتَبَأْتُ، فَقَالَ: يَا غُنْثَرُ فَجَدَّعَ وَسَبَّ، وَقَالَ: كُلُوا لَا هَنِيئًا، فَقَالَ: وَاللهِ لَا أَطْعَمُهُ أَبَدًا، وَايْمُ اللهِ مَا كُنَّا نَأْخُذُ مِنْ لُقْمَةٍ إِلَّا رَبَا مِنْ أَسْفَلِهَا أَكْثَرُ مِنْهَا قَالَ: حَتَّى شَبِعُوا وَصَارَتْ أَكْثَرَ مِمَّا كَانَتْ قَبْلَ ذَلِكَ فَنَظَرَ إِلَيْهَا أَبُو بَكْرٍ فَإِذَا هِيَ كَمَا هِيَ أَوْ أَكْثَرُ مِنْهَا فَقَالَ لِامْرَأَتِهِ: يَا أُخْتَ بَنِي فِرَاسٍ مَا هَذَا؟ قَالَتْ: لَا وَقُرَّةِ عَيْنِي لَهِيَ الْآنَ أَكْثَرُ مِنْهَا قَبْلَ ذَلِكَ بِثَلَاثِ مَرَّاتٍ فَأَكَلَ مِنْهَا أَبُو بَكْرٍ، وَقَالَ: إِنَّمَا كَانَ ذَلِكَ مِنَ الشَّيْطَانِ – يَعْنِي يَمِينَهُ – ثُمَّ أَكَلَ مِنْهَا لُقْمَةً ثُمَّ حَمَلَهَا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَصْبَحَتْ عِنْدَهُ، وَكَانَ بَيْنَنَا وَبَيْنَ قَوْمٍ عَقْدٌ فَمَضَى الْأَجَلُ فَفَرَّقْنَا اثْنَا عَشَرَ رَجُلًا مَعَ كُلِّ رَجُلٍ مِنْهُمْ أُنَاسٌ اللهُ أَعْلَمُ كَمْ مَعَ كُلِّ رَجُلٍ فَأَكَلُوا مِنْهَا أَجْمَعُونَ، أَوْ كَمَا قَالَ. (خ)', 'അബൂബക്കറിന്റെ മകൻ അബ്ദുറഹ്മാൻ(റ): പള്ളിയുടെ മുഖമണ്ഡപത്തിൽ താമസമാക്കിയവർ ദരിദ്രരായിരുന്നു. അതുകാരണത്താൽ പ്രവാചകൻ(സ) പ്രസ്താവിച്ചു: വല്ലവരുടെയും പക്കൽ രണ്ടു പേർക്കുള്ള ആഹാരമുണ്ടെങ്കിൽ (ഈ പാവപ്പെട്ടവരിൽ) ഒരാളെ കൂടെ കൊണ്ടു പോകട്ടെ. വല്ലവരുടെയും പക്കൽ നാലാൾക്കുള്ള ഭക്ഷണമുണ്ടങ്കിൽ (ഈ ആളുകളിൽ നിന്നും) അഞ്ചാമതൊരാളെയോ ആറാമതൊരാളെയോ കൂടി കൂടെ കൊണ്ടു പോകട്ടെ. അപ്പോൾ അബൂബക്കർ(റ) മൂന്നു പേരെ കൊണ്ടു പോയി. പ്രവാചകൻ(സ) പത്തു പേരെയും. അബ്ദുറഹ്മാൻ(റ) പറയുന്നു: ഞങ്ങളുടെ കുടുംബത്തിലുണ്ടായിരുന്നത് ഞാനും എന്റെ പിതാവും മാതാവുമായിരുന്നു. ഈ സംഭവം പിന്നീട് റിപ്പോർട്ട് ചെയ്ത നിവേദകൻ പറയുന്നു: ഞങ്ങളുടെ കുടുംബത്തിൽ എന്റെ ഭാര്യയും, എന്റെയും, എന്റെ പിതാവിന്റെയും വീടുകളിൽ ജോലി ചെയ്തു വന്നിരുന്ന ഒരു ഭൃത്യനും ഉണ്ടായിരുന്നു എന്ന് അബ്ദുറഹ്മാൻ (ഹദീസ് റിപ്പോർട്ടർ) പറഞ്ഞോ ഇല്ലയോ എന്ന് എനിക്ക് ഓർമയില്ല.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ سُلَيْمَانَ مَوْلَى مَيْمُونَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ ابْنَ عُمَرَ جَالِسًا عَلَى الْبَلَاطِ وَالنَّاسُ يُصَلُّونَ، قُلْتُ: يَا أَبَا عَبْدِ الرَّحْمَنِ! مَا لَكَ لَا تُصَلِّي؟ قَالَ: إِنِّي قَدْ صَلَّيْتُ، إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تُعَادُ الصَّلَاةُ فِي يَوْمٍ مَرَّتَيْنِ". (د,ن)', 'സുലൈമാൻ(റ): (മൈമൂന(റ)യുടെ മൗല) ജനങ്ങൾ നിസ്കാരം നിർവ്വഹിച്ചുകൊണ്ടിരിക്കേ ഇബ്നുഉമർ കല്ലിന്മേൽ ഇരിക്കുന്നത് ഞാൻ കണ്ടു. ഞാൻ ചോദിച്ചു. അബൂഅബ്ദിർറഹ്മാൻ! എന്താണ് നിങ്ങൾ നിസ്കരിക്കാത്തത്? അദ്ദേഹം പറഞ്ഞു: ഞാൻ നിസ്കരിച്ചിട്ടുണ്ട്. നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ഒരു ദിവസം ഒരു നിസ്കാരം രണ്ടു തവണ ആവർത്തിച്ച് നിർവ്വഹിക്കരുത്."² (ദ,ന)', 'سُلَيْمَانَ مَوْلَى مَيْمُونَةَ', 'സുലൈമാൻ(റ)', '². കാരണമില്ലാതെ ഫർള് നിസ്കാരം മടക്കരുത്. മറ്റൊരാൾക്കോ തനിക്കോ ജമാഅത്ത് കിട്ടുമെങ്കിൽ ഈ ജമാഅത്ത് ലക്ഷ്യം വെച്ചാണ് മടക്കി നിസ്കരിക്കുന്നത്.', null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 406, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وُضِعَ الْعَشَاءُ وَأُقِيمَتِ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ". قَالَ: فَتَعَشَّى ابْنُ عُمَرَ لَيْلَةً وَهُوَ يَسْمَعُ الْإِقَامَةَ. (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "രാത്രി ഭക്ഷണം മുമ്പിൽ തയ്യാറായിരിക്കേ നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിച്ചാൽ ഭക്ഷണം കഴിച്ച് തുടങ്ങുക." ഇഖാമത്ത് കേട്ടു കൊണ്ടിരിക്കെ ഒരു രാത്രി ഇബ്നുഉമർ ആഹാരം കഴിച്ചു. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 406, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قُدِّمَ الْعَشَاءُ فَابْدَءُوا بِهِ قَبْلَ أَنْ تُصَلُّوا صَلَاةَ الْمَغْرِبِ، وَلَا تَعْجَلُوا عَنْ عَشَائِكُمْ". (خ)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "രാത്രി ഭക്ഷണം നിങ്ങളുടെ മുമ്പിലെത്തിയാൽ മഗ്‌രിബ് നിസ്കരിക്കുന്നതിനു മുമ്പ് നിങ്ങൾക്കത് ഭക്ഷിക്കാം. ഭക്ഷണം കഴിക്കാതെ നിസ്കരിക്കാൻ നിങ്ങൾ ധൃതി കാണിക്കേണ്ടതില്ല." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 406, 406, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَبْدِ اللهِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ: كَانَ يَؤُمُّ أَصْحَابَهُ، فَحَضَرَتِ الصَّلَاةُ يَوْمًا فَذَهَبَ لِحَاجَتِهِ، ثُمَّ رَجَعَ، فَقَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا وَجَدَ أَحَدُكُمُ الْغَائِطَ فَلْيَبْدَأْ بِهِ قَبْلَ الصَّلَاةِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അർഖം(റ): അദ്ദേഹം തന്റെ ആളുകൾക്ക് ഇമാം നിൽക്കാറുണ്ടായിരുന്നു. ഒരു ദിവസം നിസ്കാര സമയമായപ്പോൾ അദ്ദേഹം തന്റെ പ്രാഥമിക കർമ്മം നിർവ്വഹിക്കാൻപോയി. തിരിച്ചു വന്നശേഷം പറഞ്ഞു. നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "നിങ്ങളിലാർക്കെങ്കിലും വിസർജ്ജനത്തിന് ആവശ്യം വന്നാൽ നിസ്കാരത്തിന് മുമ്പ് അവൻ അത് നിർവ്വഹിക്കട്ടെ." (ന)', 'عَبْدِ اللهِ بْنِ أَرْقَمَ', 'അബ്ദുല്ലാഹിബ്നു അർഖം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 406, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أُسَامَةَ وَالِدِ أَبِي الْمَلِيحِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِحُنَيْنٍ، فَأَصَابَنَا مَطَرٌ، فَنَادَى مُنَادِي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنْ صَلُّوا فِي رِحَالِكُمْ". (ن)', 'അബുൽമലീഹിന്റെ പിതാവ് ഉസാമഃ(റ): ഞങ്ങൾ നബിയോടൊപ്പം ഹുനൈനിലായിരുന്നു. (അവിടെ) ഞങ്ങളെ മഴ ബാധിച്ചു. അപ്പോൾ റസൂലിന്റെ അറിയിപ്പുകാരൻ വിളിച്ചു പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ തമ്പുകളിൽ തന്നെ നിസ്കരിച്ചു കൊള്ളുക." (ന)', 'أُسَامَةَ وَالِدِ أَبِي الْمَلِيحِ', 'അബുൽമലീഹിന്റെ പിതാവ് ഉസാമഃ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَقَدْ رَأَيْتُنَا وَمَا يَتَخَلَّفُ عَنِ الصَّلَاةِ إِلَّا مُنَافِقٌ قَدْ عُلِمَ نِفَاقُهُ أَوْ مَرِيضٌ، إِنْ كَانَ الْمَرِيضُ لَيَمْشِي بَيْنَ رَجُلَيْنِ حَتَّى يَأْتِيَ الصَّلَاةَ، وَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَّمَنَا سُنَنَ الْهُدَى، وَإِنَّ مِنْ سُنَنِ الْهُدَى الصَّلَاةَ فِي الْمَسْجِدِ الَّذِي يُؤَذَّنُ فِيهِ. (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നിസ്കാരം (ജമാഅത്തായി) നിർവ്വഹിക്കുന്നതിൽ നിന്ന് അറിയപ്പെട്ട കപടനോ രോഗിയോ അല്ലാതെ പിന്തുകയില്ല എന്നാണ് ഞങ്ങളുടെ അനുഭവം. രോഗി തന്നെയും രണ്ടാളുകൾക്കിടയിൽ നിന്ന് നിസ്കാരത്തിന് നടന്ന് വരുമായിരുന്നു. തീർച്ചയായും അല്ലാഹുവിന്റെ ദൂതർ ഞങ്ങളെ പഠിപ്പിച്ചത് സന്മാർഗ്ഗ ചര്യകളാണ്. നിശ്ചയം, ബാങ്ക് വിളിക്കുന്ന പള്ളിയിൽ പോയി നിസ്കരിക്കുക എന്നതും സന്മാർഗ്ഗ ചര്യകളിൽ പെട്ടതാണ്. (മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ خَطَبَ النَّاسَ فِي يَوْمِ ذِي رَدْغٍ، فَأَمَرَ الْمُؤَذِّنَ. لَمَّا بَلَغَ ''حَيَّ عَلَى الصَّلَاةِ'' قَالَ: قُلِ: الصَّلَاةُ فِي الرِّحَالِ، فَنَظَرَ بَعْضُهُمْ إِلَى بَعْضٍ، فَكَأَنَّهُمْ أَنْكَرُوا. فَقَالَ: كَأَنَّكُمْ أَنْكَرْتُمْ هَذَا؟ إِنَّ هَذَا فَعَلَهُ مَنْ هُوَ خَيْرٌ مِنِّي – يَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – إِنَّهَا عَزْمَةٌ، وَإِنِّي كَرِهْتُ أَنْ أُحْرِجَكُمْ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): മഴയും ചെളിയുമുള്ള ഒരു ദിവസം അദ്ദേഹം പ്രസംഗിച്ചു. ബാങ്ക് വിളിക്കുന്നവനോട് ''ഹയ്യഅലസ്സ്വലാത്'' എന്നെത്തിയാൽ ''നിസ്കാരം തമ്പുകളിലാണ്'' എന്നു പറയാൻ കൽപിച്ചു. അപ്പോൾ ഇതു നിരാകരിച്ചപോലെ ആളുകൾ പരസ്പരം നോക്കി. അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ ഇതു നിരാകരിച്ച പോലെയുണ്ടല്ലോ! എന്നെക്കാൾ ഉത്തമനായ മുഹമ്മദ് നബി(സ) ചെയ്ത കാര്യമാണിത്. അതൊരു നിർബന്ധ ബാധ്യതയാണ്, നിങ്ങളെ ബുദ്ധിമുട്ടിക്കാൻ ഞാനിഷ്ടപ്പെടുന്നില്ല. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: قَالَ رَجُلٌ مِنَ الْأَنْصَارِ: إِنِّي لَا أَسْتَطِيعُ الصَّلَاةَ مَعَكَ. وَكَانَ رَجُلًا ضَخْمًا، فَصَنَعَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ طَعَامًا، فَدَعَاهُ إِلَى مَنْزِلِهِ فَبَسَطَ لَهُ حَصِيرًا، وَنَضَحَ طَرَفَ الْحَصِيرِ، فَصَلَّى عَلَيْهِ رَكْعَتَيْنِ. فَقَالَ رَجُلٌ مِنْ آلِ الْجَارُودِ لِأَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الضُّحَى؟ قَالَ: مَا رَأَيْتُهُ صَلَّاهَا إِلَّا يَوْمَئِذٍ. (خ)', 'അനസുബ്നു മാലിക്(റ): അൻസ്വാരികളിൽപ്പെട്ട ഒരാൾ പറഞ്ഞു: ''താങ്കൾക്കൊപ്പം പള്ളിയിൽ ജമാഅത്തിൽ പങ്കെടുക്കാൻ എനിക്കു സാധിക്കില്ല''. അദ്ദേഹം തടിച്ച ഒരാളായിരുന്നു. അങ്ങനെ അദ്ദേഹം നബി(സ)ക്കു ഭക്ഷണമുണ്ടാക്കുകയും, നബി(സ)യെ വീട്ടിലേക്കു ക്ഷണിക്കുകയും ചെയ്തു. നബി(സ)ക്ക് ഒരു പായ വിരിച്ചു കൊടുക്കുകയും പായയുടെ അറ്റം നനക്കുകയും ചെയ്തു. നബി(സ) അതിൽ രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. ജാറൂദ് കുടുംബത്തിൽപെട്ട ഒരാൾ അനസി(റ)നോട് ചോദിച്ചു: നബി(സ) ളുഹാ നിസ്കരിക്കാറുണ്ടായിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: ആ ദിവസമല്ലാതെ നബി(സ) ളുഹാ നിസ്കരിച്ചത് ഞാൻ കണ്ടിട്ടില്ല. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 407, 407, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا سُئِلَتْ: مَا كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ فِي بَيْتِهِ؟ قَالَتْ: كَانَ يَكُونُ فِي مِهْنَةِ أَهْلِهِ – تَعْنِي خِدْمَةَ أَهْلِهِ – فَإِذَا حَضَرَتِ الصَّلَاةُ خَرَجَ إِلَى الصَّلَاةِ. (خ)', 'ആഇശ(റ): നബി(സ) വീട്ടിൽ എന്താണ് ചെയ്യാറുണ്ടായിരുന്നത് എന്നു ചോദിക്കപ്പെട്ടപ്പോൾ അവർ പറഞ്ഞു: നബി(സ) കുടുംബ ജോലികൾ ചെയ്തിരുന്നു. നിസ്കാര സമയമാവുമ്പോൾ നിസ്കാരത്തിനു പുറപ്പെടും. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 408, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا مَرِضَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَضَهُ الَّذِي مَاتَ فِيهِ، فَحَضَرَتِ الصَّلَاةُ فَأُذِّنَ، فَقَالَ: "مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ". فَقِيلَ لَهُ: إِنَّ أَبَا بَكْرٍ رَجُلٌ أَسِيفٌ، إِذَا قَامَ فِي مَقَامِكَ لَمْ يَسْتَطِعْ أَنْ يُصَلِّيَ بِالنَّاسِ. وَأَعَادَ، فَأَعَادُوا لَهُ، فَأَعَادَ الثَّالِثَةَ فَقَالَ: "إِنَّكُنَّ صَوَاحِبُ يُوسُفَ، مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ". فَخَرَجَ أَبُو بَكْرٍ فَصَلَّى، فَوَجَدَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ نَفْسِهِ خِفَّةً، فَخَرَجَ يُهَادَى بَيْنَ رَجُلَيْنِ، كَأَنِّي أَنْظُرُ رِجْلَيْهِ تَخُطَّانِ مِنَ الْوَجَعِ. فَأَرَادَ أَبُو بَكْرٍ أَنْ يَتَأَخَّرَ، فَأَوْمَأَ إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ مَكَانَكَ. ثُمَّ أُتِيَ بِهِ حَتَّى جَلَسَ إِلَى جَنْبِهِ. قِيلَ لِلْأَعْمَشِ: وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي وَأَبُو بَكْرٍ يُصَلِّي بِصَلَاتِهِ، وَالنَّاسُ يُصَلُّونَ بِصَلَاةِ أَبِي بَكْرٍ. فَقَالَ بِرَأْسِهِ: نَعَمْ. وَفِي رِوَايَةٍ: جَلَسَ عَنْ يَسَارِ أَبِي بَكْرٍ، فَكَانَ أَبُو بَكْرٍ يُصَلِّي قَائِمًا. (خ)', 'ആഇശ(റ): നബി(സ)ക്ക് മരണരോഗം ബാധിച്ച സമയത്ത് നിസ്കാര സമയമാവുകയും ബാങ്കു വിളിക്കുകയും ചെയ്തപ്പോൾ നബി(സ) പറഞ്ഞു: "അബൂബക്കറിനോട് ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കാൻ കൽപിക്കൂ." അപ്പോൾ ആരോ പറഞ്ഞു: അബൂബക്കർ മൃദുല ഹൃദയനാണ്, താങ്കളുടെ സ്ഥാനത്ത് നിന്നാൽ അദ്ദേഹത്തിന് നിസ്കരിക്കാൻ സാധിക്കില്ല. നബി(സ) തന്റെ വാക്കുകൾ ആവർത്തിച്ചപ്പോൾ ജനങ്ങളും ഇക്കാര്യം ആവർത്തിച്ചു. മൂന്നാമതും ആവർത്തിച്ചു കൊണ്ട് നബി(സ) പറഞ്ഞു: "നിങ്ങൾ യൂസുഫ് നബി(അ)യെ (കെണിയിൽ അകപ്പെടുത്താൻ ശ്രമിച്ച സ്ത്രീകളുടെ) കൂട്ടുകാരികളാണ്. അബൂബക്കറിനോട് ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കാൻ പറയൂ." അങ്ങനെ അബൂബക്കർ(റ) വന്ന് നിസ്കരിച്ചു. നബി(സ)ക്ക് ചെറിയ ആശ്വാസം തോന്നിയപ്പോൾ രണ്ടാളുകളുടെ സഹായത്തോടെ നബി(സ) പുറപ്പെട്ടു. വേദനകൊണ്ട് നബി(സ)യുടെ രണ്ട് കാലുകളും നിലത്തുറപ്പിക്കാൻ സാധിക്കാത്ത അവസ്ഥ ഞാൻ ഇപ്പോഴും കാണുന്ന പോലെയുണ്ട്. അപ്പോൾ അബൂബക്കർ(റ) ഇമാമിന്റെ സ്ഥാനത്തു നിന്ന് പിന്മാറാനുദ്ദേശിച്ചപ്പോൾ നബി(സ) ആംഗ്യത്തിലൂടെ അവിടെത്തന്നെ നിൽക്കാൻ പറഞ്ഞു. പിന്നെ നബി(സ)യെ കൊണ്ടുവരികയും, തിരുമേനി(സ) അബൂബക്കറിന്റെ ഒരു വശത്ത് ഇരിക്കുകയും ചെയ്തു. നബി(സ) നിസ്കരിച്ചു കൊണ്ടിരിന്നു, അബൂബക്കറും(റ) നിസ്കാരം തുടർന്നു. ജനങ്ങൾ അബൂബക്കറിന്റെ നിസ്കാരത്തെ പിൻതുടർന്നാണ് നിസ്കരിച്ചിരുന്നത്. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) അബൂബക്കറിന്റെ ഇടതുവശത്ത് ഇരുന്നു. അബൂബക്കർ നിന്ന് നിസ്കരിക്കുകയായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 408, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=63), 1, 'وَفِي رِوَايَةٍ: جَلَسَ عَنْ يَسَارِ أَبِي بَكْرٍ، فَكَانَ أَبُو بَكْرٍ يُصَلِّي قَائِمًا. (خ)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) അബൂബക്കറിന്റെ ഇടതുവശത്ത് ഇരുന്നു. അബൂബക്കർ നിന്ന് നിസ്കരിക്കുകയായിരുന്നു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا ثَقُلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَاشْتَدَّ وَجَعُهُ اسْتَأْذَنَ أَزْوَاجَهُ أَنْ يُمَرَّضَ فِي بَيْتِي، فَأَذِنَّ لَهُ. (خ)', 'ആഇശ(റ): രോഗ സമയത്ത് നബി(സ)ക്ക് പ്രയാസം തോന്നുകയും വേദന അനുഭവപ്പെടുകയും ചെയ്തപ്പോൾ എന്റെ വീട്ടിൽ കിടന്നു പരിചരിക്കപ്പെടാൻ തന്നെ അനുവദിക്കണമെന്ന് മറ്റു ഭാര്യമാരോട് അവിടുന്ന് സമ്മതം തേടി. അവർ അതിനു സമ്മതിച്ചു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 408, 408, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُمْتُ عَنْ يَسَارِهِ، فَأَخَذَنِي بِيَدِهِ الْيُسْرَى، فَأَقَامَنِي عَنْ يَمِينِهِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ നബി(സ)യോടൊപ്പം നിസ്കരിച്ചു. ഞാൻ അവിടുത്തെ ഇടതു ഭാഗത്തു നിന്നു. അപ്പോൾ നബി(സ) ഇടതുകൈ കൊണ്ട് എന്നെ പിടിച്ച് വലതു ഭാഗത്തേക്ക് നിർത്തി. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى أُمِّ حَرَامٍ، فَأَتَوْهُ بِسَمْنٍ وَتَمْرٍ، فَقَالَ: "رُدُّوا هَذَا فِي وِعَائِهِ، وَهَذَا فِي سِقَائِهِ، فَإِنِّي صَائِمٌ". ثُمَّ قَامَ فَصَلَّى بِنَا رَكْعَتَيْنِ تَطَوُّعًا، أَقَامَنِي عَنْ يَمِينِهِ عَلَى بِسَاطٍ، فَقَامَتْ أُمُّ سُلَيْمٍ وَأُمُّ حَرَامٍ خَلْفَنَا. (د)', 'അനസ്(റ): നബി(സ) ഉമ്മു ഹറാമിന്റെ വീട്ടിൽ ചെന്നു. അവർ അദ്ദേഹത്തിന് കാരക്കയും വെണ്ണയും നൽകി. നബി(സ) പറഞ്ഞു: "അവ അവയുടെ പാത്രങ്ങളിൽ തന്നെ വെക്കുക. ഞാൻ നോമ്പുകാരനാണ്." പിന്നെ എഴുന്നേറ്റ് ഞങ്ങളേയും കൂട്ടി രണ്ട് റക്അത്ത് സുന്നത്ത് നിസ്കരിച്ചു. വിരിപ്പിൽ എന്നെ അദ്ദേഹത്തിന്റെ വലതു ഭാഗത്ത് നിർത്തി. ഉമ്മുസുലൈമും ഉമ്മുഹറാമും ഞങ്ങളുടെ പിന്നിലും നിന്നു. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا يُحَدِّثُ عَنْ مَبِيتِهِ فِي بَيْتِ خَالَتِهِ قَالَ: ثُمَّ نَامَ حَتَّى نَفَخَ، وَكَانَ إِذَا نَامَ نَفَخَ، ثُمَّ أَتَاهُ الْمُؤَذِّنُ فَخَرَجَ، فَصَلَّى. وَلَمْ يَتَوَضَّأْ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഇബ്നുഅബ്ബാസ്(റ) ഇളയുമ്മയുടെ വീട്ടിൽ രാത്രി താമസിച്ച സംഭവം വിവരിച്ചു കൊണ്ട് പറയുന്നു: പിന്നെ നബി(സ) ഉറങ്ങുകയും കൂർക്കം വലിക്കുകയും ചെയ്തു. നബി(സ) ഉറങ്ങിയാൽ കൂർക്കം വലിക്കാറുണ്ടായിരുന്നു. പിന്നീട് നബി(സ)യുടെ അടുത്ത് ബാങ്കു വിളിക്കുന്നയാൾ ചെന്നു. അപ്പോൾ നബി(സ) പുറത്തു വരികയും, വുദു ചെയ്യാതെ നിസ്കരിക്കുകയും ചെയ്തു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَّهُ وَامْرَأَةً مِنْهُمْ، فَجَعَلَهُ عَنْ يَمِينِهِ وَالْمَرْأَةَ خَلْفَ ذَلِكَ. (م,د,ن,جه)', 'അനസ്(റ): നബി(സ) അദ്ദേഹത്തി(അനസി)നും അവരിൽപ്പെട്ട ഒരു സ്ത്രീക്കും ഇമാമായി നിസ്കരിച്ചു. എന്നെ നബി(സ)യുടെ വലതു ഭാഗത്തും സ്ത്രീയെ അതിനു പിന്നിലും നിർത്തി. (മു,ദ,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بِتُّ فِي بَيْتِ خَالَتِي مَيْمُونَةَ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ، فَأَطْلَقَ الْقِرْبَةَ، فَتَوَضَّأَ، ثُمَّ أَوْكَأَ الْقِرْبَةَ، ثُمَّ قَامَ إِلَى الصَّلَاةِ، فَقُمْتُ، فَتَوَضَّأْتُ كَمَا تَوَضَّأَ، ثُمَّ جِئْتُ فَقُمْتُ عَنْ يَسَارِهِ، فَأَخَذَنِي بِيَمِينِهِ، فَأَدَارَنِي مِنْ وَرَائِهِ فَأَقَامَنِي عَنْ يَمِينِهِ، فَصَلَّيْتُ مَعَهُ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): എന്റെ മാതൃസഹോദരി മൈമൂനയുടെ വീട്ടിൽ ഞാൻ താമസിച്ച ദിവസം നബി(സ) രാത്രി എഴുന്നേറ്റ് തോൽപാത്രം അഴിച്ച് വുദു ചെയ്തു. പാത്രം കെട്ടിവെച്ച ശേഷം നിസ്കരിക്കാൻ നിന്നു. ഞാൻ എഴുന്നേറ്റ് പ്രവാചകൻ(സ) ചെയ്തതു പോലെ വുദു ചെയ്ത് പ്രവാചകന്റെ ഇടതുഭാഗത്ത് നിന്നു. അപ്പോൾ പ്രവാചകൻ(സ) എന്നെ വലത്കൈ കൊണ്ട് പിടിച്ച് പിന്നിലൂടെ വലതു ഭാഗത്ത് നിറുത്തി. അങ്ങനെ ഞാൻ നബി(സ)യോടൊപ്പം നിസ്കരിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 409, 409, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اثْنَانِ فَمَا فَوْقَهُمَا جَمَاعَةٌ". (جه)', 'അബൂമൂസൽ അശ്അരി(റ): നബി(സ) പറഞ്ഞു: "രണ്ടും (രണ്ടു പേർ ചേർന്ന് നിസ്കരിച്ചാലും) അതിനുമുകളിലും (അതിൽ കൂടുതൽ പേർ ചേർന്ന് നിസ്കരിച്ചാലും) ജമാഅത്ത് (സംഘടിതം) തന്നെയാണ്." (ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 409, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الْمَغْرِبَ، فَجِئْتُ فَقُمْتُ عَنْ يَسَارِهِ، فَأَقَامَنِي عَنْ يَمِينِهِ. (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) മഗ്‌രിബ് നിസ്കരിക്കുകയായിരുന്നു. ഞാൻ ചെന്ന് നബിയുടെ ഇടതുഭാഗത്ത് നിന്നു. അദ്ദേഹം എന്നെ വലതുഭാഗത്തേക്ക് മാറ്റി നിർത്തി. (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: سَقَطَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ فَرَسٍ، فَجُحِشَ شِقُّهُ الْأَيْمَنُ، فَدَخَلْنَا عَلَيْهِ نَعُودُهُ، فَحَضَرَتِ الصَّلَاةُ، فَصَلَّى بِنَا قَاعِدًا، فَصَلَّيْنَا وَرَاءَهُ قُعُودًا، فَلَمَّا قَضَى الصَّلَاةَ قَالَ: "إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا سَجَدَ فَاسْجُدُوا، وَإِذَا رَفَعَ فَارْفَعُوا، وَإِذَا قَالَ سَمِعَ اللهُ لِمَنْ حَمِدَهُ فَقُولُوا: رَبَّنَا وَلَكَ الْحَمْدُ، وَإِذَا صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا أَجْمَعِينَ". (م,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) കുതിരപ്പുറത്തു നിന്ന് വീണ് വലതുവശത്ത് മുറിവ് പറ്റിയപ്പോൾ ഞങ്ങൾ സന്ദർശിക്കാൻ ചെന്നു. നിസ്കാര സമയമായപ്പോൾ നബി(സ) ഞങ്ങൾക്ക് ഇമാമായി ഇരുന്ന് നിസ്കരിച്ചു. പിന്നിൽ ഞങ്ങളും ഇരുന്ന് നിസ്കരിച്ചു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇമാം തുടരപ്പെടേണ്ടവനാണ്. ഇമാം തക്ബീർ ചൊല്ലിയാൽ നിങ്ങളും ചൊല്ലുക. സുജൂദ് ചെയ്താൽ നിങ്ങളും സുജൂദ് ചെയ്യുക. ഉയർന്നാൽ നിങ്ങളും ഉയരുക. ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്ന് ഇമാം പറഞ്ഞാൽ നിങ്ങൾ ''റബ്ബനാ വലകൽ ഹംദു'' എന്ന് പറയുക. അദ്ദേഹം ഇരുന്ന് നിസ്കരിച്ചാൽ നിങ്ങളെല്ലാവരും ഇരുന്ന് നിസ്കരിക്കുക." (മു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّهُمْ كَانُوا يُصَلُّونَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا رَكَعَ رَكَعُوا، وَإِذَا قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ". لَمْ نَزَلْ قِيَامًا حَتَّى يَرَوْهُ قَدْ وَضَعَ جَبْهَتَهُ بِالْأَرْضِ، ثُمَّ يَتْبَعُونَهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ن)', 'ബറാഅ്(റ): അവർ (തിരുമേനിയുടെ അനുചന്മാർ) പ്രവാചക(സ)ന്റെ കൂടെ നിസ്കരിക്കും. തിരുമേനി(സ) റുകൂഅ് ചെയ്താൽ അവരും റുകൂഅ് ചെയ്യും. തിരുമേനി(സ) ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' (അല്ലാഹുവിനെ സ്തുതിച്ചവനുവേണ്ടി അല്ലാഹു കേൾക്കട്ടെ) എന്ന് പറഞ്ഞാൽ അവിടുന്ന് തന്റെ നെറ്റിത്തടം നിലത്തു വെക്കും വരെ ഞങ്ങൾ (അനുചരന്മാർ) നിർത്തത്തിൽ തന്നെയായിരിക്കും. പിന്നെ തിമേനി(സ)യെ പിൻതുടരും (മു,ദ,ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 410, 410, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ جَدَّتَهُ مُلَيْكَةَ دَعَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِطَعَامٍ صَنَعَتْهُ، فَأَكَلَ مِنْهُ، ثُمَّ قَالَ: "قُومُوا، فَلِأُصَلِّيَ لَكُمْ". قَالَ أَنَسٌ: فَقُمْتُ إِلَى حَصِيرٍ لَنَا قَدِ اسْوَدَّ مِنْ طُولِ مَا لُبِسَ، فَنَضَحْتُهُ بِمَاءٍ، فَقَامَ عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَصَفَفْتُ أَنَا وَالْيَتِيمُ وَرَاءَهُ، وَالْعَجُوزُ مِنْ وَرَائِنَا، فَصَلَّى لَنَا رَكْعَتَيْنِ، ثُمَّ انْصَرَفَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ق,د,ت,ن)', 'അനസ്ബ്നു മാലിക്(റ): അദ്ദേഹത്തിന്റെ വല്യുമ്മ മുലൈക നബി(സ)യെ സദ്യക്ക് ക്ഷണിച്ചു. ഭക്ഷണ ശേഷം നബി(സ) പറഞ്ഞു: "എഴുന്നേൽക്കൂ. ഞാൻ നിങ്ങൾക്കുവേണ്ടി നിസ്കരിക്കാം." ഉടൻ ഞാനൊരു പായ എടുക്കാൻ പോയി. ദീർഘകാലം ഉപയോഗിച്ചതിനാൽ അത് കറുത്തുപോയിരുന്നു. ഞാനത് വെള്ളം കൊണ്ട് തുടച്ചു. നബി(സ) അതിൽ നിസ്കരിക്കാൻ നിന്നു. ഞാനും ഒരു അനാഥ ബാലനും നബിയുടെ പിന്നിൽ അണി നിന്നു. വല്യുമ്മ ഞങ്ങളുടെ പിന്നിലും. നബി(സ) ഞങ്ങൾക്കായി രണ്ട് റക്അത്ത് നിസ്കരിച്ച് പിരിഞ്ഞു. (ബു,മു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 410, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ: اسْتَأْذَنَ عَلْقَمَةُ وَالْأَسْوَدُ عَلَى عَبْدِ اللهِ، وَقَدْ كُنَّا أَطَلْنَا الْقُعُودَ عَلَى بَابِهِ، فَخَرَجَتِ الْجَارِيَةُ فَاسْتَأْذَنَتْ لَهُمَا، فَأَذِنَ لَهُمَا، ثُمَّ قَامَ فَصَلَّى بَيْنِي وَبَيْنَهُ، ثُمَّ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَعَلَ. (د,ن)', 'അസ്വദ്(റ): അൽഖമയും അസ്വദും അബ്ദുല്ലാഹിബ്നു മസ്ഊദിനോട് പ്രവേശനാനുമതി ചോദിച്ചു. (അവർ പറയുന്നു) ഞങ്ങൾ ദീർഘനേരം അദ്ദേഹത്തിന്റെ വാതിലിനടുത്ത് ഇരുന്നു. അപ്പോൾ പരിചാരിക പുറത്ത് വന്നു. അവൾ അവർക്കു വേണ്ടി അനുവാദം ചോദിച്ചു. അദ്ദേഹം അവർക്ക് അനുവാദം നൽകി. പിന്നെ എന്റെയും അദ്ദേഹത്തിന്റെയും ഇടയിൽ നിന്ന് നിസ്കരിച്ച ശേഷം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ,ന)', 'الْأَسْوَدِ', 'അസ്വദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ إِلَى جَنْبِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَائِشَةُ خَلْفَنَا تُصَلِّي مَعَنَا وَأَنَا إِلَى جَنْبِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُصَلِّي مَعَهُ. (ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ നബി(സ)യോടൊപ്പം നിസ്കരിച്ചു. ഞാൻ നബി(സ)യുടെ അരികിലും ആഇശ(റ) ഞങ്ങളുടെ പിന്നിലും നിന്ന് നിസ്കരിച്ചു. (ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ مَسْعُودِ بْنِ هُبَيْرَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ بِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ، فَقَالَ لِي أَبُو بَكْرٍ: يَا مَسْعُودُ! ائْتِ أَبَا تَمِيمٍ – يَعْنِي مَوْلَاهُ – فَقُلْ لَهُ يَحْمِلْنَا عَلَى بَعِيرٍ، وَيَبْعَثْ إِلَيْنَا بِزَادٍ، وَدَلِيلٍ يَدُلُّنَا، فَجِئْتُ إِلَى مَوْلَايَ فَأَخْبَرْتُهُ، فَبَعَثَ مَعِي بِبَعِيرٍ وَوَطْبٍ مِنْ لَبَنٍ، فَجَعَلْتُ آخُذُ بِهِمْ فِي إِخْفَاءِ الطَّرِيقِ، وَحَضَرَتِ الصَّلَاةُ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَقَامَ أَبُو بَكْرٍ عَنْ يَمِينِهِ، وَقَدْ عَرَفْتُ الْإِسْلَامَ وَأَنَا مَعَهُمَا، فَجِئْتُ فَقُمْتُ خَلْفَهُمَا، فَدَفَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَدْرِ أَبِي بَكْرٍ، فَقُمْنَا خَلْفَهُ. (ن)', 'മസ്ഊദുബ്നു ഹുബൈറഃ(റ): നബി(സ)യും അബൂബക്കറും(റ) എന്റെ അടുത്തുകൂടെ നടന്നു. അപ്പോൾ അബൂബക്കർ(റ) എന്നോട് പറഞ്ഞു: മസ്ഊദ്! നീ അബൂതമീമിനെ കൊണ്ടുവരൂ! ഒട്ടകപ്പുറത്ത് ഞങ്ങളെ നയിക്കാൻ അവനോട് പറയൂ! അവൻ ഞങ്ങൾക്കാവശ്യമായ ഭക്ഷണം കൊണ്ട് വരും. ഞങ്ങൾക്ക് വഴികാട്ടിയുമാകും. ഞാൻ എന്റെ അടിമയുടെ അടുത്ത് ചെന്ന് വിവരം പറഞ്ഞു. എന്റെ കൂടെ ഒരൊട്ടകവും പാൽപാത്രവും അയച്ചു. ഞാൻ അവരെ വഴിയിൽ കണ്ടുമുട്ടി. അപ്പോൾ നിസ്കാരത്തിന് സമയമായിരുന്നു. നബി(സ) നിസ്കരിക്കാൻ നിന്നു. അബൂബക്കർ(റ) നബി(സ)യുടെ വലതു ഭാഗത്തും നിന്നു. ഞാൻ ഇവരോടൊപ്പമുണ്ടായിരിക്കേയാണ് ഇസ്ലാമിനെ മനസ്സിലാക്കുന്നത്. ഞാൻ വന്ന് അവരുടെ പിന്നിൽ നിന്നു. അപ്പോൾ നബി(സ) അബൂബക്കറിന്റെ നെഞ്ചിൽ തള്ളി. ഞങ്ങൾ പ്രവാചക(സ)ന്റെ പിന്നിലേക്ക് മാറിനിന്നു. (ന)', 'مَسْعُودِ بْنِ هُبَيْرَةَ', 'മസ്ഊദുബ്നു ഹുബൈറഃ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 411, 411, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ هُوَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأُمُّهُ وَخَالَتُهُ، فَصَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَ أَنَسًا عَنْ يَمِينِهِ، وَأُمُّهُ وَخَالَتُهُ خَلْفَهُمَا. (ن)', 'അനസ്(റ): അദ്ദേഹവും മാതാവും മാതൃസഹോദരിയും നബി(സ)യോടൊപ്പം നിസ്കരിക്കുകയായിരുന്നു. അപ്പോൾ അനസിനെ വലതുഭാഗത്ത് നിർത്തി. അദ്ദേഹത്തിന്റെ ഉമ്മയെയും മാതൃസഹോദരിയെയും പിന്നിലും നിർത്തി. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 411, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: اشْتَكَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَلَّيْنَا وَرَاءَهُ وَهُوَ قَاعِدٌ، وَأَبُو بَكْرٍ يُكَبِّرُ لِيُسْمِعَ النَّاسَ تَكْبِيرَهُ،..... ثُمَّ سَاقَ الْحَدِيثَ. (م,د,ن,جه)', 'ജാബിർ(റ): പ്രവാചക(സ)ന് രോഗം പിടിപെട്ട സന്ദർഭത്തിൽ അവിടുന്ന് ഇരുന്ന് നിസ്കരിച്ചപ്പോൾ ഞങ്ങൾ തിരുമേനിക്ക് പിന്നിൽ നിസ്കരിച്ചു. അബൂബക്കർ(റ) ജനങ്ങൾ പ്രവാചകന്റെ തക്ബീർ കേൾക്കാൻ വേണ്ടി ഉച്ചത്തിൽ തക്ബീർ ചെല്ലുന്നുണ്ടായിരുന്നു..... ഹദീസ് തുടർന്നു..... (മു,ദ,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أُسَيْدِ بْنِ حُضَيْرٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يَؤُمُّهُمْ، قَالَ: فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُهُ، فَقَالُوا: يَا رَسُولَ اللهِ إِنَّ إِمَامَنَا مَرِيضٌ؟ فَقَالَ: "إِذَا صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا". قَالَ أَبُو دَاوُدَ: وَهَذَا الْحَدِيثُ لَيْسَ بِمُتَّصِلٍ. (د)', 'ഉസൈദുബ്നു ഹുളൈർ(റ): അദ്ദേഹം തന്റെ ജനതക്ക് (നിസ്കാരത്തിന്) നേതൃത്വം നൽകി. അങ്ങനെ (അദ്ദേഹത്തിന് രോഗം പിടിപ്പെട്ടപ്പോൾ) തിരുമേനി(സ) അദ്ദേഹത്തിന്റെ രോഗവിവരമറിയാൻ അദ്ദേഹത്തെ സന്ദർശിച്ചു. അദ്ദേഹത്തിന്റെ ജനത തിരുമേനി(സ)യോടു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! ഞങ്ങളുടെ ഇമാം രോഗബാധിതനാണ്. തിരുമേനി(സ) പറഞ്ഞു: അദ്ദേഹം ഇരുന്നു നിസ്കരിക്കുകയാണെങ്കിൽ നിങ്ങളും ഇരുന്നു കൊണ്ട് നിസ്കരിക്കുക. ഈ ഹദീസ് മുത്തസിലല്ലെന്ന് അബൂദാവൂദ് പറയുന്നു. (ദ)', 'أُسَيْدِ بْنِ حُضَيْرٍ', 'ഉസൈദുബ്നു ഹുളൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى فِي أَصْحَابِهِ تَأَخُّرًا، فَقَالَ: "تَقَدَّمُوا، فَأْتَمُّوا بِي، وَلْيَأْتَمَّ بِكُمْ مَنْ بَعْدَكُمْ، وَلَا يَزَالُ قَوْمٌ يَتَأَخَّرُونَ حَتَّى يُؤَخِّرَهُمُ اللهُ". (ن)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): നബി(സ) തന്റെ അനുചരരിൽ (നിസ്കാരത്തിന്) പിന്തിവരുന്ന സ്വഭാവം കണ്ടപ്പോൾ പറഞ്ഞു: "നിങ്ങൾ മുന്നിട്ട് വന്ന് എന്നെ ഇമാമാക്കി കൊണ്ട് (എന്നെ തുടർന്ന് നിസ്കാരം) നിർവ്വഹിക്കുവീൻ. നിങ്ങൾക്ക് ശേഷം വരുന്നവർ നിങ്ങളെ തുടരട്ടെ. ഒരു സമൂഹം സ്വയം പിന്തുമ്പോഴെല്ലാം അല്ലാഹു അവരെ പിന്തിച്ചു കൊണ്ടിരിക്കും." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ أَبَا بَكْرٍ أَنْ يُصَلِّيَ بِالنَّاسِ، قَالَتْ: وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ يَدَيْ أَبِي بَكْرٍ، فَصَلَّى قَاعِدًا، وَأَبُو بَكْرٍ يُصَلِّي بِالنَّاسِ، وَالنَّاسُ خَلْفَ أَبِي بَكْرٍ. (ن)', 'ആഇശ(റ): നബി(സ) അബൂബക്കറിനോട് ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കാൻ കൽപിച്ചു. (ആഇശ) പറയുന്നു: നബി(സ) അബൂബക്കറിന് മുന്നിൽ ഇരുന്ന് നിസ്കരിച്ചു. ജനങ്ങൾ അബൂബക്കറിന് പിന്നിൽ നിന്ന് നിസ്കരിക്കുകയായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 412, 412, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ، وَأَبُو بَكْرٍ خَلْفَهُ، فَإِذَا كَبَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَبَّرَ أَبُو بَكْرٍ يُسْمِعُنَا. (ن)', 'ജാബിർ(റ): നബി(സ) ഞങ്ങളുമായി ളുഹ്ർ നിസ്കരിച്ചു. അബൂബക്കർ(റ) നബി(സ)യുടെ പിന്നിലായിരുന്നു. നബി(സ) തക്ബീർ ചൊല്ലുമ്പോൾ അബൂബക്കർ(റ) ഞങ്ങളെ കേൾപ്പിക്കാനായി തക്ബീർ ചൊല്ലിയിരുന്നു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 412, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا كَانُوا ثَلَاثَةً فَلْيَؤُمَّهُمْ أَحَدُهُمْ، وَأَحَقُّهُمْ بِالْإِمَامَةِ أَقْرَؤُهُمْ". (ن)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "അവർ മൂന്ന് പേരുണ്ടെങ്കിൽ അതിലൊരാൾ ഇമാമാകണം. ഇമാമത്തിന് കൂടുതലർഹൻ അവരിൽ ഖുർആൻ നന്നായി അറിയുന്നവരാണ് (പാരായണം ചെയ്യുന്നവനാണ്)." (ന)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 413, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي مَسْعُودٍ الْبَدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللهِ وَأَقْدَمُهُمْ قِرَاءَةً، فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً فَلْيَؤُمَّهُمْ أَقْدَمُهُمْ هِجْرَةً، فَإِنْ كَانُوا فِي الْهِجْرَةِ سَوَاءً فَلْيَؤُمَّهُمْ أَكْبَرُهُمْ سِنًّا، وَلَا يُؤَمَّ الرَّجُلُ فِي بَيْتِهِ وَلَا فِي سُلْطَانِهِ، وَلَا يُجْلَسُ عَلَى تَكْرِمَتِهِ إِلَّا بِإِذْنِهِ". قَالَ شُعْبَةُ: فَقُلْتُ لِإِسْمَعِيلَ: مَا تَكْرِمَتُهُ؟ قَالَ: فِرَاشُهُ، وَفِي رِوَايَةٍ: "وَلَا يُؤَمُّ الرَّجُلُ الرَّجُلَ فِي سُلْطَانِهِ" وَفِي رِوَايَةٍ: "فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً فَأَعْلَمُهُمْ بِالسُّنَّةِ فَإِنْ كَانُوا فِي السُّنَّةِ سَوَاءً فَأَقْدَمُهُمْ هِجْرَةً". (م,د,ت,ن,جه)', 'അബൂമസ്ഊദിൽ ബദ്‌രീ(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങൾക്ക് ഇമാം നിൽക്കേണ്ടത് അവരിൽ അല്ലാഹുവിന്റെ ഗ്രന്ഥം ഏറ്റവും നന്നായി പാരായണം ചെയ്യുന്നവരാണ് (അറിയുന്നവരാണ്). അവർ ഖുർആൻ പാരായണത്തിൽ തുല്യരാണെങ്കിൽ ഇമാം നിൽക്കേണ്ടത് ആദ്യം ഹിജ്റ ചെയ്തവരാണ്. അവർ ഹിജ്റയുടെ കാര്യത്തിൽ തുല്യരാണെങ്കിൽ അവരിൽ ഏറ്റവും പ്രായം ചെന്നയാളാണ് ഇമാം നിൽക്കേണ്ടത്. ഒരാൾ തന്റെ വീട്ടിലോ തനിക്ക് അധികാരമുള്ളിടത്തോ മറ്റൊരാളെ ഇമാമാക്കരുത്. ഒരാൾ ആദരിക്കപ്പെടുന്ന സ്ഥാനത്ത് അയാളുടെ സമ്മതമില്ലാതെ മറ്റൊരാളെ ഇരുത്തലും അപ്രകാരം തന്നെ." ശുഅ്ബ പറഞ്ഞു: അപ്പോൾ ഞാൻ ഇസ്മാഈലിനോട് ചോദിച്ചു: ഒരാൾ ആദരിക്കപ്പെടുന്ന സ്ഥാനം എന്നതുകൊണ്ട് ഉദ്ദേശിക്കുന്നതെന്താണ്? അദ്ദേഹം പറഞ്ഞു: അയാളുടെ വിരിപ്പാണ്. മറ്റൊരു റിപ്പോർട്ടിൽ: "അവർ ഖുർആൻ പാരായണത്തിൽ തുല്യരാണെങ്കിൽ പ്രവാചകചര്യയിൽ ഏറ്റവും അറിവുള്ളവരാണ് ഇമാമാകേണ്ടത്. പ്രവാചകചര്യ അറിയുന്നതിൽ തുല്യരാണെങ്കിൽ ആദ്യമായി ഹിജ്റ ചെയ്തവരും." (മു,ദ,തു,ന,ജ)', 'أَبِي مَسْعُودٍ الْبَدْرِيِّ', 'അബൂമസ്ഊദിൽ ബദ്‌രീ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 413, 413, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=85), 1, 'وَفِي رِوَايَةٍ: "وَلَا يُؤَمُّ الرَّجُلُ الرَّجُلَ فِي سُلْطَانِهِ"', 'മറ്റൊരു നിവേദനിൽ: "അവർ ഖുർആൻ പാരായണത്തിൽ തുല്യരാണെങ്കിൽ പ്രവാചകചര്യയിൽ ഏറ്റവും അറിവുള്ളവരാണ് ഇമാമാകേണ്ടത്. പ്രവാചകചര്യ അറിയുന്നതിൽ തുല്യരാണെങ്കിൽ ആദ്യമായി ഹിജ്റ ചെയ്തവരും." (മു,ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=85), 2, 'وَفِي رِوَايَةٍ: "فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً فَأَعْلَمُهُمْ بِالسُّنَّةِ فَإِنْ كَانُوا فِي السُّنَّةِ سَوَاءً فَأَقْدَمُهُمْ هِجْرَةً". (م,د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَمْرِو بْنِ سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا بِحَاضِرٍ يَمُرُّ بِنَا النَّاسُ إِذَا أَتَوُا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَانُوا إِذَا رَجَعُوا مَرُّوا بِنَا، فَأَخْبَرُونَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ كَذَا وَكَذَا، وَكُنْتُ غُلَامًا حَافِظًا، فَحَفِظْتُ مِنْ ذَلِكَ قُرْآنًا كَثِيرًا، فَانْطَلَقَ أَبِي وَافِدًا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي نَفَرٍ مِنْ قَوْمِهِ، فَعَلَّمَهُمُ الصَّلَاةَ، فَقَالَ: يَؤُمُّكُمْ أَقْرَؤُكُمْ، وَكُنْتُ أَقْرَأَهُمْ لِمَا كُنْتُ أَحْفَظُ، فَقَدَّمُونِي، فَكُنْتُ أَؤُمُّهُمْ وَعَلَيَّ بُرْدَةٌ لِي صَغِيرَةٌ صَفْرَاءُ، فَكُنْتُ إِذَا سَجَدْتُ تَكَشَّفَتْ عَنِّي، فَقَالَتِ امْرَأَةٌ مِنَ النِّسَاءِ: وَارُوا عَنَّا عَوْرَةَ قَارِئِكُمْ، فَاشْتَرَوْا لِي قَمِيصًا عُمَانِيًّا، فَمَا فَرِحْتُ بِشَيْءٍ بَعْدَ الْإِسْلَامِ فَرَحِي بِهِ، فَكُنْتُ أَؤُمُّهُمْ وَأَنَا ابْنُ سَبْعِ سِنِينَ أَوْ ثَمَانِ سِنِينَ. (خ,د,ن)', 'അംറുബ്നു സലമ(റ): ജനങ്ങൾ നബി(സ)യുടെ സന്നിധിയിലേക്ക് പോകുമ്പോഴും തിരികെ വരുമ്പോഴും ഞങ്ങളുടെ അരികിലൂടെ പോകും. നബി(സ) പറഞ്ഞതെല്ലാം ഞങ്ങളെ അറിയിക്കും. ഞാൻ നന്നായി മനഃപാഠമാക്കാൻ കഴിയുന്ന കുട്ടിയായിരുന്നു. അതിനാൽ ഞാൻ ധാരാളം ഖുർആൻ മനഃപാഠമാക്കി. എന്റെ പിതാവ് ഒരു സംഘത്തോടൊപ്പം പ്രവാചകന്റെ അടുത്ത് ചെന്നു. പ്രവാചകൻ(സ) അവർക്ക് നിസ്കാരം പഠിപ്പിച്ചു. എന്നിട്ട് പറഞ്ഞു: "നിങ്ങളിൽ ഇമാമാകേണ്ടത് ഏറ്റവും നന്നായി ഖുർആൻ പാരായണം ചെയ്യുന്നവരാണ്." ഖുർആൻ മനഃപാഠമാക്കിയ കാരണം ഞാനായിരുന്നു അവരിൽ നന്നായി ഖുർആൻ ഓതുന്നുവൻ (നന്നായി അറിയുന്നവൻ). അതിനാൽ അവർ എന്നെ മുന്നിൽ നിർത്തി. ഞാനവർക്ക് ഇമാമായി. എന്റെയടുത്ത് മഞ്ഞനിറമുള്ള ഒരു ചെറിയ തുണി മാത്രമേ ഉണ്ടായിരുന്നുള്ളൂ. അത് കൊണ്ട് ഞാൻ സുജൂദ് ചെയ്താൽ (എന്റെ നഗ്നത) വെളിവാകുമായിരുന്നു. അവരിൽ ഒരു സ്ത്രീ പറഞ്ഞു: നിങ്ങളുടെ ഖാരിഇന്റെ (ഇമാമിന്റെ) നഗ്നത ഞങ്ങളിൽ നിന്ന് മറച്ച് വെക്കൂ. അങ്ങനെ അവർ എനിക്കൊരു ഒമാനി വസ്ത്രം വാങ്ങിത്തന്നു. ഇസ്ലാമിൽ വന്നതിന് ശേഷം അത്ര വലിയ സന്തോഷം എനിക്കുണ്ടായിട്ടേയില്ല. എനിക്ക് ഏഴോ എട്ടോ വയസ്സുള്ളപ്പോഴാണ് ഞാനവർക്ക് ഇമാമായത്. (ബു,ദ,ന)', 'عَمْرِو بْنِ سَلَمَةَ', 'അംറുബ്നു സലമ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 413, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا قَدِمَ الْمُهَاجِرُونَ الْأَوَّلُونَ نَزَلُوا الْعُصْبَةَ قَبْلَ مَقْدَمِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ يَؤُمُّهُمْ سَالِمٌ مَوْلَى أَبِي حُذَيْفَةَ، وَكَانَ أَكْثَرَهُمْ قُرْآنًا، وَفِيهِمْ عُمَرُ بْنُ الْخَطَّابِ وَأَبُو سَلَمَةَ بْنُ عَبْدِ الْأَسَدِ. (خ,د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ആദ്യത്തെ മുഹാജിറുകൾ നബി(സ) എത്തുന്നതിന് മുമ്പ് അസ്വബഃയിൽ ഇറങ്ങി. അവരുടെ ഇമാം അബൂഹുദൈഫയുടെ അടിമയായ സാലിമായിരുന്നു. അവരുടെ കൂട്ടത്തിൽ ഖുർആൻ നന്നായി അറിയുന്ന ആളായിരുന്നു അദ്ദേഹം. അവരുടെ ഇടയിൽ ഉമറുബ്നുൽ ഖത്താബും അബൂസലമതബ്നു അബ്ദിൽ അസദും ഉണ്ടായിരുന്നു. (ബു,ദ)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ أَوْ لِصَاحِبٍ لَهُ: "إِذَا حَضَرَتِ الصَّلَاةُ فَأَذِّنَا، ثُمَّ أَقِيمَا، ثُمَّ لِيَؤُمَّكُمَا أَكْبَرُكُمَا سِنًّا". وَكُنَّا يَوْمَئِذٍ مُتَقَارِبَيْنِ فِي الْعِلْمِ. (ق,ت,ن,جه)', 'മാലിക്ബ്നുൽ ഹുവൈരിസ്(റ): നബി(സ) അദ്ദേഹത്തോട് - അല്ലെങ്കിൽ അദ്ദേഹത്തിന്റെ കൂട്ടുകാരനോട് - പറഞ്ഞു: "നിസ്കാര സമയമായാൽ ബാങ്ക് വിളിക്കുക. പിന്നെ ഇഖാമത്ത് വിളിക്കുക. ശേഷം നിങ്ങളിൽ ഏറ്റവും പ്രായം കൂടിയ ആൾ ഇമാമാകുക. അന്ന് ഞങ്ങൾ രണ്ട് പേരും വിജ്ഞാനത്തിൽ തുല്യരായിരുന്നു." (ബു,മു,തു,ന,ജ)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലിക്ബ്നുൽ ഹുവൈരിസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِيُؤَذِّنْ لَكُمْ خِيَارُكُمْ، وَلْيَؤُمَّكُمْ قُرَّاؤُكُمْ". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഉത്തമരായ ആളുകൾ ബാങ്ക് വിളിക്കട്ടെ. നിങ്ങളിൽ നന്നായി ഖുർആൻ അറിയുന്നവർ ഇമാമാകുകയും ചെയ്യട്ടെ." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ زَارَ قَوْمًا فَلَا يَؤُمَّهُمْ، وَلْيَؤُمَّهُمْ رَجُلٌ مِنْهُمْ". (د,ت,ن)', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരാൾ ഒരു സമൂഹത്തെ സന്ദർശിച്ചാൽ അയാൾ അവർക്ക് ഇമാമാകരുത്. അവരിൽ തന്നെ ഒരാളാണ് ഇമാമാകേണ്ടത്." (ദ,തു,ന)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ قَالَ: إِنِّي لَأُصَلِّي بِكُمْ، وَمَا أُرِيدُ الصَّلَاةَ. أُصَلِّي كَيْفَ رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي. (خ)', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ): യഥാർത്ഥത്തിൽ നിസ്കാരം ഉദ്ദേശിച്ചല്ല നിങ്ങളെക്കൊണ്ട് ഞാൻ നിസ്കരിക്കുന്നത്. നബി(സ) എങ്ങനെ നിസ്കരിക്കുന്നതായാണ് ഞാൻ കണ്ടത് അങ്ങനെയാണ് ഞാൻ നിസ്കരിക്കുന്നത്. (ബു)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 414, 414, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أُمِّ الْمُؤْمِنِينَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي مَرَضِهِ: "مُرُوا أَبَا بَكْرٍ يُصَلِّي بِالنَّاسِ". قَالَتْ عَائِشَةُ: قُلْتُ: إِنَّ أَبَا بَكْرٍ إِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعِ النَّاسَ مِنَ الْبُكَاءِ، فَمُرْ عُمَرَ، فَلْيُصَلِّ لِلنَّاسِ، فَقَالَ: "مُرُوا أَبَا بَكْرٍ، فَلْيُصَلِّ بِالنَّاسِ". فَقَالَتْ عَائِشَةُ: فَقُلْتُ لِحَفْصَةَ: قُولِي: إِنَّ أَبَا بَكْرٍ إِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعِ النَّاسَ مِنَ الْبُكَاءِ، فَمُرْ عُمَرَ، فَلْيُصَلِّ بِالنَّاسِ، فَفَعَلَتْ حَفْصَةُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكُنَّ لَأَنْتُنَّ صَوَاحِبُ يُوسُفَ! مُرُوا أَبَا بَكْرٍ، فَلْيُصَلِّ لِلنَّاسِ". فَقَالَتْ حَفْصَةُ لِعَائِشَةَ: مَا كُنْتُ لِأُصِيبَ مِنْكِ خَيْرًا. (خ)', 'ആഇശ(റ): രോഗ സന്ദർഭത്തിൽ നബി(സ) പറഞ്ഞു: "ജനങ്ങൾക്ക് (നേതൃത്വം നൽകി) നിസ്കരിക്കാൻ അബൂബക്കറിനോട് പറയൂ." ആഇശ(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: അബൂബക്കർ താങ്കളുടെ സ്ഥാനത്ത് നിന്നാൽ കരച്ചിൽ കാരണം ജനങ്ങളെ ഒന്നും കേൾപ്പിക്കാൻ കഴിയില്ല. അതിനാൽ ഉമറിനോട് കൽപ്പിച്ചാലും! അദ്ദേഹം ജനങ്ങളുമായി നിസ്കരിക്കട്ടെ. നബി(സ) പറഞ്ഞു: "ജനങ്ങൾക്ക് (നേതൃത്വം നൽകി) നിസ്കരിക്കാൻ അബൂബക്കറിനോട് പറയുക." ആഇശ(റ) പറയുന്നു: ഞാൻ ഹഫ്സ്വയോട് പറഞ്ഞു: ''അബൂബക്കർ താങ്കളുടെ സ്ഥാനത്ത് നിന്നാൽ കരച്ചിൽ കാരണം ജനങ്ങളെ ഒന്നും കേൾപ്പിക്കാൻ കഴിയില്ല. അതിനാൽ ഉമറിനോട് കൽപ്പിച്ചാലും! അദ്ദേഹം ജനങ്ങളുമായി നിസ്കരിക്കട്ടെ.'' എന്ന് നീ (നബിയോട്) പറയൂ. ഹഫ്സ അങ്ങനെ ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം, നിങ്ങൾ യുസുഫിന്റെ (യുസുഫിനെ കെണിയിലാക്കാൻ ഉദ്ദേശിച്ച സ്ത്രീകളുടെ) സഹോദരങ്ങൾ തന്നെ. അബൂബക്കറിനോട് ജനങ്ങൾക്ക് (നേതൃത്വം നൽകി) നിസ്കരിക്കാൻ പറയൂ." അപ്പോൾ ആഇശ(റ)യോട് ഹഫ്സ പറഞ്ഞു: എനിക്ക് നിന്നിൽ നിന്ന് നല്ലത് കിട്ടിയിട്ടില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 414, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَنَسِ بْنِ مَالِكٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَا بَكْرٍ كَانَ يُصَلِّي لَهُمْ فِي وَجَعِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الَّذِي تُوُفِّيَ فِيهِ، حَتَّى إِذَا كَانَ يَوْمُ الِاثْنَيْنِ وَهُمْ صُفُوفٌ فِي الصَّلَاةِ، فَكَشَفَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سِتْرَ الْحُجْرَةِ يَنْظُرُ إِلَيْنَا وَهُوَ قَائِمٌ، كَأَنَّ وَجْهَهُ وَرَقَةُ مُصْحَفٍ، ثُمَّ تَبَسَّمَ يَضْحَكُ، فَهَمَمْنَا أَنْ نَفْتَتِنَ مِنَ الْفَرَحِ بِرُؤْيَةِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَنَكَصَ أَبُو بَكْرٍ عَلَى عَقِبَيْهِ لِيَصِلَ الصَّفَّ، وَظَنَّ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَارِجٌ إِلَى الصَّلَاةِ، فَأَشَارَ إِلَيْنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَتِمُّوا صَلَاتَكُمْ وَأَرْخَى السِّتْرَ فَتُوُفِّيَ مِنْ يَوْمِهِ. (خ)', 'അനസ്(റ): നബി(സ) മരണരോഗ ശയ്യയിലായിരിക്കെ അബൂബക്കർ ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കുകയായിരുന്നു. അങ്ങനെ തിങ്കളാഴ്ച അവർ നിസ്കരിക്കാൻ വേണ്ടി അണിയായി നിൽക്കവെ നബി(സ) മുറിയുടെ മറ നീക്കി എഴുന്നേറ്റു നിന്ന് ഞങ്ങളെ നോക്കി. അദ്ദേഹത്തിന്റെ മുഖം മുസ്ഹഫിന്റെ താളു പോലെയുണ്ട്. അവിടുന്ന് ഞങ്ങളെ നോക്കി പുഞ്ചിരിച്ചു. നബിയെ കണ്ട സന്തോഷത്താൽ ഞങ്ങൾ അശ്രദ്ധയിലാകുമോ എന്ന് ഭയപ്പെട്ടു. നബി(സ) നിസ്കാരത്തിനെത്തുമെന്ന് കരുതി അബൂബക്കർ അണിയിലേക്ക് മാറാൻ വേണ്ടി തന്റെ മടമ്പുകാലിൽ പിന്നോട്ട് നിന്നു. എന്നാൽ നിസ്കാരം പൂർത്തിയാക്കാൻ ഞങ്ങളോട് ആംഗ്യം കാണിച്ച് വിരി താഴ്ത്തിയിട്ടു. ആ ദിവസമാണ് നബി(സ) മരണപ്പെട്ടത്. (ബു)', 'أَنَسِ بْنِ مَالِكٍ الْأَنْصَارِيِّ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 415, 415, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَهَبَ إِلَى بَنِي عَمْرِو بْنِ عَوْفٍ لِيُصْلِحَ بَيْنَهُمْ، فَحَانَتِ الصَّلَاةُ، فَجَاءَ الْمُؤَذِّنُ إِلَى أَبِي بَكْرٍ فَقَالَ: أَتُصَلِّي لِلنَّاسِ فَأُقِيمَ. قَالَ: نَعَمْ فَصَلَّى أَبُو بَكْرٍ، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالنَّاسُ فِي الصَّلَاةِ، فَتَخَلَّصَ حَتَّى وَقَفَ فِي الصَّفِّ، فَصَفَّقَ النَّاسُ. وَكَانَ أَبُو بَكْرٍ لَا يَلْتَفِتُ فِي صَلَاتِهِ، فَلَمَّا أَكْثَرَ النَّاسُ التَّصْفِيقَ الْتَفَتَ، فَرَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَشَارَ إِلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنِ امْكُثْ مَكَانَكَ". فَرَفَعَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ يَدَيْهِ، فَحَمِدَ اللهَ عَلَى مَا أَمَرَهُ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ ذَلِكَ. ثُمَّ اسْتَأْخَرَ أَبُو بَكْرٍ حَتَّى اسْتَوَى فِي الصَّفِّ، وَتَقَدَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى. فَلَمَّا انْصَرَفَ قَالَ: "يَا أَبَا بَكْرٍ، مَا مَنَعَكَ أَنْ تَثْبُتَ إِذْ أَمَرْتُكَ". فَقَالَ أَبُو بَكْرٍ: مَا كَانَ لِابْنِ أَبِي قُحَافَةَ أَنْ يُصَلِّيَ بَيْنَ يَدَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا لِي رَأَيْتُكُمْ أَكْثَرْتُمُ التَّصْفِيقَ، مَنْ رَابَهُ شَيْءٌ فِي صَلَاتِهِ فَلْيُسَبِّحْ، فَإِنَّهُ إِذَا سَبَّحَ الْتُفِتَ إِلَيْهِ. وَإِنَّمَا التَّصْفِيقُ لِلنِّسَاءِ". (خ)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ): നബി(സ) ബനൂ അംറുബ്നു ഔഫിന്നിടയിൽ തീർപ്പു കൽപിക്കാൻ പോയി. നിസ്കാര സമയമായപ്പോൾ ബാങ്ക് വിളിച്ചയാൾ അബൂബക്കറി(റ)നോട് പറഞ്ഞു: താങ്കൾ നിസ്കരിക്കുമെങ്കിൽ ഇഖാമത്ത് വിളിക്കാം. അദ്ദേഹം സമ്മതിച്ചു. അദ്ദേഹം നിസ്കരിക്കുമ്പോൾ നബി(സ) വന്ന് ഒരു സ്വഫ്ഫിൽ നിന്നു. അപ്പോൾ ജനങ്ങൾ കൈകൊട്ടി. നിസ്കാരത്തിൽ തിരിഞ്ഞു നോക്കാത്തയാളായിരുന്നു അബൂബക്കർ. എന്നാൽ ജനങ്ങളുടെ കൈയ്യടിക്കൽ അധികരിച്ചപ്പോൾ അദ്ദേഹം തിരിഞ്ഞു നോക്കി. അപ്പോൾ നബിയെ കണ്ടു. നബി(സ) അദ്ദേഹത്തോട് അതേസ്ഥാനത്ത് നിൽക്കാൻ പറഞ്ഞു. അതേസ്ഥാനത്ത് നിൽക്കാൻ നബി(സ) പറഞ്ഞതിനാൽ അദ്ദേഹം കൈകളുയർത്തി അല്ലാഹുവിനെ സ്തുതിച്ചു. പിന്നോട്ടു മാറി സ്വഫ്ഫിൽ നിന്നു. നബി(സ) മുന്നോട്ടു നിന്ന് നിസ്കരിക്കുകയും ചെയ്തു. നിസ്കാരശേഷം നബി(സ) ചോദിച്ചു: "അബൂബക്കർ, ഞാൻ നിൽക്കാൻ പറഞ്ഞപ്പോൾ താങ്കളെന്തു കൊണ്ട് നിന്നില്ല?" അദ്ദേഹം പറഞ്ഞു: റസൂലിന്റെ മുന്നിൽനിന്ന് നിസ്കരിക്കാൻ അബൂഖുഹാഫയുടെ മകന് യോഗ്യതയില്ല. നബി(സ) പറഞ്ഞു: "നിങ്ങളെന്തിനാണ് ശക്തമായി കൈകൊട്ടിയത്? ആർക്കെങ്കിലും നിസ്കാരത്തിൽ സംശയം തോന്നിയാൽ അവൻ തസ്ബീഹ് ചൊല്ലട്ടെ. കൈകൊട്ടൽ സ്ത്രീകൾക്കുള്ളതാണ്." (ബു)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 415, 416, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: لَمَّا ثَقُلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَصَلَّى النَّاسُ؟" قُلْنَا: لَا، هُمْ يَنْتَظِرُونَكَ. قَالَ: "ضَعُوا لِي مَاءً فِي الْمِخْضَبِ". قَالَتْ: فَفَعَلْنَا، فَاغْتَسَلَ فَذَهَبَ لِيَنُوءَ، فَأُغْمِيَ عَلَيْهِ. ثُمَّ أَفَاقَ فَقَالَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَصَلَّى النَّاسُ؟" قُلْنَا: لَا، هُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللهِ. قَالَ: "ضَعُوا لِي مَاءً فِي الْمِخْضَبِ". قَالَتْ: فَقَعَدَ فَاغْتَسَلَ، ثُمَّ ذَهَبَ لِيَنُوءَ، فَأُغْمِيَ عَلَيْهِ. ثُمَّ أَفَاقَ فَقَالَ: "أَصَلَّى النَّاسُ؟" قُلْنَا: لَا، هُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللهِ فَقَالَ: "ضَعُوا لِي مَاءً فِي الْمِخْضَبِ". فَقَعَدَ فَاغْتَسَلَ، ثُمَّ ذَهَبَ لِيَنُوءَ فَأُغْمِيَ عَلَيْهِ. ثُمَّ أَفَاقَ فَقَالَ: "أَصَلَّى النَّاسُ؟" فَقُلْنَا: لَا، هُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللهِ. وَالنَّاسُ عُكُوفٌ فِي الْمَسْجِدِ، يَنْتَظِرُونَ النَّبِيَّ عَلَيْهِ السَّلَامُ لِصَلَاةِ الْعِشَاءِ الْآخِرَةِ، فَأَرْسَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى أَبِي بَكْرٍ بِأَنْ يُصَلِّيَ بِالنَّاسِ، فَأَتَاهُ الرَّسُولُ فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكَ أَنْ تُصَلِّيَ بِالنَّاسِ. فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: (وَكَانَ رَجُلًا رَقِيقًا) يَا عُمَرُ، صَلِّ بِالنَّاسِ. فَقَالَ لَهُ عُمَرُ رَضِيَ اللهُ عَنْهُ: أَنْتَ أَحَقُّ بِذَلِكَ. فَصَلَّى أَبُو بَكْرٍ تِلْكَ الْأَيَّامَ........ (خ)', 'ആഇശ(റ): നബി(സ)ക്ക് രോഗം കലശലായപ്പോൾ തിരുമേനി ചോദിച്ചു: "ജനങ്ങൾ നിസ്കരിച്ചോ?" ഞങ്ങൾ പറഞ്ഞു: ഇല്ല, അവർ താങ്കളെ പ്രതീക്ഷിച്ചരിക്കുകയാണ്. നബി(സ) പറഞ്ഞു: "എനിക്ക് കുളിക്കാനുള്ള പാത്രത്തിൽ വെള്ളം വെക്കുക. ഞങ്ങൾ അപ്രകാരം ചെയ്യുകയും, നബി(സ) കുളിക്കുകയും ചെയ്തു. അങ്ങനെ പ്രയാസപ്പെട്ട് എഴുന്നേൽക്കാൻ ശ്രമിക്കുകയും, നബിക്ക് ബോധക്ഷയം സംഭവിക്കുകയും ചെയ്തു. പിന്നെ ബോധം തെളിഞ്ഞപ്പോൾ നബി(സ) ചോദിച്ചു: "ജനങ്ങൾ നിസ്കരിച്ചോ?" ഇല്ല എന്നും, അവർ താങ്കളെ പ്രതീക്ഷിച്ചിരിക്കുകയാണെന്നും ഞങ്ങൾ പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "എനിക്ക് കുളിക്കാൻ വെള്ളമെടുക്കൂ. നബി(സ) കുളിച്ചു. എഴുന്നേൽക്കാൻ ശ്രമിച്ചപ്പോൾ വീണ്ടും ബോധക്ഷയമുണ്ടായി. ബോധം തെളിഞ്ഞപ്പോൾ വീണ്ടും: "ജനങ്ങൾ നിസ്കരിച്ചോ?" എന്നു ചോദിച്ചു. അപ്പോൾ ഇല്ല എന്നും, അവർ താങ്കളെ പ്രതീക്ഷിച്ചിരിക്കുകയാണെന്നും ഞങ്ങൾ പറഞ്ഞു. അപ്പോൾ വീണ്ടും: "എനിക്ക് കുളിക്കാൻ വെള്ളമെടുക്കൂ" എന്നു പറഞ്ഞു. ഇരുന്ന് കുളിക്കുകയും എഴുന്നേൽക്കാൻ ശ്രമിച്ചപ്പോൾ വീണ്ടും ബോധക്ഷയമുണ്ടുവുകയും ചെയ്തു. പിന്നീട് ബോധം തെളിഞ്ഞപ്പോൾ ചോദിച്ചു: "ജനങ്ങൾ നിസ്കരിച്ചോ?" ഇല്ല എന്നും, അവർ താങ്കളെ പ്രതീക്ഷിച്ചിരിക്കുകയാണെന്നും പറഞ്ഞു. ജനങ്ങൾ ഇശാനിസ്കാരത്തിനായി നബിയെയും പ്രതീക്ഷിച്ച് പള്ളിയിലിരിക്കുകയായിരുന്നു. ജനങ്ങളെയും കൊണ്ട് നിസ്കരിക്കണമെന്ന സന്ദേശവുമായി ഒരു ദൂതനെ അബൂബക്കറിന്നടുത്തേക്കയച്ചു. ജനങ്ങളെയുമായി താങ്കൾ നിസ്കരിക്കണമെന്ന് നബി(സ) അറിയിക്കുന്നതായി ദൂതൻ വന്നുപറഞ്ഞപ്പോൾ മൃദുലഹൃദയനായ അബൂബക്കർ(റ) ഉമറി(റ)നോട് ആവശ്യപ്പെട്ടു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: താങ്കളാണ് അതിന് കൂടുതൽ അർഹൻ. അങ്ങനെ ആ ദിവസങ്ങളിൽ അബൂബക്കർ നിസ്കരിച്ചു........... (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 416, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: لَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةً، رَجُلٌ أَمَّ قَوْمًا وَهُمْ لَهُ كَارِهُونَ، وَامْرَأَةٌ بَاتَتْ وَزَوْجُهَا عَلَيْهَا سَاخِطٌ، وَرَجُلٌ سَمِعَ حَيَّ عَلَى الْفَلَاحِ ثُمَّ لَمْ يُجِبْ. (ت)', 'അനസുബ്നു മാലിക്(റ): മൂന്നു വിഭാഗം ആളുകളെ നബി(സ) ശപിച്ചിരിക്കുന്നു: തന്നെ വെറുക്കുന്ന ജനങ്ങൾക്ക് ഇമാമാകുയാൾ, ഭർത്താവ് കോപിച്ച അവസ്ഥയിൽ രാത്രി കഴിച്ചുകൂട്ടിയ സ്ത്രീ, ഹയ്യ അലൽ ഫലാഹ് (വിജയത്തിലേക്ക് വരൂ) എന്ന വിളി കേട്ട് ഉത്തരം നൽകാത്തവൻ. (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 417, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَمْرِو بْنِ الْحَارِثِ بْنِ الْمُصْطَلِقِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ يُقَالُ: أَشَدُّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ اثْنَانِ، امْرَأَةٌ عَصَتْ زَوْجَهَا، وَإِمَامُ قَوْمٍ وَهُمْ لَهُ كَارِهُونَ. (ت)', 'അംറുബ്നുഹാരിസുബ്നു മുസ്ത്വലിഖ്(റ): അദ്ദേഹം പറയാറുണ്ടായിരരുന്നു: രണ്ട് വിഭാഗമാണ് അന്ത്യനാളിൽ ഏറ്റവും കഠിനമായി ശിക്ഷിക്കപ്പെടുക; ഭർത്താവിനെ ധിക്കരിച്ച സ്ത്രീ, തന്നെ വെറുത്ത ജനതക്ക് ഇമാമാകുന്നവൻ. (തു)', 'عَمْرِو بْنِ الْحَارِثِ بْنِ الْمُصْطَلِقِ', 'അംറുബ്നുഹാരിസുബ്നു മുസ്ത്വലിഖ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 417, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ لَا تُجَاوِزُ صَلَاتُهُمْ آذَانَهُمْ، الْعَبْدُ الْآبِقُ حَتَّى يَرْجِعَ، وَامْرَأَةٌ بَاتَتْ وَزَوْجُهَا عَلَيْهَا سَاخِطٌ، وَإِمَامُ قَوْمٍ وَهُمْ لَهُ كَارِهُونَ". (ت)', 'അബൂഉമാമഃ(റ): നബി(സ) പറഞ്ഞു: "മൂന്നു വിഭാഗത്തിന്റെ നിസ്കാരം അവരുടെ ചെവികൾ വിട്ടു കടക്കുകയില്ല (സ്വീകാര്യമല്ല). ഒളിച്ചോടിയ അടിമ മടങ്ങി വരുന്നതു വരെ, ഭർത്താവ് കോപിച്ച നിലയിൽ രാത്രി കഴിച്ചു കൂട്ടിയ സ്ത്രീ, തന്നെ വെറുക്കുന്ന ജനതക്ക് ഇമാമാകുന്നയാൾ." (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമഃ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 417, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "ثَلَاثَةٌ لَا يَقْبَلُ اللهُ مِنْهُمْ صَلَاةً، مَنْ تَقَدَّمَ قَوْمًا وَهُمْ لَهُ كَارِهُونَ، وَرَجُلٌ أَتَى الصَّلَاةَ دِبَارًا، وَالدِّبَارُ أَنْ يَأْتِيَهَا بَعْدَ أَنْ تَفُوتَهُ، وَرَجُلٌ اعْتَبَدَ مُحَرَّرَهُ. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറയാറുണ്ട്: "മൂന്നു വിഭാഗത്തിന്റെ നിസ്കാരം അല്ലാഹു സ്വീകരിക്കുകയില്ല. ജനം തന്നെ വെറുത്തിരിക്കെ ഒരാൾ അവർക്ക് ഇമാമാകുന്നവൻ, സമയം കഴിഞ്ഞ ശേഷം നിസ്കരിക്കുന്നവൻ, സ്വതന്ത്രനായ ശേഷം വീണ്ടും അവനെ അടിമയാക്കുന്നവൻ." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 417, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: آخِرُ صَلَاةٍ صَلَّاهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَعَ الْقَوْمِ صَلَّى فِي ثَوْبٍ وَاحِدٍ مُتَوَشِّحًا، خَلْفَ أَبِي بَكْرٍ. (ن)', 'അനസ്(റ): തിരുമേനി(സ) അവസാനമായി തന്റെ ജനതയോടൊപ്പം നിസ്കരിച്ചത്; അബൂബക്കറിന്റെ പിന്നിൽ ഒറ്റ വസ്ത്രം ധരിച്ചവനായിക്കൊണ്ടായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 417, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَبَا بَكْرٍ صَلَّى لِلنَّاسِ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الصَّفِّ. (ن)', 'ആഇശ(റ): അബൂബക്കർ(റ) ജനങ്ങൾക്ക് ഇമാമായി നിസ്കാരം നിർവ്വഹിച്ചു. തിരുമേനി(സ) അന്നേരം സ്വഫ്ഫിലായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 417, 417, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: كَانَ يُقَدِّمُ فِتْيَانَ قَوْمِهِ يُصَلُّونَ بِهِمْ، فَقِيلَ لَهُ: تَفْعَلُ، وَلَكَ مِنَ الْقِدَمِ مَا لَكَ؟ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْإِمَامُ ضَامِنٌ، فَإِنْ أَحْسَنَ فَلَهُ وَلَهُمْ، وَإِنْ أَسَاءَ يَعْنِي فَعَلَيْهِ وَلَا عَلَيْهِمْ". (جه)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ): തന്റെ സമൂഹത്തിലെ യുവാക്കളെ അവർക്ക് ഇമാമായി നിർത്താറുണ്ടായിരുന്നു. അദ്ദേഹത്തോട് ചോദിച്ചു: നിങ്ങൾ ഇങ്ങനെ ചെയ്യുകയോ? നേരത്തേയുള്ള (ഇമാമത്തിന്റെ യോഗ്യത)യെല്ലാം നിങ്ങൾക്കില്ലേ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറഞ്ഞതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "ഇമാം ഉത്തരവാദിത്തമുള്ളവനാണ്. അയാൾ (നിസ്കാരം) നന്നാക്കിയാൽ അയാൾക്കും അവർക്കും അതിന്റെ പ്രതിഫലമുണ്ട്. ഇനി അയാൾ മോശമാക്കിയാൽ അത് അയാൾക്ക് മാത്രം ബാധകമാണ്. അവർക്കില്ല." (ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 418, 418, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُصَلُّونَ لَكُمْ، فَإِنْ أَصَابُوا فَلَكُمْ، وَإِنْ أَخْطَئُوا فَلَكُمْ وَعَلَيْهِمْ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇമാമുകൾ നിസ്കരിക്കുമ്പോൾ അവർ ശരിയായി ചെയ്യുന്നതിന്റെ പ്രതിഫലം അവർക്കും നിങ്ങൾക്കുമുണ്ട്. ഇനി അവർ തെറ്റുചെയ്താൽ നിങ്ങൾക്ക് പ്രതിഫലവും അവർക്ക് അതിന്റെ കുറ്റവുമുണ്ട്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 418, 418, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ سَلَامَةَ بِنْتِ الْحُرِّ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَأْتِي عَلَى النَّاسِ زَمَانٌ يَقُومُونَ سَاعَةً لَا يَجِدُونَ إِمَامًا يُصَلِّي بِهِمْ". (د,جه)', 'സലാമതുബിൻതുൽഹുർറ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "തങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കാൻ (യോഗ്യനായ) ഒരാളെ കാണാതെ ജനങ്ങൾ കാത്തുനിൽക്കുന്ന ഒരുകാലം വരും." (ദ,ജ)', 'سَلَامَةَ بِنْتِ الْحُرِّ', 'സലാമതുബിൻതുൽഹുർറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 418, 418, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي عَلِيٍّ الْهَمْدَانِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ خَرَجَ فِي سَفِينَةٍ فِيهَا عُقْبَةُ بْنُ عَامِرٍ الْجُهَنِيُّ رَضِيَ اللهُ عَنْهُ، فَحَانَتْ صَلَاةٌ مِنَ الصَّلَوَاتِ، فَأَمَرْنَاهُ أَنْ يَؤُمَّنَا، وَقُلْنَا لَهُ: إِنَّكَ أَحَقُّنَا بِذَلِكَ، أَنْتَ صَاحِبُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَبَى، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَمَّ النَّاسَ فَأَصَابَ فَالصَّلَاةُ لَهُ وَلَهُمْ، وَمَنِ انْتَقَصَ مِنْ ذَلِكَ شَيْئًا فَعَلَيْهِ وَلَا عَلَيْهِمْ". (د,جه)', 'അബൂഅലിയ്യുൽ ഹംദാനീ(റ): അദ്ദേഹം ഉഖ്ബതുബ്നു ആമിറിൽ ജുഹനീ(റ) ഉള്ള ഒരു കപ്പലിൽ യാത്ര പോയി. ഒരു നിസ്കാര സമയമായപ്പോൾ ഞങ്ങൾക്ക് ഇമാമാകാൻ അദ്ദേഹത്തോട് ആവശ്യപ്പെട്ടു. ഞങ്ങൾ അദ്ദേഹത്തോട് പറഞ്ഞു: താങ്കളാണ് ഞങ്ങളിൽ അതിന് ഏറ്റവും അർഹൻ. നിങ്ങൾ നബി(സ)യുടെ കൂട്ടുകാരനാണല്ലോ. എന്നാൽ അദ്ദേഹം വിസമ്മതിച്ചുകൊണ്ട് പറഞ്ഞു: നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. "ഒരാൾ ജനങ്ങൾക്ക് ഇമാമാകുകയും (നിസ്കാരം) ശരിയാകുകയും ചെയ്താൽ ആ നിസ്കാരം അയാൾക്കും അവർക്കും ലഭിച്ചു. എന്നാൽ ആരെങ്കിലും വീഴ്ച വരുത്തിയാൽ അത് അയാൾക്ക് മാത്രമാണ്. അവർക്ക് തെറ്റില്ല." (ദ,ജ)', 'أَبِي عَلِيٍّ الْهَمْدَانِيِّ', 'അബൂഅലിയ്യുൽ ഹംദാനീ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 418, 418, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي الْعَالِيَةِ الْبَرَّاءِ قَالَ: أَخَّرَ زِيَادٌ الصَّلَاةَ، فَأَتَانِي ابْنُ صَامِتٍ، فَأَلْقَيْتُ لَهُ كُرْسِيًّا فَجَلَسَ عَلَيْهِ، فَذَكَرْتُ لَهُ صُنْعَ زِيَادٍ، فَعَضَّ عَلَى شَفَتَيْهِ وَضَرَبَ عَلَى فَخِذِي وَقَالَ: إِنِّي سَأَلْتُ أَبَا ذَرٍّ رَضِيَ اللهُ عَنْهُ كَمَا سَأَلْتَنِي، فَضَرَبَ فَخِذِي كَمَا ضَرَبْتُ فَخِذَكَ، وَقَالَ: إِنِّي سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَمَا سَأَلْتَنِي، فَضَرَبَ فَخِذِي كَمَا ضَرَبْتُ فَخِذَكَ، فَقَالَ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ: "صَلِّ الصَّلَاةَ لِوَقْتِهَا، فَإِنْ أَدْرَكْتَ مَعَهُمْ فَصَلِّ، وَلَا تَقُلْ: إِنِّي صَلَّيْتُ فَلَا أُصَلِّي". (ن)', 'അബുൽ ആലിയത്തുൽ ബർറാഅ്: സിയാദ് നിസ്കാരം പിന്തിച്ചു. അങ്ങനെ ഇബ്നുസാമിത്ത് ഒരിക്കൽ എന്റെ അടുക്കൽ വന്നു. അപ്പോൾ ഞാനദ്ദേഹത്തിന് ഒരു കസേരയിട്ടുകൊടുത്തു. അദ്ദേഹം അതിന്മേലിരുന്നു. ഞാൻ അദ്ദേഹത്തോട് സിയാദിന്റെ പ്രവൃത്തിയെ കുറിച്ച് പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം തന്റെ ഇരു ചുണ്ടുകൾ കടിച്ച് പിടിച്ചുകൊണ്ട് എന്റെ തുടക്ക്മേൽ അടിച്ചുകൊണ്ട് പറഞ്ഞു: ഞാൻ അബൂദർ(റ)നോട് നീ എന്നോട് ചോദിച്ചത് പോലെത്തന്നെ ചോദിച്ചപ്പോൾ അദ്ദേഹം എന്റെ തുടക്ക് ഞാൻ നിന്റെ തുടക്കുമേൽ അടിച്ചത് പോലെത്തന്നെ അടിച്ചു. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: നീ എന്നോട് ഈ ചോദിച്ചതുപോലെ ഞാൻ റസൂലി(സ)നോടു ചോദിച്ചപ്പോൾ ഞാൻ നിന്റെ തുടക്ക് അടിച്ചത് പൊലെത്തന്നെ തിരുമേനി(സ) എന്റെ തുടക്കുമേലും അടിയ്ക്കുകയുണ്ടായി. ശേഷം അവിടുന്ന് പറഞ്ഞു: നീ നിസ്കാരം അതിന്റെ സമയത്തു തന്നെ നിർവ്വഹിക്കുക. എന്നിട്ട് നിനക്ക് അവരോടൊപ്പം ജമാഅത്ത് ലഭിക്കുകയാണെങ്കിൽ അവരുടെ കൂടെ നിസ്കരിക്കുക. ''ഞാൻ നിസ്കാരം നിർവ്വഹിച്ചു. അതിനാൽ ഞാൻ നിസ്കാരത്തിൽ പങ്കെടുക്കുന്നില്ല'' എന്നു നീ പറയരുത്. (ന)', 'أَبِي الْعَالِيَةِ الْبَرَّاءِ قَالَ', 'അബുൽ ആലിയത്തുൽ ബർറാഅ്', null, null, array['ن']::text[], array['ന']::text[], null, null, 418, 419, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَعَلَّكُمْ سَتُدْرِكُونَ أَقْوَامًا يُصَلُّونَ الصَّلَاةَ لِغَيْرِ وَقْتِهَا، فَإِنْ أَدْرَكْتُمُوهُمْ فَصَلُّوا الصَّلَاةَ لِوَقْتِهَا، وَصَلُّوا مَعَهُمْ وَاجْعَلُوهَا سُبْحَةً". (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): തിരുമേനി(സ) പറഞ്ഞു: നമസ്കാരം അതിന്റേതല്ലാത്ത സമയത്ത് നിർവ്വഹിക്കുന്ന ജനവിഭാഗങ്ങളെ നിങ്ങൾ (എനിക്കു ശേഷം) കണ്ടേക്കാം. നിങ്ങൾ അവരെ കാണുകയാണെങ്കിൽ, നിങ്ങൾ നമസ്കാരം അതിന്റേതായ സമയത്ത് നിർവ്വഹിക്കുക. അവരോടൊപ്പം നിങ്ങൾ (ജമാഅത്തിൽ പങ്കെടുത്തുകൊണ്ട് വീണ്ടും) നിസ്കരിക്കുകയും അതിനെ നിങ്ങൾ ഐച്ഛിക നിസ്കാരമായികണക്കാക്കുകയും ചെയ്യുക. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 419, 419, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ مَنَاكِبَنَا فِي الصَّلَاةِ، وَيَقُولُ: "اسْتَوُوا، وَلَا تَخْتَلِفُوا، فَتَخْتَلِفَ قُلُوبُكُمْ، لِيَلِنِي مِنْكُمْ أُولُو الْأَحْلَامِ وَالنُّهَى، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ". قَالَ أَبُو مَسْعُودٍ: فَأَنْتُمُ الْيَوْمَ أَشَدُّ اخْتِلَافًا. (م,ن)', 'അബൂമസ്ഊദ്(റ): നബി(സ) നിസ്കാരത്തിന് നിൽക്കുമ്പോൾ ഞങ്ങളുടെ ചുമലുകൾ തട്ടിക്കൊണ്ട് പറയും: "നിങ്ങൾ ശരിയായി നിൽക്കുക. നിങ്ങൾ വിടവുണ്ടാക്കരുത്. അപ്പോൾ നിങ്ങളുടെ ഹൃദയങ്ങൾ ഭിന്നിക്കും. നിങ്ങളിൽ സമർത്ഥരും വിവേകികളും എന്റെ തൊട്ടുപിന്നിൽ നിൽക്കട്ടെ. പിന്നെ അവരോടടുത്തവർ. പിന്നെ അവരോടടുത്തവർ." അബൂമസ്ഊദ് പറഞ്ഞു: നിങ്ങൾ ഇന്ന് ശക്തമായ ഭിന്നതയുള്ളവരാണ്. (മു,ന)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 419, 419, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ قَيْسِ بْنِ عُبَادٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَا أَنَا فِي الْمَسْجِدِ فِي الصَّفِّ الْمُقَدَّمِ، فَجَبَذَنِي رَجُلٌ مِنْ خَلْفِي جَبْذَةً، فَنَحَّانِي، وَقَامَ مَقَامِي، فَوَاللَّهِ مَا عَقَلْتُ صَلَاتِي، فَلَمَّا انْصَرَفَ فَإِذَا هُوَ أُبَيُّ بْنُ كَعْبٍ، فَقَالَ: يَا فَتَى! لَا يَسُؤْكَ اللَّهُ، إِنَّ هَذَا عَهْدٌ مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيْنَا أَنْ نَلِيَهُ، ثُمَّ اسْتَقْبَلَ الْقِبْلَةَ فَقَالَ: هَلَكَ أَهْلُ الْعُقَدِ، وَرَبِّ الْكَعْبَةِ! ثَلَاثًا، ثُمَّ قَالَ: وَاللهِ! مَا عَلَيْهِمْ آسَى، وَلَكِنْ آسَى عَلَى مَنْ أَضَلُّوا، قُلْتُ: يَا أَبَا يَعْقُوبَ! مَا يَعْنِي بِأَهْلِ الْعُقَدِ؟ قَالَ: الْأُمَرَاءُ. (ن)', 'ഖൈസുബ്നു ഉബാദ(റ): ഞാൻ പള്ളിയിൽ ഒന്നാമത്തെ സ്വഫ്ഫിലായിരിക്കേ എന്നെ പിന്നിൽ നിന്നൊരാൾ പിടിച്ചുവലിച്ചു. എന്നിട്ട് എന്റെ സ്ഥലത്ത് കയറിനിന്നു. എനിക്ക് പിന്നെ നിസ്കാരത്തിൽ സൂക്ഷ്മത പാലിക്കാനായില്ല. നിസ്കാരം കഴിഞ്ഞപ്പോഴാണ് അത് ഉബയ്യുബ്നു കഅ്ബ്(റ) ആണെന്നറിഞ്ഞത്. അദ്ദേഹം പറഞ്ഞു. യുവാവേ! അല്ലാഹു നിന്നെ മോശമാക്കിയിട്ടില്ല. നബി(സ)യുടെ പിന്നിൽ നിൽക്കുക എന്നത് നബി(സ) ഞങ്ങളോട് വാങ്ങിയ കരാറാണ്; പിന്നെ കഅ്ബയുടെ നേരേ തിരിഞ്ഞ് പറഞ്ഞു: കഅ്ബയുടെ നാഥനാണെ! കുരുക്കുകളുടെ വക്താക്കൾ നശിച്ചതുതന്നെ. മൂന്ന് വട്ടം ഇത് ആവർത്തിച്ചു. പിന്നെ പറഞ്ഞു: അല്ലാഹുവാണെ! അവർക്ക് ദുഃഖിക്കേണ്ടതില്ല. എന്നാൽ വഴി പിഴച്ചവർക്കാണ് ദുഃഖിക്കേണ്ടി വരിക. ഞാൻ ചോദിച്ചു: അബൂയഅ്ഖൂബ്! ആരാണ് കുരുക്കുകളുടെ ആളുകൾ? അദ്ദേഹം പറഞ്ഞു: നേതാക്കൾ. (ന)', 'قَيْسِ بْنِ عُبَادٍ', 'ഖൈസുബ്നു ഉബാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 419, 420, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ أَنْ يَلِيَهُ الْمُهَاجِرُونَ وَالْأَنْصَارُ لِيَأْخُذُوا عَنْهُ. (جه)', 'അനസ്(റ): നബി(സ)യിൽ നിന്ന് കാര്യങ്ങൾ പഠിച്ചെടുക്കുന്നതിനു വേണ്ടി അൻസ്വാറുകളും മുഹാജിറുകളും (തൊട്ടുപിന്നിൽ) തുടരുന്നത് നബി(സ) ഇഷ്ടപ്പെട്ടിരുന്നു. (ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 420, 420, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ عَبْدِ الْحَمِيدِ بْنِ مَحْمُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ أَنَسِ بْنِ مَالِكٍ يَوْمَ الْجُمُعَةِ، فَدُفِعْنَا إِلَى السَّوَارِي، فَتَقَدَّمْنَا وَتَأَخَّرْنَا، فَقَالَ أَنَسٌ: كُنَّا نَتَّقِي هَذَا عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د,ت,ن)', 'അബ്ദുൽഹമീദുബ്നു മഹ്മൂദ്(റ): അനസുബ്നു മാലികിനോടൊപ്പം ഞാൻ വെള്ളിയാഴ്ച നിസ്കരിച്ചു. ഞങ്ങൾ തൂണുകളിലേക്ക് തിരിഞ്ഞു നിന്നു. ഞങ്ങൾ (ചിലർ) മുന്നിലും (ചിലർ) പിന്നിലുമൊക്കെയായി (കൊണ്ടാണ് അണിനിന്നത്). അപ്പോൾ അനസ്(റ) പറഞ്ഞു: (സ്വഫ്ഫുകളിൽ നിൽക്കുന്നതിന്റെ ക്രമം) ഇങ്ങനെയാകുന്നത് ഞങ്ങൾ നബി(സ)യുടെ കാലത്ത് സൂക്ഷിച്ചിരുന്നു. (ദ,തു,ന)', 'عَبْدِ الْحَمِيدِ بْنِ مَحْمُودٍ', 'അബ്ദുൽഹമീദുബ്നു മഹ്മൂദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 420, 420, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ قُرَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُنْهَى أَنْ نَصُفَّ بَيْنَ السَّوَارِي عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنُطْرَدُ عَنْهَا طَرْدًا. (جه)', 'ഖുർറ(റ): തൂണുകൾക്കിടയിൽ അണി നിൽക്കുന്നത് നബി(സ)യുടെ കാലത്ത് ഞങ്ങളെ വിലക്കിയിരുന്നു. ഞങ്ങൾ അതിൽ നിന്ന് വിട്ടുനിന്നിരുന്നു. (ജ)', 'قُرَّةَ', 'ഖുർറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 420, 420, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا تَصُفُّونَ كَمَا تَصُفُّ الْمَلَائِكَةُ عِنْدَ رَبِّهِمْ جَلَّ وَعَزَّ؟" قُلْنَا: وَكَيْفَ تَصُفُّ الْمَلَائِكَةُ عِنْدَ رَبِّهِمْ؟ قَالَ: "يُتِمُّونَ الصُّفُوفَ الْمُقَدَّمَةَ، وَيَتَرَاصُّونَ فِي الصَّفِّ". (م,د,ن,جه)', 'ജാബിറുബ്നു സമുറഃ(റ): നബി(സ) പറഞ്ഞു: "മലക്കുകൾ തങ്ങളുടെ നാഥന്റെ അടുക്കൽ അണി നിൽക്കുന്നത് പോലെ നിങ്ങൾ അണി നിൽക്കുന്നില്ലേ?" ഞങ്ങൾ ചോദിച്ചു: പ്രവാചകരേ! എപ്രകാരമാണ് മലക്കുകൾ തങ്ങളുടെ നാഥന്റെ അടുത്ത് അണിനിൽക്കുന്നത്? നബി(സ) പറഞ്ഞു: "അവർ മുൻപിലെ അണികൾ പൂർത്തീകരിക്കുകയും അണികളിൽ ചേർന്നു നിൽക്കുകയും ചെയ്യും." (മു,ദ,ന,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറഃ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 420, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى النَّاسِ بِوَجْهِهِ فَقَالَ: "أَقِيمُوا صُفُوفَكُمْ – ثَلَاثًا – وَاللهِ! لَتُقِيمُنَّ صُفُوفَكُمْ، أَوْ لَيُخَالِفَنَّ اللهُ بَيْنَ قُلُوبِكُمْ". قَالَ: فَرَأَيْتُ الرَّجُلَ يُلْزِقُ مَنْكِبَهُ بِمَنْكِبِ صَاحِبِهِ وَرُكْبَتَهُ بِرُكْبَةِ صَاحِبِهِ وَكَعْبَهُ بِكَعْبِهِ. (ق,د,ت,ن,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): നബി(സ) ജനങ്ങളെ അഭിമുഖീകരിച്ച് പറഞ്ഞു: "നിങ്ങൾ അണികൾ ശരിപ്പെടുത്തി നിൽക്കുക. (ഇക്കാര്യം മൂന്നുതവണ ആവർത്തിച്ചു.) അല്ലാഹുവാണെ! നിങ്ങൾ നിങ്ങളുടെ അണികൾ ശരിയാക്കി നിൽക്കുക. അല്ലെങ്കിൽ അല്ലാഹു നിങ്ങളുടെ ഹൃദയങ്ങളെ ഭിന്നിപ്പിക്കും." ഇത് പറഞ്ഞപ്പോൾ ആളുകൾ തങ്ങളുടെ ചുമലുകളും കൈമുട്ടുകളും മടമ്പുകളും തന്റെ അടുത്ത ആളുടേതിനോട് ചേർത്തു വെക്കുന്നത് ഞാൻ കണ്ടു. (ബു,മു,ദ,തു,ന,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُسَوِّينَا فِي الصُّفُوفِ كَمَا يُقَوَّمُ الْقِدْحُ، حَتَّى إِذَا ظَنَّ أَنْ قَدْ أَخَذْنَا ذَلِكَ عَنْهُ وَفَقِهْنَا أَقْبَلَ ذَاتَ يَوْمٍ بِوَجْهِهِ إِذَا رَجُلٌ مُنْتَبِذٌ بِصَدْرِهِ، فَقَالَ: "لَتُسَوُّنَّ صُفُوفَكُمْ، أَوْ لَيُخَالِفَنَّ اللهُ بَيْنَ وُجُوهِكُمْ". (ق,د,ت,ن,جه)', 'നൂഅ്മാനുബ്നു ബഷീർ(റ): നബി(സ) ഞങ്ങളെ അണിയിൽ ശരിയായി നിർത്താറുണ്ടായിരുന്നു, അമ്പുകൾ ശരിയാക്കി വെക്കുന്നതുപോലെ. അത് നബി(സ)യിൽ നിന്ന് ഞങ്ങൾ പഠിച്ചു മനസ്സിലാക്കി എന്ന് തിരുമേനിക്ക് ബോധ്യപ്പെടുന്നതു വരെ (ഈ രീതി തുടർന്നു.) പിന്നീടൊരിക്കൽ തിരുനബി(സ) ഞങ്ങൾക്കുനേരെ മുഖം തിരിച്ചുകൊണ്ട് നോക്കി. അപ്പോൾ നെഞ്ച് അണിയിൽ നിന്നും പുറത്തേക്ക് തള്ളി നിൽക്കുന്നതായി കണ്ടു. അപ്പോൾ പ്രവാചകൻ പറഞ്ഞു: "നിങ്ങൾ അണികൾ ശരിപ്പെടുത്തുക തന്നെ വേണം. അല്ലെങ്കിൽ നിങ്ങളുടെ മുഖങ്ങളെ അല്ലാഹു ഭിന്നിപ്പിക്കും." (ബു,മു,ദ,തു,ന,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നൂഅ്മാനുബ്നു ബഷീർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَخَلَّلُ الصَّفَّ مِنْ نَاحِيَةٍ إِلَى نَاحِيَةٍ: يَمْسَحُ صُدُورَنَا وَمَنَاكِبَنَا، وَيَقُولُ: "لَا تَخْتَلِفُوا، فَتَخْتَلِفَ قُلُوبُكُمْ". وَكَانَ يَقُولُ: "إِنَّ اللهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصُّفُوفِ الْأُوَلِ". (د,ن)', 'ബറാഉബ്നു ആസിബ്(റ): നബി(സ) അണികൾ ഒരറ്റം മുതൽ മറ്റേയറ്റം വരെ ശരിപ്പെടുത്തും. ഞങ്ങളുടെ ചുമലുകളും നെഞ്ചുകളും തടകി നോക്കും. അവിടുന്ന് പറയും: "നിങ്ങൾ അകന്ന് നിൽക്കരുത്. അപ്പോൾ നിങ്ങളുടെ ഹൃദയങ്ങൾ അകലും." പിന്നീട് ഇപ്രകാരം പറയും: "അല്ലാഹുവും അവന്റെ മലക്കുകളും ആദ്യത്തെ അണികൾക്കുവേണ്ടി സ്വലാത്ത് ചൊല്ലുന്നു." (ദ,ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى رَجُلًا يُصَلِّي قَدْ صَفَّ بَيْنَ قَدَمَيْهِ، فَقَالَ: خَالَفَ – وَفِي رِوَايَةٍ: أَخْطَأَ – السُّنَّةَ، وَلَوْ رَاوَحَ بَيْنَهُمَا كَانَ أَفْضَلَ. كَانَ أَعْجَبَ إِلَيَّ. (ن)', 'ഒരിക്കൽ ഒരാൾ തന്റെ ഇരു പാദങ്ങൾ ചേർത്തി വെച്ചു നിസ്കരിക്കുന്നത് കപ്പോൾ ഇബ്നുമസ്ഊദ്(റ) പറഞ്ഞു: ''(ഇയാൾ) സുന്നത്തിനെതിർ പ്രവർത്തിച്ചു - മറ്റൊരു റിപ്പോർട്ടിൽ: സുന്നത്ത് തെറ്റിച്ചു - ഇദ്ദേഹം തന്റെ ഇരു പാദങ്ങൾ അകറ്റി വെച്ചിരുന്നെങ്കിൽ അതായിരിക്കും ശ്രേഷ്ടമായത്. അതാണ് എനിക്കു പ്രിയങ്കരമായത്. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', null, null, null, array['ن']::text[], array['ന']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=117), 1, 'وَفِي رِوَايَةٍ: أَخْطَأَ – السُّنَّةَ، وَلَوْ رَاوَحَ بَيْنَهُمَا كَانَ أَفْضَلَ. كَانَ أَعْجَبَ إِلَيَّ. (ن)', 'മറ്റൊരു നിവേദനിൽ: സുന്നത്ത് തെറ്റിച്ചു - ഇദ്ദേഹം തന്റെ ഇരു പാദങ്ങൾ അകറ്റി വെച്ചിരുന്നെങ്കിൽ അതായിരിക്കും ശ്രേഷ്ടമായത്. അതാണ് എനിക്കു പ്രിയങ്കരമായത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُسَوِّي صُفُوفَنَا إِذَا قُمْنَا لِلصَّلَاةِ، فَإِذَا اسْتَوَيْنَا كَبَّرَ. (د)', 'നൂഅ്മാനുബ്നു ബശീർ(റ): നബി(സ) ഞങ്ങളുടെ അണികൾ നേരെയാക്കാറുണ്ടായിരുന്നു. ഞങ്ങൾ നേരേ നിന്നാൽ തക്ബീർ ചൊല്ലും. (ദ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നൂഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 421, 421, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "اسْتَوُوا، اسْتَوُوا، اسْتَوُوا، فَوَالَّذِي نَفْسِي بِيَدِهِ! إِنِّي لَأَرَاكُمْ مِنْ خَلْفِي كَمَا أَرَاكُمْ مِنْ بَيْنِ يَدَيَّ". (خ,ن)', 'അനസ്(റ): നബി(സ) പറയാറുണ്ട്: "നിങ്ങൾ അണികൾ ശരിപ്പെടുത്തൂ, നിങ്ങൾ അണികൾ ശരിപ്പെടുത്തൂ, നിങ്ങൾ അണികൾ ശരിപ്പെടുത്തൂ. എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനിൽ തന്നെ സത്യം! ഞാൻ നിങ്ങളെ എന്റെ മുന്നിൽ നിന്ന് കാണുന്നതുപോലെ പിന്നിൽനിന്നും കാണുന്നു." (ബു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَقِيمُوا صُفُوفَكُمْ وَتَرَاصُّوا، فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي". (خ)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സ്വഫ്ഫുകൾ ശരിപ്പെടുത്തുകയും, വിടവ് തീർത്തു നിൽക്കുകയും ചെയ്യുക. ഞാൻ എന്റെ പിന്നിലൂടെ നിങ്ങളെ കാണുന്നുണ്ട്." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَقِيمُوا الصُّفُوفَ، وَحَاذُوا بَيْنَ الْمَنَاكِبِ، وَسُدُّوا الْخَلَلَ، وَلِينُوا بِأَيْدِي إِخْوَانِكُمْ، وَلَا تَذَرُوا فُرُجَاتٍ لِلشَّيْطَانِ، وَمَنْ وَصَلَ صَفًّا وَصَلَهُ اللهُ، وَمَنْ قَطَعَ صَفًّا قَطَعَهُ اللهُ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അണികളായി നിൽക്കുക. ചുമലുകൾക്കിടയിൽ ചേർന്ന് നിൽക്കുക. വിടവുകൾ നികത്തുക. നിങ്ങളുടെ സഹോദരങ്ങളുടെ കൈകളോട് ചേർന്നു നിൽക്കുക. നിങ്ങൾ പിശാചിനുവേണ്ടി വിടവുകൾ നൽകരുത്. ആരെങ്കിലും അണി ചേർത്താൽ അല്ലാഹു അവനെ ചേർക്കുന്നു (അവനുമായി അല്ലാഹു ബന്ധം ചേർക്കുന്നു). ആരെങ്കിലും അണി മുറിച്ചാൽ അല്ലാഹു അവനെ മുറിക്കുന്നു (അവനുമായി ബന്ധം മുറിക്കുന്നു)." (ദ,ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رُصُّوا صُفُوفَكُمْ، وَقَارِبُوا بَيْنَهَا، وَحَاذُوا بِالْأَعْنَاقِ، فَوَالَّذِي نَفْسِي بِيَدِهِ! إِنِّي لَأَرَى الشَّيْطَانَ يَدْخُلُ مِنْ خَلَلِ الصَّفِّ كَأَنَّهَا الْحَذَفُ". (د,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ അണികൾ ചേർത്ത് നിൽക്കുക. അടുത്തു നിൽക്കുക. പിരടികൾ നേരെയാക്കുക. എന്റെ ശരീരം ഉടമപ്പെടുത്തിയവനാണെ! അണിയുടെ വിടവിലൂടെ ചെറിയ ആട്ടിൻകുട്ടിയെപ്പോലെ പിശാച് പ്രവേശിക്കുന്നത് ഞാൻ കാണുന്നു;." (ദ,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سَوُّوا صُفُوفَكُمْ، فَإِنَّ تَسْوِيَةَ الصَّفِّ مِنْ تَمَامِ الصَّلَاةِ". (ق,د,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ അണികൾ ശരിപ്പെടുത്തുക. അണികൾ ശരിപ്പെടുത്തൽ നിസ്കാരത്തിന്റെ പൂർണ്ണതയിൽ പെട്ടതാണ്." (ബു,മു,ദ,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 422, 422, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ مُحَمَّدِ بْنِ مُسْلِمِ بْنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ إِلَى جَنْبِ أَنَسِ بْنِ مَالِكٍ يَوْمًا، فَقَالَ: هَلْ تَدْرِي لِمَ صُنِعَ هَذَا الْعُودُ؟ فَقُلْتُ: لَا، وَاللهِ! قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَضَعُ يَدَهُ عَلَيْهِ، فَيَقُولُ: "اسْتَوُوا، وَعَدِّلُوا صُفُوفَكُمْ". وَفِي رِوَايَةٍ: قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ أَخَذَهُ بِيَمِينِهِ، ثُمَّ الْتَفَتَ فَقَالَ: "اعْتَدِلُوا، سَوُّوا صُفُوفَكُمْ" ثُمَّ أَخَذَهُ بِيَسَارِهِ فَقَالَ: "اعْتَدِلُوا، سَوُّوا صُفُوفَكُمْ". (د)', 'മുഹമ്മദുബ്നു മുസ്ലിമിബ്നുസാഇബ്(റ): ഞാൻ ഒരിക്കൽ അനസുബ്നു മാലികിനോടൊപ്പം നിസ്കരിച്ചു. അദ്ദേഹം ചോദിച്ചു: ഈ വടി എന്തിനുള്ളതാണെന്നറിയുമോ? ഞാൻ പറഞ്ഞു: അല്ലാഹുവാണെ! എനിക്കറിയില്ല. അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഇതിൽ കൈ വെച്ചു പറയും: "നിങ്ങളുടെ അണികൾ ക്രമത്തിലും ചിട്ടയിലുമാക്കുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=124), 1, 'وَفِي رِوَايَةٍ: قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ أَخَذَهُ بِيَمِينِهِ، ثُمَّ الْتَفَتَ فَقَالَ: "اعْتَدِلُوا، سَوُّوا صُفُوفَكُمْ" ثُمَّ أَخَذَهُ بِيَسَارِهِ فَقَالَ: "اعْتَدِلُوا، سَوُّوا صُفُوفَكُمْ". (د)', 'മറ്റൊരു നിവേദനിൽ: അനസ്(റ) പറഞ്ഞു: നിശ്ചയം, നബി(സ) നിസ്കാരത്തിന് വന്നാൽ വലത് കയ്യിൽ വടി പിടിച്ചശേഷം തിരിഞ്ഞുനോക്കിപ്പറയും: "നേരെ നിന്ന് അണികൾ ശരിപ്പെടുത്തുക." പിന്നെ ഇടതു കയ്യിൽ പിടിച്ച് തിരിഞ്ഞു നോക്കിപ്പറയും. "നേരെ നിന്ന് അണികൾ ശരിപ്പെടുത്തുക." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَتِمُّوا الصَّفَّ الْمُقَدَّمَ، ثُمَّ الَّذِي يَلِيهِ، فَمَا كَانَ مِنْ نَقْصٍ فَلْيَكُنْ فِي الصَّفِّ الْمُؤَخَّرِ". (د,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ മുന്നിലെ അണി പൂർത്തിയാക്കുക. പിന്നെ അതിന് ശേഷമുള്ളതും. വല്ല കുറവുമുണ്ടെങ്കിൽ അത് പിന്നിലത്തേതിലാവട്ടെ." (ദ,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خِيَارُكُمْ أَلْيَنُكُمْ مَنَاكِبًا فِي الصَّلَاةِ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഉത്തമർ നിസ്കാരത്തിൽ ചുമലുകൾ ശരിപ്പെടുത്തുന്നവരാണ്." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُقِيمَتِ الصَّلَاةُ فَقُمْنَا، فَعُدِّلَتِ الصُّفُوفُ قَبْلَ أَنْ يَخْرُجَ إِلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِذَا قَامَ فِي مُصَلَّاهُ قَبْلَ أَنْ يُكَبِّرَ فَانْصَرَفَ، فَقَالَ لَنَا: "مَكَانَكُمْ" فَلَمْ نَزَلْ قِيَامًا نَنْتَظِرُهُ حَتَّى خَرَجَ إِلَيْنَا قَدِ اغْتَسَلَ، يَنْطُفُ رَأْسُهُ مَاءً، فَكَبَّرَ وَصَلَّى. (م,ن)', 'അബൂ ഹുറൈറ(റ): നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിക്കപ്പെട്ടു. അപ്പോൾ ഞങ്ങൾ എഴുന്നേറ്റ് നിന്നു. നബി(സ) ഞങ്ങളുടെ അടുത്തേക്ക് വരുന്നതിന്ന് മുമ്പു തന്നെ ഞങ്ങൾ അണികൾ ശരിപ്പെടുത്തി. നബി(സ) വന്ന് മുസ്വല്ലയിൽ നിന്ന് തക്ബീർ ചൊല്ലുന്നതിന് മുമ്പ് തന്നെ തിരിച്ചുപോയി. നബി(സ) ഞങ്ങളോട് പറഞ്ഞു: "നിങ്ങൾ അവിടെ നിൽക്കുക." ഞങ്ങൾ നബിയെ പ്രതീക്ഷിച്ച് അവിടെ നിന്നു. നബി(സ) പുറത്തുവന്നു. അവിടുന്ന് കുളിച്ചിട്ടുണ്ടായിരുന്നു. തലയിൽ നിന്ന് വെള്ളമുറ്റുന്നുണ്ട്. അവിടുന്ന് തക്ബീർ ചൊല്ലി നിസ്കരിച്ചു. (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂ ഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُ صُفُوفِ الرِّجَالِ أَوَّلُهَا، وَشَرُّهَا آخِرُهَا، وَخَيْرُ صُفُوفِ النِّسَاءِ آخِرُهَا، وَشَرُّهَا أَوَّلُهَا". (م,د,ت,ن,جه)', 'അബൂ ഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പുരുഷന്മാർക്ക് അണികളിൽ ഏറ്റവും ഉത്തമമായത് ഒന്നാമത്തേതും മോശമായത് അവസാനത്തേതുമാണ്. സ്ത്രീകൾക്ക് അണികളിൽ ഏറ്റവും ഉത്തമമായത് അവസാനത്തേതും മോശമായത് ആദ്യത്തേതുമാണ്." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂ ഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "لَوْ أَنَّ النَّاسَ يَعْلَمُونَ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ يَسْتَهِمُوا عَلَيْهِ لَاسْتَهَمُوا عَلَيْهِ". (ق,ت)', 'അബൂ ഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ബാങ്കിലും ഒന്നാമത്തെ അണിയിലുമുള്ള മഹത്വം ജനം അറിഞ്ഞിരുന്നുവെങ്കിൽ, പിന്നെ അത് ലഭിക്കാൻ നറുക്കെടുക്കേണ്ടി വരുമെങ്കിൽ അതിന് നറുക്കെടുക്കാനും അവർ തയ്യാറാകുമായിരുന്നു." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂ ഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ عِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْتَغْفِرُ لِلصَّفِّ الْمُقَدَّمِ ثَلَاثًا وَلِلثَّانِي مَرَّةً. (ن,جه)', 'ഇർബാളുബ്നു സാരിയ(റ): നിശ്ചയം, നബി(സ) ഒന്നാമത്തെ അണിക്കുവേണ്ടി മൂന്നുതവണ പാപമോചനം തേടി. രണ്ടാമത്തെ അണിക്കുവേണ്ടി ഒരു തവണയും. (ന,ജ)', 'عِرْبَاضِ بْنِ سَارِيَةَ', 'ഇർബാളുബ്നു സാരിയ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 423, 423, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى مَيَامِنِ الصُّفُوفِ". (د,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവും അവന്റെ മലക്കുകളും അണികളുടെ വലതു ഭാഗത്തുള്ളവർക്ക് സ്വലാത്ത് ചൊല്ലുന്നു (അനുഗ്രഹ പ്രാർത്ഥന നടത്തുന്നു)." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إِذَا صَلَّيْنَا خَلْفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِمَّا نُحِبُّ – أَوْ مِمَّا أُحِبُّ – أَنْ نَقُومَ عَنْ يَمِينِهِ. (م,د,ن,جه)', 'ബറാഉബ്നു ആസിബ്(റ): ഞങ്ങൾ നബി(സ)യുടെ പിന്നിൽ നിന്ന് നിസ്കരിക്കുമ്പോൾ വലതുവശത്ത് നിൽക്കാൻ ഇഷ്ടപ്പെട്ടിരുന്നു. (മു,ദ,ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قِيلَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مَيْسَرَةَ الْمَسْجِدِ تَعَطَّلَتْ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَمَّرَ مَيْسَرَةَ الْمَسْجِدِ كُتِبَ لَهُ كِفْلَانِ مِنَ الْأَجْرِ". (جه)', 'ഇബ്നു ഉമർ(റ): പള്ളിയുടെ ഇടതുഭാഗം അണി ഒഴിവാക്കിയിടുന്നതായി നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും പള്ളിയുടെ ഇടതു ഭാഗത്ത് നിസ്കരിച്ചാൽ (അണിയിൽ ഇമാമിന്റെ ഇടതു ഭാഗത്ത് വന്നിട്ടുള്ള ഒഴിവ് നികത്തും വിധം ആ ഭാഗത്ത് നിന്നുകൊണ്ട് നിസ്കരിച്ചാൽ) അയാൾ രണ്ട് പ്രതിഫലത്തിനർഹനായി". (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ قَوْمٌ يَتَأَخَّرُونَ عَنِ الصَّفِّ الْأَوَّلِ حَتَّى يُؤَخِّرَهُمُ اللهُ فِي النَّارِ". (د)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ഒരു ജനത ആദ്യ അണിയിൽ നിന്നും പിന്നോട്ടു പോകുംതോറും അല്ലാഹു അവരെ നരകത്തിൽ പിന്തള്ളിക്കൊണ്ടേയിരിക്കും." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ وَابِصَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يُصَلِّي خَلْفَ الصَّفِّ وَحْدَهُ، فَأَمَرَهُ أَنْ يُعِيدَ الصَّلَاةَ. (د,ت,جه)', 'വാബിസ്വ(റ): നബി(സ) ഒരാളെ അണിക്കു പിന്നിൽ ഒറ്റക്ക് നിസ്കരിക്കുന്നതായി കണ്ടപ്പോൾ അയാളോട് മടക്കി നിസ്കരിക്കാൻ കൽപിച്ചു. (ദ,തു,ജ)', 'وَابِصَةَ', 'വാബിസ്വ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ عَلِيِّ بْنِ شَيْبَانَ رَضِيَ اللهُ عَنْهُ – وَكَانَ مِنَ الْوَفْدِ – قَالَ: خَرَجْنَا حَتَّى قَدِمْنَا عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَبَايَعْنَاهُ، وَصَلَّيْنَا خَلْفَهُ، ثُمَّ صَلَّيْنَا وَرَاءَهُ صَلَاةً أُخْرَى، فَقَضَى الصَّلَاةَ، فَرَأَى رَجُلًا فَرْدًا يُصَلِّي خَلْفَ الصَّفِّ، قَالَ: فَوَقَفَ عَلَيْهِ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ انْصَرَفَ، قَالَ: "اسْتَقْبِلْ صَلَاتَكَ، لَا صَلَاةَ لِلَّذِي خَلْفَ الصَّفِّ". (جه)', 'അലിയ്യുബ്നു ശൈബാൻ(റ): (അദ്ദേഹം ഒരു നിവേദക സംഘത്തിലായിരുന്നു) ഞങ്ങൾ നബി(സ)യുടെ അടുത്തേക്ക് പുറപ്പെട്ടു. നബിയുമായി ഉടമ്പടി ചെയ്തു. നബിയുടെ പിന്നിൽ നിന്ന് നിസ്കരിച്ചു. മറ്റൊരു നിസ്കാരം കൂടി നബിയുടെ പിന്നിൽ നിസ്കരിച്ചു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ ഒരാൾ അണിക്ക് പിന്നിൽ ഒറ്റക്ക് നിസ്കരിക്കുന്നത് കണ്ടു. അയാൾ നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചപ്പോൾ നബി(സ) അയാളുടെ അടുത്ത് നിന്ന് പറഞ്ഞു: "നീ നിസ്കാരം മടക്കി നിർവ്വഹിക്കുക. അണിക്ക് പിന്നിൽ നിൽക്കുന്നവന് നിസ്കാരമില്ല." (ജ)', 'عَلِيِّ بْنِ شَيْبَانَ', 'അലിയ്യുബ്നു ശൈബാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 424, 424, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ جَاءَ وَرَسُولُ اللهِ رَاكِعٌ، فَرَكَعَ دُونَ الصَّفِّ، ثُمَّ مَشَى إِلَى الصَّفِّ، فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ قَالَ: "أَيُّكُمُ الَّذِي رَكَعَ دُونَ الصَّفِّ؟ ثُمَّ مَشَى إِلَى الصَّفِّ" فَقَالَ أَبُو بَكْرَةَ: أَنَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "زَادَكَ اللهُ حِرْصًا، وَلَا تَعُدْ". (خ,د,ن)', 'അബൂബക്റ(റ): നബി(സ) റകൂഇലായിരിക്കെ അദ്ദേഹം കടന്നുവന്ന് അണിയിൽ നിൽക്കാതെ റുകൂഅ് ചെയ്തു. എന്നിട്ട് അണിയിലേക്ക് നടന്നു ചെന്നു. നബി(സ) നിസ്കാരം നിർവ്വഹിച്ചു കഴിഞ്ഞപ്പോൾ ചോദിച്ചു. "നിങ്ങളിലാരാണ് അണിയിൽ നിന്ന് മാറി റുകൂഅ് ചെയ്തശേഷം അണിയിലേക്ക് വന്നത്?" അപ്പോൾ അബൂബക്റ പറഞ്ഞു. ഞാനാണ്. നബി(സ) പറഞ്ഞു: "അല്ലാഹു നിനക്ക് ആർത്തി വർദ്ധിപ്പിക്കട്ടെ! ഇനി ഇതാവർത്തിക്കരുത്." (ബു,ദ,ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 425, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَمَا يَخْشَى أَحَدُكُمْ – أَوْ لَا يَخْشَى أَحَدُكُمْ – إِذَا رَفَعَ رَأْسَهُ قَبْلَ الْإِمَامِ أَنْ يَجْعَلَ اللهُ رَأْسَهُ رَأْسَ حِمَارٍ، أَوْ يَجْعَلَ اللهُ صُورَتَهُ صُورَةَ حِمَارٍ". (خ,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇമാം സുജൂദിൽ നിന്ന് തലയുയർത്തുന്നതിനു മുമ്പ് നിങ്ങളിൽ തല ഉയർത്തുന്നവന്റെ തല കഴുതയുടെ തലയാക്കപ്പെടുന്നത്, അല്ലെങ്കിൽ അവനെ കഴുതയുടെ രൂപത്തിലാക്കപ്പെടുന്നത് നിങ്ങൾ ഭയക്കുന്നില്ലേ?" (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 425, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ: "مَا يَأْمَنُ الَّذِي يَرْفَعُ رَأْسَهُ فِي صَلَاتِهِ قَبْلَ الْإِمَامِ أَنْ يُحَوِّلَ اللهُ صُورَتَهُ فِي صُورَةِ حِمَارٍ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇമാമിനു മുമ്പായി നിസ്കാരത്തിൽ തല ഉയർത്തുന്നവർ അല്ലാഹു അവരുടെ രൂപം കഴുതകളാക്കുന്നതിൽ നിന്ന് നിർഭയരല്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 425, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّهُمْ كَانُوا إِذَا صَلَّوْا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَرَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ، قَامُوا قِيَامًا حَتَّى يَرَوْهُ سَاجِدًا ثُمَّ سَجَدُوا. (ن)', 'ബറാഅ്(റ): അവർ നബി(സ)യോടൊപ്പം നിസ്കരിക്കുമ്പോൾ നബി റുകൂഇൽ നിന്നുയർന്നാൽ അവർ നേരെ നിൽക്കും; നബി(സ) സുജൂദിലെത്തി എന്ന് കാണുംവരെ അവർ നിർത്തത്തിൽ തുടരും. പിന്നെ സുജൂദ് ചെയ്യും. (ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 425, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: حَدِيثُ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِهِ وَهُوَ شَاكٍ تَقَدَّمَ، وَفِي هَذِهِ الرِّوَايَةِ قَالَ: "وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا". (خ)', 'ആഇശ(റ): നബി(സ) വീട്ടിൽവെച്ച് സംശയാസ്പദമായി നിസ്കരിച്ചതു സംബന്ധിച്ച് പറയുന്ന ഹദീസ് മുമ്പ് പറഞ്ഞു. ഈ റിപ്പോർട്ടിൽ: നബി(സ) പറഞ്ഞു: "ഇമാം ഇരുന്ന് നിസ്കരിക്കുകയാണെങ്കിൽ നിങ്ങളും ഇരുന്ന് നിസ്കരിക്കുക." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 425, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ" لَمْ يَحْنِ أَحَدٌ مِنَّا ظَهْرَهُ حَتَّى يَقَعَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَاجِدًا، ثُمَّ نَقَعُ سُجُودًا بَعْدَهُ. (خ)', 'ബറാഅ്(റ): നബി(സ) ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്നു പറഞ്ഞാൽ നബി സുജൂദ് ചെയ്യുന്നതു വരെ ഞങ്ങളിലൊരാളും തന്റെ മുതുക് കുനിച്ചിരുന്നില്ല. പിന്നെ ഞങ്ങൾ സുജൂദ് ചെയ്യും. (ബു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 425, 425, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ حِطَّانَ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا أَبُو مُوسَى، فَلَمَّا كَانَ فِي الْقَعْدَةِ دَخَلَ رَجُلٌ مِنَ الْقَوْمِ فَقَالَ: أُقِرَّتِ الصَّلَاةُ بِالْبِرِّ وَالزَّكَاةِ، فَلَمَّا سَلَّمَ أَبُو مُوسَى أَقْبَلَ عَلَى الْقَوْمِ فَقَالَ: أَيُّكُمُ الْقَائِلُ هَذِهِ الْكَلِمَةَ؟ فَأَرَمَّ الْقَوْمُ، قَالَ: يَا حِطَّانُ! لَعَلَّكَ قُلْتَهَا، قَالَ: لَا، وَقَدْ خَشِيتُ أَنْ تَبْكَعَنِي بِهَا: فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُنَا صَلَاتَنَا وَسُنَّتَنَا، فَقَالَ: إِنَّمَا الْإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا قَالَ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} فَقُولُوا آمِينَ، يُجِبْكُمُ اللهُ، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا رَفَعَ فَقَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَقُولُوا: رَبَّنَا لَكَ الْحَمْدُ، يَسْمَعِ اللهُ لَكُمْ، وَإِذَا سَجَدَ فَاسْجُدُوا، وَإِذَا رَفَعَ فَارْفَعُوا، فَإِنَّ الْإِمَامَ يَسْجُدُ قَبْلَكُمْ، وَيَرْفَعُ قَبْلَكُمْ، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَتِلْكَ بِتِلْكَ". (ن)', 'ഹിത്വാനുബ്നു അബ്ദില്ല(റ): അബൂമൂസ(റ) ഞങ്ങളുമായി നിസ്കരിച്ചു. അദ്ദേഹം ഇരുത്തത്തിലായിരിക്കേ ആ കൂട്ടത്തിൽ ഒരാൾ കടന്നുവന്ന് പറഞ്ഞു: നിസ്കാരത്തോടൊപ്പം തന്നെ പുണ്യത്തേയും സകാത്തിനേയും സ്ഥാപിച്ചിരിക്കുന്നു. അബൂമൂസ(റ) സലാം വീട്ടിയശേഷം സമൂഹത്തോടായി ചോദിച്ചു: നിങ്ങളിൽ ആരാണ് ഈ വാക്ക് പറഞ്ഞത്? ആളുകൾ മൗനം പാലിച്ചു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: ഹിത്വാൻ! നീയാണോ അത് പറഞ്ഞത്? അയാൾ പറഞ്ഞു: അല്ല. അതിൽ എന്നെ കുറ്റപ്പെടുത്തുന്നത് ഞാൻ ഭയപ്പെട്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിശ്ചയം, നബി(സ) ഞങ്ങൾക്ക് നിസ്കാരവും ചര്യകളും പഠിപ്പിച്ചു തന്നുകൊണ്ട് പറഞ്ഞു: "ഇമാം തുടരപ്പെടേണ്ടവനാണ്. അദ്ദേഹം തക്ബീർ ചൊല്ലിയാൽ നിങ്ങളും തക്ബീർ ചൊല്ലുക. അദ്ദേഹം "...വലള്ളാല്ലീൻ" ചൊല്ലിയാൽ നിങ്ങൾ "ആമീൻ" എന്ന് ചൊല്ലുക. അല്ലാഹു നിങ്ങൾക്ക് ഉത്തരം നൽകും. ഇമാം റുകൂഅ് ചെയ്താൽ നിങ്ങളും റുകൂഅ് ചെയ്യുക. റുകൂഇൽ നിന്നുയർന്ന് "സമിഅല്ലാഹു ലിമൻ ഹമിദഹു" എന്ന് പറഞ്ഞാൽ നിങ്ങൾ "റബ്ബനാ ലകൽ ഹംദു" എന്ന് പറയുക. നിങ്ങളിൽ നിന്ന് അല്ലാഹു അത് കേൾക്കും. ഇമാം സുജൂദ് ചെയ്താൽ നിങ്ങളും സുജൂദ് ചെയ്യുക. ഇമാം അതിൽനിന്ന് ഉയർന്നാൽ നിങ്ങളും ഉയരുക. ഇമാം നിങ്ങൾക്ക് മുമ്പ് സുജൂദ് ചെയ്യേണ്ടതും എഴുന്നേൽക്കേണ്ടതുമാണ്." നബി(സ) പറഞ്ഞു. "അത് അപ്രകാരം തന്നെ നിർവ്വഹിക്കപ്പെടണം." (ന)', 'حِطَّانَ بْنِ عَبْدِ اللهِ', 'ഹിത്വാനുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَالَ أَحَدُكُمْ: آمِينَ، وَقَالَتِ الْمَلَائِكَةُ فِي السَّمَاءِ: آمِينَ، فَوَافَقَتْ إِحْدَاهُمَا الْأُخْرَى، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ ''ആമീൻ'' ചൊല്ലുകയും ആകാശത്തിലെ മലക്കുകളും ആമീൻ പറയുകയും, രണ്ടു കൂട്ടരുടെയും ആമീൻ ചൊല്ലൽ യോജിച്ചു വരികയും ചെയ്താൽ അവന്റെ മുൻകഴിഞ്ഞ ദോഷങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا، يَقُولُ: "لَا تُبَادِرُوا الْإِمَامَ، إِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا قَالَ {وَلَا الضَّالِّينَ} فَقُولُوا آمِينَ، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ فَقُولُوا: رَبَّنَا لَكَ الْحَمْدُ". (م)', 'അബൂ ഹുറൈറ(റ): നബി(സ) ഞങ്ങളെ പഠിപ്പിച്ചുകൊണ്ട് പറയാറുണ്ടായിരുന്നു: "നിങ്ങൾ ഇമാമിനെ മുൻകടക്കരുത്. അദ്ദേഹം തക്ബീർ ചൊല്ലിയാൽ നിങ്ങളും തക്ബീർ ചൊല്ലുക. അദ്ദേഹം ...വലല്ലാല്ലീൻ ചൊല്ലിയാൽ നിങ്ങൾ ആമീൻ എന്ന് ചൊല്ലുക. റുകൂഅ് ചെയ്താൽ നിങ്ങളും റുകൂഅ് ചെയ്യുക. സമിഅല്ലാഹു ലിമൻ ഹമിദഹു എന്ന് പറഞ്ഞാൽ നിങ്ങൾ ''റബ്ബനാ ലകൽ ഹംദു'' എന്ന് പറയുക." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂ ഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 426, 426, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَالَ الْإِمَامُ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇമാം ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്നു പറഞ്ഞാൽ നിങ്ങൾ ''അല്ലാഹുമ്മ റബ്ബനാലകൽ ഹംദു'' എന്നുപറയുക. കാരണം, ആരെങ്കിലും ഇതു ചൊല്ലുന്നത് മലക്കുകളുടേതിനോട് യോജിച്ചു വന്നാൽ അവന്റെ മുൻപാപങ്ങൾ പൊറുക്കപ്പെടും." (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 426, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَمَّنَ الْإِمَامُ فَأَمِّنُوا، فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ق,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇമാം ആമീൻ പറയുമ്പോൾ നിങ്ങളും ആമീൻ പറയുക, ആരുടെയെങ്കിലും ആമീൻ മലക്കുകളുടെ ആമീനുമായി യോജിച്ചുവന്നാൽ അവരുടെ മുൻകഴിഞ്ഞ പാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്" (ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} فَقَالَ: "آمِينَ" وَمَدَّ بِهَا صَوْتَهُ. حَسَنٌ. (م,د,ت,ن,جه)', 'വാഇലുബ്നു ഹിജ്ർ(റ): നബി(സ) "വലള്ളാല്ലീൻ" ഓതുന്നത് ഞാൻ കേട്ടു. അതിന്നുശേഷം ശബ്ദം നീട്ടി "ആമീൻ" എന്നു പറഞ്ഞു. ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു. (മു,ദ,തു,ന,ജ)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹിജ്ർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَأُقَرِّبَنَّ صَلَاةَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكَانَ أَبُو هُرَيْرَةَ يَقْنُتُ فِي الرَّكْعَةِ الْأُخْرَى مِنْ صَلَاةِ الظُّهْرِ، وَصَلَاةِ الْعِشَاءِ، وَصَلَاةِ الصُّبْحِ بَعْدَ مَا يَقُولُ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَيَدْعُو لِلْمُؤْمِنِينَ وَيَلْعَنُ الْكُفَّارَ. (خ)', 'അബൂഹുറൈറ(റ): ഞാൻ നബി(സ)യുടെ നിസ്കാരത്തോട് അടുക്കുകതന്നെ ചെയ്യും. അബൂഹുറൈറ ളുഹ്റിലെയും ഇശാഇലെയും സുബ്ഹ്ലെയും രണ്ടാമത്തെ റക്അത്തിൽ ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്നുപറഞ്ഞതിനുശേഷം ഖുനൂത്ത് ഓതാറുണ്ടായിരുന്നു. അങ്ങനെ മുസ്ലിംകൾക്കു വേണ്ടി പ്രാർത്ഥിക്കുകയും അവിശ്വാസികളെ ശപിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا يَوْمًا نُصَلِّي وَرَاءَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَفَعَ رَأْسَهُ مِنَ الرَّكْعَةِ قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ". قَالَ رَجُلٌ وَرَاءَهُ: رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، فَلَمَّا انْصَرَفَ قَالَ: "مَنِ الْمُتَكَلِّمُ؟" قَالَ: أَنَا قَالَ: "رَأَيْتُ بِضْعَةً وَثَلَاثِينَ مَلَكًا يَبْتَدِرُونَهَا، أَيُّهُمْ يَكْتُبُهَا أَوَّلُ". (خ)', 'രിഫാഅത്തുബ്നു റാഫിഉസ്സുറഖി(റ): ഒരിക്കൽ ഞങ്ങൾ നബി(സ)ക്കു പിന്നിൽ നിസ്കരിക്കുകയായിരുന്നു. നബി(സ) തലയുയർത്തിയപ്പോൾ ''സമിഅല്ലാഹു ലിമൻഹമിദഹു'' എന്നു പറഞ്ഞു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: ''റബ്ബനാലകൽ ഹംദു, ഹംദൻ ത്വയ്യിബൻ മുബാറകൻഫീഹി'' നിസ്കാര ശേഷം നബി(സ) ചോദിച്ചു: "ആരാണ് നിസ്കാരത്തിൽ സംസാരിച്ചത്?" അദ്ദേഹം ഞാനാണെന്നു പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "തീർച്ചയായും മുപ്പതിൽ കൂടുതൽ മലക്കുകൾ ഇത് ആദ്യം എഴുതുന്നതിനായി തർക്കിക്കുന്നതു ഞാൻ കണ്ടു." (ബു)', 'رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ', 'രിഫാഅത്തുബ്നു റാഫിഉസ്സുറഖി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَضَّهُمْ عَلَى الصَّلَاةِ، وَنَهَاهُمْ أَنْ يَنْصَرِفُوا قَبْلَ انْصِرَافِهِ مِنَ الصَّلَاةِ. (د)', 'അനസ്(റ): പ്രവാചകൻ(സ) അവരെ (അനുചരന്മാരെ) (സംഘടിത) നിസ്കാരത്തിന് പ്രോൽസാഹിപ്പിച്ചു. തിരുമേനി(സ) നിസ്കാരത്തിൽ നിന്നും പിരിഞ്ഞു പോകും മുമ്പ് അവർ പിരിഞ്ഞു പോകുന്നതിനെ അവിടുന്ന് വിലക്കി. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 427, 427, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ رَضِيَ اللهُ عَنْهُ يَقُولُ: كَانَ آخِرُ مَا عَهِدَ إِلَيَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ أَمَّرَنِي عَلَى الطَّائِفِ قَالَ لِي: "يَا عُثْمَانُ! تَجَاوَزْ فِي الصَّلَاةِ، وَاقْدِرِ النَّاسَ بِأَضْعَفِهِمْ، فَإِنَّ فِيهِمُ الْكَبِيرَ وَالصَّغِيرَ وَالسَّقِيمَ وَالْبَعِيدَ وَذَا الْحَاجَةِ. وَفِي رِوَايَةٍ: قَالَ: أَنَّ آخِرَ مَا قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "إِذَا أَمَمْتَ قَوْمًا فَأَخِفَّ بِهِمْ". (م,د,ن,جه)', 'ഉസ്മാനുബ്നു അബിൽആസ്(റ): ത്വാഇഫിലേക്ക് അമീറായി നിശ്ചയിച്ച് നബി(സ) എന്നോട് അവസാനമായി കരാർ ചെയ്തത് ഇങ്ങനെയാണ്: "ഉസ്മാൻ! നീ വേഗം നിസ്കാരം നിർവ്വഹിക്കുക. ജനങ്ങളുടെ ദൗർബല്യങ്ങൾ നീ കണക്കിലെടുക്കണം. അവരിൽ പ്രായമായവരും കുട്ടികളുമുണ്ട്. രോഗികളും ദൂരത്തുള്ളവരുമുണ്ട്. അത്യാവശ്യ കാര്യങ്ങൾ നിർവ്വഹിക്കേണ്ടവരുമുണ്ട്." മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) എന്നോട് അവസാനമായി പറഞ്ഞത്: "നീ ഒരു ജനതക്ക് ഇമാമായാൽ അവരെയുമായി നീ ലഘുവായി (ജമാഅത്ത് നിസ്കാരം) നിർവ്വഹിക്കുക". എന്നാണ്. (മു,ദ,ന,ജ)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ', 'ഉസ്മാനുബ്നു അബിൽആസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 428, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=152), 1, 'وَفِي رِوَايَةٍ: قَالَ: أَنَّ آخِرَ مَا قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "إِذَا أَمَمْتَ قَوْمًا فَأَخِفَّ بِهِمْ". (م,د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) എന്നോട് അവസാനമായി പറഞ്ഞത്: "നീ ഒരു ജനതക്ക് ഇമാമായാൽ അവരെയുമായി നീ ലഘുവായി (ജമാഅത്ത് നിസ്കാരം) നിർവ്വഹിക്കുക". എന്നാണ്. (മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ جابر رَضِيَ اللهُ عَنْهُ قَالَ: جاء رجل مِنَ الْأَنْصَارِ، وَقَدْ أُقِيمَتِ الصَّلَاةُ، فَدَخَلَ الْمَسْجِدَ، فصلَّى خلف مُعاذ، فطوَّل بِهِمْ، فَانْصَرَفَ الرَّجُلُ فَصَلَّى فِي نَاحِيَةِ الْمَسْجِدِ، ثُمَّ انْطَلَقَ، فَلَمَّا قَضَى مُعَاذٌ الصَّلَاةَ قِيلَ لَهُ: إِنَّ فُلَانًا فَعَلَ كَذَا وَكَذَا، فَقَالَ مُعَاذٌ: لَئِنْ أَصْبَحْتُ لَأَذْكُرَنَّ ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَى مُعَاذٌ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ ذَلِكَ لَهُ فَأَرْسَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِ، فَقَالَ: "مَا حَمَلَكَ عَلَى الَّذِي صَنَعْتَ؟" فَقَالَ: يَا رَسُولَ اللهِ! عَمِلْتُ عَلَى نَاضِحِي مِنَ النَّهَارِ، فَجِئْتُ وَقَدْ أُقِيمَتِ الصَّلَاةُ، فَدَخَلْتُ الْمَسْجِدَ، فَدَخَلْتُ مَعَهُ فِي الصَّلَاةِ، فَقَرَأَ سُورَةَ كَذَا وَكَذَا فَطَوَّلَ، فَانْصَرَفْتُ فَصَلَّيْتُ فِي نَاحِيَةِ الْمَسْجِدِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَفَتَّانٌ يَا مُعَاذُ، أَفَتَّانٌ يَا مُعَاذُ، أَفَتَّانٌ يَا مُعَاذُ". (م,ن,جه)', 'ജാബിർ(റ): നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിച്ചപ്പോൾ അൻസ്വാറുകളിൽപെട്ട ഒരാൾ പള്ളിയിൽ വന്ന് മുആദ്(റ)ന്റെ പിന്നിൽ നിസ്കരിച്ചു. അദ്ദേഹം (മുആദ്) അവരുമായി (നിസ്കാരം) ദീർഘിപ്പിച്ചു. അപ്പോൾ അയാൾ (ഇമാമുമായി) വേർപിരിഞ്ഞ് പള്ളിയുടെ ഒരു മൂലയിൽ നിന്ന് ഒറ്റക്ക് നിസ്കരിച്ചു തിരിച്ചുപോയി. മുആദ് നിസ്കാരം നിർവ്വഹിച്ച് കഴിഞ്ഞപ്പോൾ ഇന്നയാൾ ഇങ്ങനെയെല്ലാം ചെയ്തെന്ന വിവരം മുആദിനോട് അറിയിച്ചു. മുആദ് പറഞ്ഞു: നാളെ നേരം വെളുത്താൽ ഞാനിക്കാര്യം നബി(സ)യെ അറിയിക്കും. അങ്ങനെ മുആദ് നബി(സ)യുടെ അടുത്ത് വന്ന് കാര്യങ്ങൾ ധരിപ്പിച്ചു. നബി(സ) അദ്ദേഹത്തെ (ഒറ്റക്ക് നിസ്കരിച്ച് പിരിഞ്ഞുപോയ മനുഷ്യനെ) ആളയച്ചു വരുത്തി അന്വേഷിച്ചു. "നീ ചെയ്ത കാര്യത്തിന് നിന്നെ പ്രേരിപ്പിച്ചതെന്താണ്?" അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! പകലിൽ ഞാനെന്റെ ഒട്ടകവുമായി കൃഷിക്ക് നനക്കുകയായിരുന്നു. ഞാൻ വന്നപ്പോൾ ഇഖാമത്ത് വിളിച്ചിരുന്നു. അപ്പോൾ ഞാൻ പള്ളിയിൽ കയറി അദ്ദേഹത്തോടൊപ്പം നിസ്കരിക്കാൻ കൂടി. എന്നാൽ അദ്ദേഹം ഇന്നയിന്ന സൂറത്തുകൾ പാരായണം ചെയ്ത് ദീർഘിപ്പിച്ചു. അതിനാൽ ഞാൻ പിരിഞ്ഞുപോയി പള്ളിയുടെ ഒരു ഭാഗത്ത് നിന്ന് നിസ്കരിച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "മുആദ്! നീ കുഴപ്പക്കാരനാകുകയാണോ?, മുആദ്! നീ കുഴപ്പക്കാരനാകുകയാണോ?, മുആദ്! നീ കുഴപ്പക്കാരനാകുകയാണോ?" (മു,ന,ജ)', 'جابر', 'ജാബിർ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 428, 428, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ أَبِي صَالِحٍ رَضِيَ اللهُ عَنْهُ عَنْ بَعْضِ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ: "كَيْفَ تَقُولُ فِي الصَّلَاةِ؟" قَالَ: أَتَشَهَّدُ، وَأَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ، أَمَا إِنِّي لَا أُحْسِنُ دَنْدَنَتَكَ وَلَا دَنْدَنَةَ مُعَاذٍ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حَوْلَهَا نُدَنْدِنُ". (د,جه)', 'അബൂസ്വാലിഹ്(റ): നബിയുടെ ചില അനുയായികൾ പറഞ്ഞു: നബി(സ) ഒരാളോട് ചോദിച്ചു: "നീ നിസ്കാരത്തിൽ എപ്രകാരമാണ് പ്രാർത്ഥിച്ചത്?" അയാൾ പറഞ്ഞു: ഞാൻ തശഹ്ഹുദ് (അത്തഹിയ്യാത്ത്) നിർവ്വഹിക്കുന്നു. ഞാൻ പറയുന്നു: നാഥാ! ഞാൻ നിന്നോട് സ്വർഗ്ഗം ചോദിക്കുന്നു. നരകത്തിൽ നിന്ന് നിന്നോട് കാവൽ ചോദിക്കുന്നു. എന്നാൽ എനിക്ക് നിന്റെയോ മുആദിന്റേയോ പ്രാർത്ഥനകൾ അറിയില്ല. നബി(സ) പറഞ്ഞു: "അവ രണ്ടിനും ചുറ്റും തന്നെയാണ് ഞങ്ങളും പ്രാർത്ഥിക്കുന്നത്." (ദ,ജ)', 'أَبِي صَالِحٍ', 'അബൂസ്വാലിഹ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 428, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَقُومُ إِلَى الصَّلَاةِ وَأَنَا أُرِيدُ أَنْ أُطَوِّلَ فِيهَا، فَأَسْمَعُ بُكَاءَ الصَّبِيِّ فَأَتَجَوَّزُ، كَرَاهِيَةَ أَنْ أَشُقَّ عَلَى أُمِّهِ". (خ,د,ن,جه)', 'അബൂഖതാദ(റ): തിരുമേനി(സ) പറഞ്ഞു: ഞാൻ നിസ്കാരത്തിനു നിൽക്കുകയും നിസ്കാരം ദീർഘിപ്പിക്കാനുദ്ദേശിക്കുകയും ചെയ്യും. അങ്ങ ഞാൻ കുഞ്ഞുന്റെ കരച്ചിൽ കേൽക്കുമ്പോൾ അതിന്റെ ഉമ്മയ്ക്ക് ഞാൻ പ്രയാസം സൃഷ്ടിക്കുന്നതിനെ ഞാൻ വെറുക്കുന്നതിനാൽ നിസ്കാരം ലഘുവാക്കും (ബു,ദ,ന,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ حَزْمِ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَى مُعَاذَ بْنَ جَبَلٍ رَضِيَ اللهُ عَنْهُ وَهُوَ يُصَلِّي بِقَوْمٍ صَلَاةَ الْمَغْرِبِ، فِي هَذَا الْخَبَرِ، قَالَ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا مُعَاذُ، لَا تَكُنْ فَتَّانًا، فَإِنَّهُ يُصَلِّي وَرَاءَكَ الْكَبِيرُ وَالضَّعِيفُ وَذُو الْحَاجَةِ وَالْمُسَافِرُ". (د)', 'ഹസമുബ്നു കഅ്ബ്(റ): മുആദ്(റ) മഗ്രിബ് നിസ്കരിച്ചുകൊണ്ടിരിക്കെ ഹസമുബ്നു കഅ്ബ് മുആദിന്റെ അടുക്കൽ കടന്നു ചെന്നു..... (ഈ വിഷയകമായി ഹദിസ് വന്നിട്ടുണ്ട്)....... അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: ഓ മുആദ്! നീ കുഴപ്പക്കാരനാകരുത്! നിശ്ചയം, നിന്റെ പിന്നിൽ വലിയവരും, ദുർബ്ബലരും, ആവശ്യമുള്ളവരും, യാത്രക്കാരുമുണ്ട്. (ദ)', 'حَزْمِ بْنِ كَعْبٍ', 'ഹസമുബ്നു കഅ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، ذَكَرَ قِصَّةَ مُعَاذٍ رَضِيَ اللهُ عَنْهُ، قَالَ: وَقَالَ – يَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – لِلْفَتَى: "كَيْفَ تَصْنَعُ يَا ابْنَ أَخِي إِذَا صَلَّيْتَ". قَالَ: أَقْرَأُ بِفَاتِحَةِ الْكِتَابِ، وَأَسْأَلُ اللهَ الْجَنَّةَ، وَأَعُوذُ بِهِ مِنَ النَّارِ، وَإِنِّي لَا أَدْرِي مَا دَنْدَنَتُكَ وَلَا دَنْدَنَةُ مُعَاذٍ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي وَمُعَاذًا حَوْلَ هَاتَيْنِ". أَوْ: "نَحْوَ هَذَا". (د)', 'ജാബിർ(റ), മുആദുമായി ബന്ധപ്പെട്ട സംഭവം റിപ്പോർട്ട് ചെയ്യുന്നു: ജാബിർ(റ) പറയുന്നു: നബി(സ) ഒരു യുവാവിനോട് ചോദിച്ചു: എന്റെ സഹോദര പുത്രാ! നീ നിസ്കരാത്തിൽ എന്താണ് ചെയ്യാറുള്ളത്? അദ്ദേഹം പറഞ്ഞു: ഞാൻ ''ഫാത്തിഹ'' പാരായണം ചെയ്യുകയും, അല്ലാഹുവിനോട് സ്വർഗ്ഗത്തെ തേടുകയും, അവനോട് നരകത്തിൽ നിന്നും രക്ഷതേടുകയും ചെയ്യും. താങ്കളുടെ പ്രാർത്ഥനയോ മുആദിന്റെ പ്രാർത്ഥനയോ എന്താണെന്ന് എനിക്കറിയില്ല. ഞാനും മുആദും ഏറെക്കുറെ ഇവ രണ്ടിനും (സ്വർഗ്ഗത്തിനും നരകത്തിനും) സമീപത്തു തന്നെയാണ്. അല്ലെങ്കിൽ: ഇതിനു സമാനമായതു തന്നെയാണ് (പ്രാർത്ഥിക്കുക). (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ مُعَاذُ ابْنُ جَبَلٍ يُصَلِّي مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ يَرْجِعُ فَيَؤُمُّ قَوْمَهُ، فَصَلَّى الْعِشَاءَ فَقَرَأَ بِالْبَقَرَةِ، فَانْصَرَفَ الرَّجُلُ فَكَأَنَّ مُعَاذًا تَنَاوَلَ مِنْهُ، فَبَلَغَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "فَتَّانٌ، فَتَّانٌ، فَتَّانٌ" ثَلَاثَ مِرَارٍ، وَأَمَرَهُ بِسُورَتَيْنِ مِنْ أَوْسَطِ الْمُفَصَّلِ. وَفِي رِوَايَةٍ: قَالَ لَهُ: "فَلَوْلَا صَلَّيْتَ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}، وَ{وَالشَّمْسِ وَضُحَاهَا}، {وَاللَّيْلِ إِذَا يَغْشَى}". (خ,ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): മുആദുബ്നു ജബൽ(റ) നബിയോടൊപ്പം നിസ്കരിച്ചു, തിരിച്ചുപോയി തന്റെ ജനതക്ക് ഇമാമായി ഇശാഅ് നിസ്കരിച്ചു. അൽബഖറഃയാണ് ഓതിയത്. അപ്പോൾ ഒരാൾ പിരിഞ്ഞുപോയി. മുആദിന് അദ്ദേഹത്തിന്റെ കാര്യത്തിൽ പ്രയാസം തോന്നി. വിഷയം നബി(സ)യുടെ മുന്നിലെത്തി. നബി(സ) പറഞ്ഞു: "കുഴപ്പക്കാരൻ!, കുഴപ്പക്കാരൻ!, കുഴപ്പക്കാരൻ!." എന്നിട്ട് അവസാന ഭാഗത്തുള്ള രണ്ട് സൂറത്തുകൾ (ഇടത്തരം) ഓതാൻ നിർദ്ദേശിച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) അദ്ദേഹത്തോട് ചോദിച്ചു. "സബ്ബിഹിസ്മ, വശ്ശംസി, വല്ലൈലി എന്നിവ ഓതി നിസ്കരിച്ചാൽ പോരേ?" (ബു,ന)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 429, 429, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=158), 1, 'وَفِي رِوَايَةٍ: قَالَ لَهُ: "فَلَوْلَا صَلَّيْتَ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}، وَ{وَالشَّمْسِ وَضُحَاهَا}، {وَاللَّيْلِ إِذَا يَغْشَى}". (خ,ن)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) അദ്ദേഹത്തോട് ചോദിച്ചു. "സബ്ബിഹിസ്മ, വശ്ശംസി, വല്ലൈലി എന്നിവ ഓതി നിസ്കരിച്ചാൽ പോരേ?" (ബു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: وَاللهِ! يَا رَسُولَ اللهِ! إِنِّي لَأَتَأَخَّرُ عَنْ صَلَاةِ الْغَدَاةِ مِنْ أَجْلِ فُلَانٍ، مِمَّا يُطِيلُ بِنَا. فَمَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَوْعِظَةٍ أَشَدَّ غَضَبًا مِنْهُ يَوْمَئِذٍ، ثُمَّ قَالَ: "إِنَّ مِنْكُمْ مُنَفِّرِينَ، فَأَيُّكُمْ مَا صَلَّى بِالنَّاسِ فَلْيَتَجَوَّزْ، فَإِنَّ فِيهِمُ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ". (ق,جه)', 'അബൂമസ്ഊദ്(റ): ഒരാൾ പറഞ്ഞു: അല്ലാഹുവാണെ! അല്ലാഹുവിന്റെ ദൂതരേ! ഒരാൾ നിസ്കാരം ദീർഘിപ്പിക്കുന്നത് കാരണം എനിക്ക് പ്രഭാത നിസ്കാരം വൈകിക്കേണ്ടി വരുന്നു. ഇത്ര മാത്രം കോപാകുലനായി നബി(സ) ഉപദേശിക്കുന്നത് ഞാൻ ഒരിക്കലും കണ്ടിട്ടില്ല. നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ കൂട്ടത്തിൽ വെറുപ്പിക്കുന്നവരുണ്ട്. നിങ്ങളാരെങ്കിലും ഇമാമായി നിസ്കരിക്കുന്നുവെങ്കിൽ അവൻ ലഘൂകരിക്കട്ടെ!. അവരിൽ ദുർബ്ബലരും പ്രായം ചെന്നവരും ആവശ്യങ്ങൾ നിർവ്വഹിക്കേണ്ടവരുമുണ്ട്." (ബു,മു,ജ)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ. (ق,ت)', 'അനസുബ്നു മാലിക്(റ): ജനങ്ങളിൽ നിസ്കാരത്തിന്റെ പൂർണ്ണതയോടെ ഏറ്റവും ലഘുവായി നിസ്കരിക്കുന്ന ആളായിരുന്നു നബി(സ). (ബു,മു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُوجِزُ الصَّلَاةَ وَيُكْمِلُهَا. (خ)', 'അനസ്(റ): നബി(സ) നിസ്കാരത്തെ ലഘൂകരിക്കുകയും പൂർത്തിയാക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَمَّ أَحَدُكُمُ النَّاسَ فَلْيُخَفِّفْ، فَإِنَّ فِيهِمُ الصَّغِيرَ وَالْكَبِيرَ وَالضَّعِيفَ وَالْمَرِيضَ، فَإِذَا صَلَّى وَحْدَهُ فَلْيُصَلِّ كَيْفَ شَاءَ". (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കുന്നുവെങ്കിൽ അവൻ ലഘൂകരിക്കട്ടെ. നിശ്ചയം, അവരിൽ കുട്ടികളും പ്രായം ചെന്നവരും ദുർബ്ബലരും രോഗികളും ഉണ്ട്. ഒറ്റക്ക് നിസ്കരിക്കുമ്പോൾ അവനുദ്ദേശിക്കുന്ന വിധം നിസ്കരിക്കാം." (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَدْخُلُ فِي الصَّلَاةِ، وَإِنِّي أُرِيدُ إِطَالَتَهَا، فَأَسْمَعُ بُكَاءَ الصَّبِيِّ، فَأَتَجَوَّزُ فِي صَلَاتِي مِمَّا أَعْلَمُ لِوَجْدِ أُمِّهِ بِبُكَائِهِ". وَفِي رِوَايَةِ دَاوُدَ: كَرَاهِيَةَ أَنْ أَشُقَّ عَلَى أُمِّهِ. (ق,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: ഞാൻ നിസ്കാരത്തിൽ പ്രവേശിക്കുകയും നിസ്കാരം ദീർഘിപ്പിക്കാൻ ഉദ്ദേശിക്കുകയും ചെയ്യുമ്പോൾ ഞാൻ കുട്ടികളുടെ കരച്ചിൽ കേൾക്കും. അപ്പോൾ ഞാൻ ആ കുട്ടിയുടെ മാതാവിന് കരച്ചിലുണ്ടാക്കുന്ന പ്രയാസമോർത്ത് നിസ്കാരം ചുരുക്കും." ദാവൂദിന്റെ റിപ്പോർട്ടിൽ ''ഞാൻ ആ കുട്ടിയുടെ മാതാവിന് ബുദ്ധിമുട്ടുണ്ടാക്കുക എന്നത് ഞാൻ വെറുക്കുന്നതിനാൽ'' എന്നാണുള്ളത്. (ബു,മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=163), 1, 'وَفِي رِوَايَةٍ دَاوُدَ: كَرَاهِيَةَ أَنْ أَشُقَّ عَلَى أُمِّهِ. (ق,د,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ بِالتَّخْفِيفِ، وَيَؤُمُّنَا بِالصَّافَّاتِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) ഞങ്ങളോട് ലഘൂകരിക്കാൻ കൽപിക്കാറുണ്ട്. അവിടുന്ന് സൂറതുസ്സ്വാഫ്ഫാത് ഓതി ഇമാം നിൽക്കാറുണ്ട്. (ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 430, 430, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اسْمَعُوا وَأَطِيعُوا، وَإِنِ اسْتُعْمِلَ حَبَشِيٌّ، كَأَنَّ رَأْسَهُ زَبِيبَةٌ". (خ)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ കേൾക്കുവിൻ, അനുസരിക്കുവിൻ! ഉണങ്ങിയ മുന്തിരി പോലെ തലയുള്ള ഒരു എത്യോപ്യക്കാരൻ നിങ്ങളുടെ ഭരണാധികാരിയായി നിശ്ചയിക്കപ്പെട്ടാലും ശരി." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أُمِّ وَرَقَةَ بِنْتِ نَوْفَلٍ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمَّا غَزَا بَدْرًا قَالَتْ: قُلْتُ لَهُ: يَا رَسُولَ اللهِ، ائْذَنْ لِي فِي الْغَزْوِ مَعَكَ، أُمَرِّضُ مَرْضَاكُمْ، لَعَلَّ اللهَ أَنْ يَرْزُقَنِي شَهَادَةً. قَالَ: "قَرِّي فِي بَيْتِكِ، فَإِنَّ اللهَ تَعَالَى يَرْزُقُكِ الشَّهَادَةَ". قَالَ: فَكَانَتْ تُسَمَّى الشَّهِيدَةَ، قَالَ: وَكَانَتْ قَدْ قَرَأَتِ الْقُرْآنَ، فَاسْتَأْذَنَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ تَتَّخِذَ فِي دَارِهَا مُؤَذِّنًا، فَأَذِنَ لَهَا، قَالَ: وَكَانَتْ قَدْ دَبَّرَتْ غُلَامًا لَهَا وَجَارِيَةً، فَقَامَا إِلَيْهَا بِاللَّيْلِ فَغَمَّاهَا بِقَطِيفَةٍ لَهَا حَتَّى مَاتَتْ، وَذَهَبَا، فَأَصْبَحَ عُمَرُ فَقَامَ فِي النَّاسِ فَقَالَ: مَنْ كَانَ عِنْدَهُ مِنْ هَذَيْنِ عِلْمٌ – أَوْ رَآهُمَا – فَلْيَجِئْ بِهِمَا. فَأَمَرَ بِهِمَا فَصُلِبَا، فَكَانَا أَوَّلَ مَصْلُوبٍ بِالْمَدِينَةِ. وَفِي رِوَايَةٍ: وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَزُورُهَا فِي بَيْتِهَا، وَجَعَلَ لَهَا مُؤَذِّنًا يُؤَذِّنُ لَهَا، وَأَمَرَهَا أَنْ تَؤُمَّ أَهْلَ دَارِهَا. (د)', 'ഉമ്മുവറഖത്തുബ്നു നൗഫൽ(റ): പ്രവാചകൻ(സ) ബദ്ർയുദ്ധത്തിനൊരുങ്ങിയപ്പോൾ ''അള്ളാഹുവിന്റെ ദൂതരേ! അങ്ങയോടൊപ്പം യുദ്ധത്തിൽ പങ്കാളിയാകുവാൻ എനിക്കനുവാദം നൽകിയാലും. ഞാൻ രോഗികളെ (യുദ്ധത്തിൽ പരിക്കേറ്റവരെ) ശുശ്രൂഷിച്ചു കൊള്ളാം. അല്ലാഹു എന്നെ രക്തസാക്ഷിത്വം വരിപ്പിച്ചേക്കാം''. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: ''നീ നിന്റെ വീട്ടിൽ താമസിച്ചു കൊള്ളുക. അല്ലാഹു നിന്നെ രക്തസാക്ഷിത്വം വരിപ്പിച്ചേക്കാം''. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവർ ''രക്തസാക്ഷി'' എന്നു വിളിക്കപ്പെട്ടു. അവർ ഖുർആൻ പാരായണം ചെയ്തു. അവരുടെ വീട്ടിൽ ഒരു ഒരു മുഅദ്ദിനിനെ നിശ്ചയിക്കാൻ അവർ നബി(സ)യോട് സമ്മതം തേടി. അപ്പോൾ തിരുമേനി അവർക്കതിനു അനുമതി നൽകി. നിവേദകൻ തുടർന്ന് പറയുന്നു: അവർ തന്റെ ഒരു അടിമയെയും ഒരു അടിമ സ്ത്രീയെയും തന്റെ മരണശേഷം സ്വതന്ത്രരായി പ്രഖ്യാപിച്ചു. അങ്ങനെ അവരിരുവരും ഒരു രാത്രിയിൽ അവരിലേക്ക് ചെന്ന് അവരെ ഒരു വസ്ത്രം കൊണ്ട് മൂടുകയും (ഞെരുക്കുകയും), അങ്ങനെ അവർ മരിക്കുകയും ചെയ്തു. അടുത്ത ദിവസം ഉമർ(റ) ജന മദ്ധ്യേ നിന്നുകൊണ്ടു പറഞ്ഞു: വല്ലവനും ഈ രണ്ടു വ്യക്തികളെ സംബന്ധിച്ചു വിവരം ലഭിച്ചാൽ - അല്ലെങ്ങിൽ അവരെ കണ്ടാൽ - അവരെയും കൊണ്ട് (എന്റെയടുക്കൽ) വരട്ടെ. അങ്ങനെ അവരിരുവരും (പിടികൂടപ്പെട്ടു. ഉമറിന്റെ) കൽപ്പനപ്രകാരം ക്രൂശിക്കപ്പെട്ടു. മദീനയിൽ ആദ്യമായി കുരിശിലേറ്റപ്പെട്ടത് അവരിരുവരുമാണ്. മറ്റൊരു റിപ്പോർട്ടിൽ: പ്രവാചകൻ(സ) അവരുടെ വീട്ടിൽ ചെന്ന് അവരെ സന്ദർശിക്കാറുണ്ടായിരുന്നു. അവരുടെ വീട്ടിലുള്ളവർക്ക് (നിസ്കാരത്തിന്) നേതൃത്വം നൽകാൻ നബി(സ) അവരോടു നിർദ്ദേശിച്ചു. (ദ)', 'أُمِّ وَرَقَةَ بِنْتِ نَوْفَلٍ', 'ഉമ്മുവറഖത്തുബ്നു നൗഫൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=166), 1, 'وَفِي رِوَايَةٍ: وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَزُورُهَا فِي بَيْتِهَا، وَجَعَلَ لَهَا مُؤَذِّنًا يُؤَذِّنُ لَهَا، وَأَمَرَهَا أَنْ تَؤُمَّ أَهْلَ دَارِهَا. (د)', 'മറ്റൊരു നിവേദനിൽ: പ്രവാചകൻ(സ) അവരുടെ വീട്ടിൽ ചെന്ന് അവരെ സന്ദർശിക്കാറുണ്ടായിരുന്നു. അവരുടെ വീട്ടിലുള്ളവർക്ക് (നിസ്കാരത്തിന്) നേതൃത്വം നൽകാൻ നബി(സ) അവരോടു നിർദ്ദേശിച്ചു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الصَّلَاةُ الْمَكْتُوبَةُ وَاجِبَةٌ خَلْفَ كُلِّ مُسْلِمٍ، بَرًّا كَانَ أَوْ فَاجِرًا، وَإِنْ عَمِلَ الْكَبَائِرَ". (د,جه)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: മുസ്ലിമായ എതൊരുവന്റെ പിന്നിലും നിർബ്ബന്ധനിസ്കാരങ്ങൾ നിർവ്വഹിക്കുക എന്നത് (വിശ്വാസികൾക്ക്) കടമയാകുന്നു. അവൻ പുണ്യവാനായാലും ദുർനടപ്പുകാരനായാലും ശരി, ഇനി അവൻ വൻപാപങ്ങൾ ചെയ്തിട്ടുണ്ടെങ്കിലും ശരി. (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 431, 431, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اسْتَخْلَفَ ابْنَ أُمِّ مَكْتُومٍ يَؤُمُّ النَّاسَ وَهُوَ أَعْمَى. (د)', 'അനസ്(റ): പ്രവാചകൻ(സ) അന്ധനായ ഉമ്മുമക്തൂമിനെ ജനങ്ങൾക്ക് (നിസ്കാരത്തിൽ) ഇമാമത്ത് നിർവ്വഹിക്കാൻ വേണ്ടി പകരക്കാരനായി നിയോഗിച്ചു. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 431, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عن عطيَّة قال: كَانَ مَالِكُ بْنُ حُوَيْرِث رَضِيَ اللهُ عَنْهُ يَأْتِينَا إِلَى مُصَلَّانَا هَذَا، فَأُقِيمَتِ الصَّلَاةُ، فَقُلْنَا لَهُ: تَقَدَّمْ فَصَلِّهْ، فَقَالَ لَنَا: قَدِّمُوا رَجُلًا مِنْكُمْ يُصَلِّي بِكُمْ، وَسَأُحَدِّثُكُمْ لِمَ لَا أُصَلِّي بِكُمْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ زَارَ قَوْمًا فَلَا يَؤُمَّهُمْ، وَلْيَؤُمَّهُمْ رَجُلٌ مِنْهُمْ". (د,ت,ن)', 'അത്വിയ്യ പറയുന്നു: മാലിക്കുബ്നു ഹുവൈരിഥ്(റ) ഞങ്ങളുടെ മുസ്വല്ലയിൽ വന്നു. അങ്ങനെ നിസ്കാരത്തിന് ഇഖാമത്തു വിളിക്കപ്പെട്ടു. ഞങ്ങൾ അദ്ദേഹത്തോടു പറഞ്ഞു: മുന്നോട്ടു നിന്ന് നിസ്കാരം (നേതൃത്വം നൽകിക്കൊണ്ട്) നിർവ്വഹിക്കൂ! അപ്പോൾ അദ്ദേഹം ഞങ്ങളോടു പറഞ്ഞു: നിങ്ങളിൽ നിന്ന് നിങ്ങൾക്ക് നേതൃത്വം നൽകി നിസ്കരിക്കുന്ന ഒരാളെ മുന്നോട്ടു നിർത്തൂ! ഞാൻ (നിങ്ങൾക്കിമാമായി) നിങ്ങളെയും കൊണ്ട് നിസ്കരിക്കാത്തതെന്താണെന്ന് ഞാൻ പറയാം: തിരുമേനി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: ഒരാൾ ഒരു ജനതയെ സന്ദർശിച്ചാൽ അവർക്ക് അവൻ (നിസ്കാരത്തിന്) നേതൃത്വം നൽകാൻ പാടില്ല. അവരിൽ നിന്നു തന്നെയുള്ള ഒരാൾ അവർക്ക് നിസ്കാരത്തിന് നേതൃത്വം നൽകിക്കൊള്ളട്ടെ. (ദ,തു,ന)', 'عطيَّة قال', 'അത്വിയ്യ പറയുന്നു', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ عُمَرُ لِسَعْدٍ رَضِيَ اللهُ عَنْهُمَا: قَدْ شَكَاكَ النَّاسُ فِي كُلِّ شَيْءٍ، حَتَّى فِي الصَّلَاةِ، قَالَ: أَمَّا أَنَا فَأَمُدُّ فِي الْأُولَيَيْنِ وَأَحْذِفُ فِي الْأُخْرَيَيْنِ، وَلَا آلُو مَا اقْتَدَيْتُ بِهِ مِنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: ذَاكَ الظَّنُّ بِكَ. (ق,د,ن)', 'ജാബിറുബ്നു സമുറ(റ): ഉമർ(റ) സഅ്ദി(റ)നോട് പറഞ്ഞു: ജനങ്ങൾ താങ്കളെക്കുറിച്ച് എല്ലാ കാര്യങ്ങളിലും വേവലാതി പറയുന്നുവല്ലോ! താങ്കളുടെ നിസ്കാരത്തിന്റെ കാര്യത്തിൽ പോലും (അവർ പരാതിപ്പെടുന്നു). അദ്ദേഹം പറഞ്ഞു: ഞാൻ ആദ്യത്തെ രണ്ടു റക്അത്തുകൾ ദീർഘിപ്പിക്കുകയും, അവസാനത്തെ രണ്ടു റക്അത്തുകൾ ലഘുവായി നിർവ്വഹിക്കുകയും ചെയ്യും. ഞാൻ തിരുമേനി(സ)യുടെ നിസ്കാരത്തിൽ നിന്നും അനുധാവനം ചെയ്ത ഒന്നും ഞാൻ കുറക്കുകയില്ല. ഉമർ(റ) പറഞ്ഞു: താങ്കളെക്കുറിച്ച് എന്റെ ധാരണ അതുതന്നെയാണ്. (ബു,മു,ദ,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 432, 432, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عن أبي سعيد الخُدْريِّ رَضِيَ اللهُ عَنْهُ قال: حَزَرْنا قيام رسول الله صلَّى الله عَلَيْه وسَلَّم في الظُّهر والعَصر، فحَزَرْنا قِيامَهُ في الرَّكْعتين الأُولَيين من الظُّهر قدْر ثلاثين آيةً، قدْر {الم تنزيل...} السَّجدة. وحَزَرْنا قِيامَهُ في الأُخْرَيين على النِّصف مِنْ ذلك، وحَزَرْنا قِيامَهُ في الأُولَيين من العَصر على قَدْر الأُخْرَيين من الظُّهر، وحَزَرْنا قِيامَهُ في الأُخْرَيين من العَصر على النِّصف مِنْ ذَلِك. (م,د,ن)', 'അബൂസഈദുൽ ഖുദ്രി(റ): അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ തിരുമേനി(സ)യുടെ ദുഹ്ർ, അസ്ർ എന്നീ നിസ്കാരങ്ങളിലെ നിർത്തത്തിന്റെ ദൈർഘ്യം കണക്കുകൂട്ടാറുണ്ടായിരുന്നു. ഞങ്ങൾ (ഒരിക്കൽ) തിരുമേനി(സ)യുടെ ദുഹ്ർ നിസ്കാരത്തിലെ ആദ്യ രണ്ടു റക്അത്തുകളിലെ നിർത്തത്തിന്റെ ദൈർഘ്യം മുപ്പത് (ഖുർആൻ) സൂക്തങ്ങൾ ഓതുന്നത്രയാണെന്ന് കണക്കൂകൂട്ടികണ്ടെത്തി. അലിഫ്ലാംമീം -സൂറത്തുസ്സജദ - ഓതുന്നത്ര ദൈർഘ്യം. തിരുമേനി(സ)യുടെ (ദുഹ്റിലെ) അവസാന രണ്ടു റക്അത്തുകളുടെ നിർത്തത്തിന്റെ ദൈർഘ്യം അതിന്റെ പകുതിയാണെന്നും ഞങ്ങൾ കണക്കുകൂട്ടിമനസ്സിലാക്കി. തിരുമേനിയുടെ അസ്റിലെ ആദ്യ രണ്ടു റക്അത്തുകളിലെ നിർത്തത്തിന്റെ ദൈർഘ്യം ദുഹ്റിലെ അവസാനത്തെ രണ്ടു റക്അത്തുകളിലെ നിർത്തത്തിനു നമാനമായതാണെന്ന് ഞങ്ങൾ കണക്കാക്കി. അവിടുത്തെ അസ്റിലെ അവസാന രണ്ടു റക്അത്തുകളിലെ നിർത്തത്തിന്റെ ദൈർഘ്യം അതിന്റെ പകുതിയാണെന്നും ഞങ്ങൾ കണക്കുകൂട്ടിക്കണ്ടെത്തി. (മു,ദ,ന)', 'أبي سعيد الخُدْريِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 432, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ هَمَّامٍ: أَنَّ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ أَمَّ النَّاسَ بِالْمَدَائِنِ عَلَى دُكَّانٍ، فَأَخَذَ أَبُو مَسْعُودٍ رَضِيَ اللهُ عَنْهُ بقميصه فَجَبَذَهُ، فَلَمَّا فَرَغَ مِنْ صلاته قَالَ: أَلَمْ تَعْلَمْ أَنَّهُمْ كَانُوا يُنْهَوْنَ عَنْ ذَلِكَ؟ قَالَ: بَلَى، قَدْ ذَكَرْتُ حِينَ مَدَدْتَنِي. (د)', 'ഹമ്മാം പറയുന്നു: ഹുമൈറ(റ) മദാഇനിലെ³ ജനങ്ങൾക്ക് ഉയർന്ന സ്ഥത്തുനിന്ന് കൊണ്ട് (നിസ്കാരത്തിന്) നേതൃത്വം നൽകി. അന്നേരം അബൂമസ്ഊദ്(റ) അദ്ദേഹത്തിന്റെ വസ്ത്രത്തിനു പിടിച്ചു. (വലിച്ച് താഴേക്കുമാറ്റി) എന്നിട്ട് അദ്ദേഹം (അബൂമസ്ഊദ്) തന്റെ നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചപ്പോൾ പറഞ്ഞു: അവർ (വിശ്വാസികൾ) ഇങ്ങനെ ചെയ്യുന്നതിൽ നിന്ന് വിലക്കപ്പെട്ടിരുക്കുന്നുവെന്ന് നിനക്കറിയില്ലെ? അദ്ദേഹം പറഞ്ഞു: അതെ, നീ എന്നെ (താഴോട്ട്) വലിച്ചപ്പോഴാണ് ഞാനത് ഓർമ്മിച്ചത്. (ദ)', 'هَمَّامٍ', 'ഹമ്മാം പറയുന്നു', '³. ഇറാഖിലെ ടൈഗ്രീസ് തീരത്തുള്ള ഒരു സ്ഥലം', null, array['د']::text[], array['ദ']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عَدِيِّ بْنِ ثَابِتٍ الْأَنْصَارِيِّ: حَدَّثَنِي رَجُلٌ أَنَّهُ كَانَ مَعَ عَمَّارِ بْنِ يَاسِرٍ بِالْمَدَائِنِ، فَأُقِيمَتِ الصَّلَاةُ، فَتَقَدَّمَ عَمَّارٌ، وَقَامَ عَلَى دُكَّانٍ يُصَلِّي وَالنَّاسُ أَسْفَلَ مِنْهُ، فَتَقَدَّمَ حُذَيْفَةُ فَأَخَذَ عَلَى يَدَيْهِ، فَاتَّبَعَهُ عَمَّارٌ حَتَّى أَنْزَلَهُ حُذَيْفَةُ، فَلَمَّا فَرَغَ عَمَّارٌ مِنْ صَلَاتِهِ قَالَ لَهُ حُذَيْفَةُ: أَلَمْ تَسْمَعْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا أَمَّ الرَّجُلُ الْقَوْمَ فَلَا يَقُمْ فِي مَكَانٍ أَرْفَعَ مِنْ مَقَامِهِمْ". أَوْ نَحْوَ ذَلِكَ؟ قَالَ عَمَّارٌ: لِذَلِكَ اتَّبَعْتُكَ حِينَ أَخَذْتَ عَلَى يَدَيَّ. (د)', 'അദിയ്യുബ്നു ഥാബിത്തുൽ അൻസാരി(റ): അമ്മാറുബ്നുയാസിറിന്റെ കൂടെ (കൂഫക്കടുത്തുള്ള) മദാഇനിൽ ഉണ്ടായിരുന്ന ഒരാൾ പറഞ്ഞു: നിസ്കാരത്തിനു ഇഖാമത്തു വിളിക്കപ്പെട്ടു. അമ്മാർ (ഇമാമത്തു നിർവ്വഹിക്കാൻ) മുമ്പോട്ട് വന്നു. എന്നിട്ട് ഒരു ഉയർന്ന സ്ഥലത്ത് നിസ്കരിക്കാൻ നിന്നു. ആളുകളാവട്ടെ അതിനേക്കാൾ താഴ്ന്ന സ്ഥലത്തും അന്നേരം ഹുദൈഫ ചെന്ന് അദ്ദേഹത്തിന്റെ കൈക്കു പിടി(ച്ചു വലി)ക്കുകയും അമ്മാർ(റ) അദ്ദേഹത്തോടൊപ്പം (പിറകിലേക്കു) വന്നു. അങ്ങനെ ഹുദൈഫ അദ്ദേഹത്തെ താഴേക്കിറക്കി. അമ്മാർ(റ) തന്റെ നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചപ്പോൾ ഹുദൈഫ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: ''ഒരാൾ ഒരു ജനതക്ക് ഇമാമായി നിൽക്കുകയാണെങ്കിൽ അയാൾ അവർ നിൽക്കുന്ന സ്ഥാനത്തേക്കാൾ ഉയർന്ന സ്ഥാനത്ത് നിൽക്കുവാൻ പാടില്ല'' എന്ന് തിരുമേനി(സ) പറയുന്നത് -അല്ലെങ്കിൽ, ഇതിനു സമാനമായ വാക്യം പറയുന്നത് - നീ കേട്ടിട്ടില്ലേ? അമ്മാർ പറഞ്ഞു: അതു കാരണത്താൽ തന്നെയാണ്, നീ എന്റെ കൈ പിടി(ച്ചു വലി)ച്ചപ്പോൾ ഞാൻ നിന്റെ കൂടെ വന്നത്. (ദ)', 'عَدِيِّ بْنِ ثَابِتٍ الْأَنْصَارِيِّ', 'അദിയ്യുബ്നു ഥാബിത്തുൽ അൻസാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ مُعَاذَ بْنَ جَبَلٍ رَضِيَ اللهُ عَنْهُ كَانَ يُصَلِّي مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ، ثُمَّ يَأْتِي قَوْمَهُ فَيُصَلِّي بِهِمْ تِلْكَ الصَّلَاةَ. وَفِي رِوَايَةٍ: إِنَّ مُعَاذًا رَضِيَ اللهُ عَنْهُ كَانَ يُصَلَّى مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ يَرْجِعُ فَيَؤُمُّ قَوْمَهُ. (ق,د,ن)', 'ജാബിർ(റ): മൂആദ്(റ) പ്രവാചക(സ)ന്റെ കൂടെ ഇശാ നിസ്കരിക്കുകയും ശേഷം തന്റെ ജനതയിലേക്കു വരികയും അവർക്ക് നിസ്കാരത്തിന് നേതൃത്വം നൽകുകയും ചെയ്തു. മറ്റൊരു റിപ്പോർട്ട്: മുആദ്(റ) തിരുമേനിയോടൊപ്പം നിസ്കാരം നിസകാരം നിർവ്വഹിച്ചു. പിന്നെ തന്റെ ജനതയിലേക്ക് മടങ്ങി വന്ന് അവർക്ക് നിസ്കരത്തിന് നേതൃത്വം നൽകി (ബു,മു,ദ,ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 433, 433, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=19 and h.hadith_no=174), 1, 'وَفِي رِوَايَةٍ: إِنَّ مُعَاذًا رَضِيَ اللهُ عَنْهُ كَانَ يُصَلَّى مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ يَرْجِعُ فَيَؤُمُّ قَوْمَهُ. (ق,د,ن)', 'മറ്റൊരു നിവേദന്: മുആദ്(റ) തിരുമേനിയോടൊപ്പം നിസ്കാരം നിസകാരം നിർവ്വഹിച്ചു. പിന്നെ തന്റെ ജനതയിലേക്ക് മടങ്ങി വന്ന് അവർക്ക് നിസ്കരത്തിന് നേതൃത്വം നൽകി (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَكِبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَسًا بِالْمَدِينَةِ، فَصَرَعَهُ عَلَى جِذْمِ نَخْلَةٍ، فَانْفَكَّتْ قَدَمُهُ، فَأَتَيْنَاهُ نَعُودُهُ فَوَجَدْنَاهُ فِي مَشْرُبَةٍ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا يُسَبِّحُ جَالِسًا، قَالَ: فَقُمْنَا خَلْفَهُ، فَسَكَتَ عَنَّا، ثُمَّ أَتَيْنَاهُ مَرَّةً أُخْرَى نَعُودُهُ، فَصَلَّى الْمَكْتُوبَةَ جَالِسًا، فَقُمْنَا خَلْفَهُ، فَأَشَارَ إِلَيْنَا فَقَعَدْنَا، قَالَ: فَلَمَّا قَضَى الصَّلَاةَ قَالَ: "إِذَا صَلَّى الْإِمَامُ جَالِسًا فَصَلُّوا جُلُوسًا، وَإِذَا صَلَّى الْإِمَامُ قَائِمًا فَصَلُّوا قِيَامًا، وَلَا تَفْعَلُوا كَمَا يَفْعَلُ أَهْلُ فَارِسَ بِعُظَمَائِهَا". (د,جه)', 'ജാബിർ(റ) പ്രവാചകൻ(സ) മദീനയിലൂടെ കുതിരപ്പുറത്ത് സഞ്ചരിച്ചുകൊണ്ടിരിക്കെ, ഒരു ഈത്തപ്പനയുടെ വേര് തടഞ്ഞ് അവിടുന്ന് വീണു. അതു കരാണത്താൽ തിരുമേനി(സ)യുടെ കാൽപ്പാദത്തിന് മുറിവേറ്റു. അങ്ങനെ ഞങ്ങൾ രോഗവിവരം അറിയാൻ വേണ്ടി തിരുമേനി(സ)യെ സന്ദർശിച്ചു. അപ്പോൾ തിരുമേനി(സ) ആഇശ(റ)യുടെ റൂമിൽ ഇരുന്നുകൊണ്ട് നിസ്കരിക്കുകയായിരുന്നു. ഞങ്ങൾ തിരുമേനി(സ)യുടെ പിന്നിൽ ''നിന്ന് കൊണ്ട്'' നിസ്കരിച്ചു. തിരുമേനി(സ) അക്കാര്യത്തിൽ ഞങ്ങളോടൊന്നും പറഞ്ഞില്ല. ഞങ്ങൾ പിന്നീടൊരിക്കൽ കൂടി തിരുമേനിയുടെ അടുക്കൽ രോഗ സന്ദർശനം നടത്തി. അപ്പോൾ തിരുമേനി(സ) നിർബ്ബന്ധ നിസ്കാരം ഇരുന്നുകൊണ്ട് നിർവ്വഹിക്കുകയായിരുന്നു. ഞങ്ങൾ തിരുമേനിയുടെ പിന്നിൽ നിന്നു (കൊണ്ട് നിസ്കരിച്ചു തുടങ്ങി) അവിടുന്ന് ഞങ്ങളോട് സൂചന നൽകുകയും ഞങ്ങൾ ഇരിക്കുകയും ചെയ്തു. നിസ്കാരം നിർവ്വഹിച്ചു കഴിഞ്ഞപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: ''ഇമാം ഇരുന്ന് കൊണ്ട് നിസ്കരിക്കുകയാണെങ്കിൽ നിങ്ങൾ ഇരുന്നു കൊണ്ടു നിസ്കരിക്കുക. ഇമാം നിന്നു കൊണ്ട് നിസ്കരിക്കുകയാണെങ്കിൽ നിങ്ങളും നിന്നു കൊണ്ട് നിസ്കരിക്കുക. പേർഷ്യക്കാർ തങ്ങളുടെ നേതാക്കളോട് ചെയ്തതു പോലെ നിങ്ങൾ ചെയ്യരുത്. (ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ فِي حُجْرَتِهِ، وَجِدَارُ الْحُجْرَةِ قَصِيرٌ. فَرَأَى النَّاسُ شَخْصَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ أُنَاسٌ يُصَلُّونَ بِصَلَاتِهِ، فَأَصْبَحُوا فَتَحَدَّثُوا بِذَلِكَ. فَقَامَ اللَّيْلَةَ الثَّانِيَةَ، فَقَامَ مَعَهُ أُنَاسٌ يُصَلُّونَ بِصَلَاتِهِ، صَنَعُوا ذَلِكَ لَيْلَتَيْنِ أَوْ ثَلَاثًا، حَتَّى إِذَا كَانَ بَعْدَ ذَلِكَ جَلَسَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَخْرُجْ، فَلَمَّا أَصْبَحَ ذَكَرَ ذَلِكَ النَّاسُ فَقَالَ: "إِنِّي خَشِيتُ أَنْ تُكْتَبَ عَلَيْكُمْ صَلَاةُ اللَّيْلِ". (خ)', 'ആഇശ(റ): നബി(സ) രാത്രി തന്റെ റൂമിൽവെച്ച് നിസ്കരിക്കാറുണ്ടായിരുന്നു. റൂമിന്റെ ചുമർ ഉയരം കുറഞ്ഞതായിരുന്നു. അതിനാൽ ആളുകൾ നബി(സ) നിസ്കരിക്കുന്നത് കാണുകയും അവരിൽ ചിലർ നബി(സ)യോടൊപ്പം നിസ്കരിക്കുകയും ചെയ്തു. നേരം പുലർന്നപ്പോൾ ജനങ്ങൾ ഇതിനെപ്പറ്റി പറഞ്ഞു. രണ്ടാമത്തെ രാത്രി നബി(സ) നിസ്കരിച്ചപ്പോഴും ചിലർ നബിയോടൊപ്പം നിസ്കരിച്ചു. ഇപ്രകാരം രണ്ടോ, മൂന്നോ രാത്രികൾ ജനങ്ങൾ ചെയ്തു. ശേഷം നബി(സ) ഇരുന്നു. നിസ്കരിക്കാൻ പുറപ്പെട്ടില്ല. രാവിലെ ജനങ്ങൾ ഇതിനെപ്പറ്റി പറഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "രാത്രി നിസ്കാരം നിങ്ങൾക്ക് നിർബന്ധമാക്കപ്പെടുന്നത് ഞാൻ ഭയക്കുന്നു." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 434, 434, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عن خَبَّاب قيل لهُ: أكان رسول الله صَلَّى الله عَلَيْه وَسَلَّمَ يقرَأُ فِي الظُّهر والعصر؟ قال: نعم، قلنا: بِمَ كنتم تعرفون ذاك؟ قال: باضطراب لحيته. (خ)', 'ഖബ്ബാബ്(റ): നബി(സ) ളുഹ്റിലും അസ്വറിലും ഖുർആൻ പാരായണം ചെയ്യാറുണ്ടായിരുന്നോ എന്ന് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം അതെയെന്നു പറഞ്ഞു. നിങ്ങൾക്കതെങ്ങനെ മനസ്സിലായി എന്നു ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അദ്ദേഹത്തിന്റെ താടി ഇളകിയതുമൂലം. (ബു)', 'خَبَّاب قيل لهُ', 'ഖബ്ബാബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 434, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُصَلِّ الْإِمَامُ فِي الْمَوْضِعِ الَّذِي صَلَّى فِيهِ حَتَّى يَتَحَوَّلَ". (د,جه)', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ): പ്രവാചകൻ(സ) അരുളി: ഒരു ഇമാം താൻ നിസ്കരിച്ച അതേ സ്ഥാനത്തുനിന്ന് നിസ്കരിക്കരിക്കരുത്, അൽപം മാറിനിൽക്കേണ്ടതാണ്. (ദ,ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَضَى الْإِمَامُ الصَّلَاةَ وَقَعَدَ، فَأَحْدَثَ قَبْلَ أَنْ يَتَكَلَّمَ، فَقَدْ تَمَّتْ صَلَاتُهُ وَمَنْ كَانَ خَلْفَهُ مِمَّنْ أَتَمَّ الصَّلَاةَ". (د,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: ഇമാം നിസ്കാരം നിർവ്വഹിക്കുകയും (ശേഷം) ഇരിക്കുകയും, ചെയ്തു. എന്നിട്ട് അദ്ദേഹം വല്ലതും സംസാരിക്കുന്നതിനുമുമ്പ് അയാൾക്ക് അശുദ്ധിയുണ്ടാവുകയും ചെയ്തു. എങ്കിൽ അയാളുടെയും അയാളുടെ പിന്നിൽ മുഴുവൻ നിസ്കരിച്ചവരുടെയും നിസ്കാരം പൂർണ്ണമായി. (ദ,തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مفتاحُ الصَّلاة الطُّهُورُ. وتحريمُهَا التَّكبيرُ، وتحليلُهَا التَّسليمُ". (د,ت,جه)', 'അലി(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: നിസ്കാരത്തിന്റെ താക്കോൽ ശുദ്ധിയാകുന്നു. അത് ആരംഭിക്കുന്നത് തക്ബീർ കൊണ്ടും അവസാനിക്കുന്നത് സലാം ചൊല്ലൽ കൊണ്ടുമാണ്. (ദ,തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 435, 435, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: شكا أهل الكُوفة سَعْدًا إلى عُمر رَضِيَ اللهُ عَنْهُ، فعزلَهُ واسْتَعْمَل عَلَيْهِمْ عَمَّارًا. فشكَوْا حتَّى ذَكَرُوا: أنَّهُ لَا يُحسنُ يُصلِّي، فَأَرْسَلَ إِلَيْهِ فَقَالَ: يَا أَبَا إِسْحَاقَ، إِنَّ هَؤُلَاءِ يَزْعُمُونَ أَنَّكَ لَا تُحْسِنُ تُصلِّي. قَالَ أَبُو إِسْحَاقَ: أَمَّا أَنَا وَاللَّهِ فَإِنِّي كُنْتُ أُصَلِّي بِهِمْ صَلَاةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مَا أَخْرِمُ عَنْهَا، أُصَلِّي صَلَاةَ الْعِشَاءِ فَأَرْكُدُ فِي الْأُولَيَيْنِ، وَأُخِفُّ فِي الْأُخْرَيَيْنِ. قَالَ: ذَاكَ الظَّنُّ بِكَ يَا أَبَا إِسْحَاقَ. فَأَرْسَلَ مَعَهُ رَجُلًا أَوْ رِجَالًا إِلَى الْكُوفَةِ، فَسَأَلَ عَنْهُ أَهْلَ الْكُوفَةِ. وَلَمْ يَدَعْ مَسْجِدًا إِلَّا سَأَلَ عَنْهُ، وَيُثْنُونَ مَعْرُوفًا، حَتَّى دَخَلَ مَسْجِدًا لِبَنِي عَبْسٍ، فَقَامَ رَجُلٌ مِنْهُمْ يُقَالُ لَهُ – أُسَامَةُ بْنُ قَتَادَةَ، يُكْنَى أَبَا سَعْدَةَ – قَالَ: أَمَّا إِذْ نَشَدْتَنَا، فَإِنَّ سَعْدًا كَانَ لَا يَسِيرُ بِالسَّرِيَّةِ، وَلَا يَقْسِمُ بِالسَّوِيَّةِ، وَلَا يَعْدِلُ فِي الْقَضِيَّةِ، قَالَ سَعْدٌ: أَمَا وَاللَّهِ، لَأَدْعُوَنَّ بِثَلَاثٍ: اللَّهُمَّ إِنْ كَانَ عَبْدُكَ هَذَا كَاذِبًا قَامَ رِيَاءً وَسُمْعَةً، فَأَطِلْ عُمْرَهُ، وَأَطِلْ فَقْرَهُ، وَعَرِّضْهُ بِالْفِتَنِ. وَكَانَ بَعْدُ إِذَا سُئِلَ يَقُولُ: شَيْخٌ كَبِيرٌ مَفْتُونٌ، أَصَابَتْنِي دَعْوَةُ سَعْدٍ. قَالَ عَبْدُالْمَلِكِ: فَأَنَا رَأَيْتُهُ بَعْدُ قَدْ سَقَطَ حَاجِبَاهُ عَلَى عَيْنَيْهِ مِنَ الْكِبَرِ، وَإِنَّهُ لَيَتَعَرَّضُ لِلْجَوَارِي فِي الطَّرِيقِ يَغْمِزُهُنَّ. (خ)', 'ജാബിറുബ്നു സമുറ(റ): കൂഫക്കാർ ഉമറി(റ)നോട് സഅദി(റ)നെപ്പറ്റി പരാതിപ്പെട്ടു. അങ്ങനെ അദ്ദേഹത്തെ ഒഴിവാക്കുകയും അമ്മാറിനെ ഗവർണ്ണറായി നിയമിക്കുകയും ചെയ്തു. സഅദിന് ശരിയായി നിസ്കരിക്കാൻപോലും അറിയില്ലെന്ന് അവർ പരാതിപ്പെട്ടിരുന്നു. അദ്ദേഹത്തെ ആളയച്ചുവരുത്തി. ഉമർ പറഞ്ഞു: അബൂഇസ്ഹാഖ്, ഇവർ വാദിക്കുന്നത് താങ്കൾക്ക് ശരിയായി നിസ്കരിക്കാൻപോലും അറിയില്ല എന്നാണ്. അദ്ദേഹം പറഞ്ഞു: ഞാൻ അവരോടൊപ്പം നബി(സ) നിസ്കരിക്കുന്നതുപോലെ നിസ്കരിക്കാറുണ്ട്, ഞാൻ ഒന്നും ചുരുക്കാറില്ല. ഇശാ നിസ്കാരത്തിലെ ആദ്യ രണ്ട്റക്അത്തുകൾ ദീർഘിപ്പിക്കുകയും, അവസാനത്തെ രണ്ട് റക്അത്തുകൾ ചുരുക്കുകയും ചെയ്യും. ഉമർ(റ) പറഞ്ഞു: അബൂഇസ്ഹാഖ്, താങ്കളെക്കുറിച്ചുള്ള എന്റെ വിചാരം അതുതന്നെയാണ്. അങ്ങനെ അദ്ദേഹത്തോടൊപ്പം ഒരാളെ (അല്ലെങ്കിൽ ആളുകളെ) കൂഫയിലേക്കയച്ചു. കൂഫക്കാരോട് സഅദിനെക്കുറിച്ചന്വേഷിച്ചു. എല്ലാ പള്ളികളിലും അദ്ദേഹത്തെപ്പറ്റി അന്വേഷിച്ചു. അദ്ദേഹത്തെക്കുറിച്ച് നല്ലതു മാത്രം പറഞ്ഞ് പ്രശംസിച്ചു. ബനൂഅബ്സിന്റെ പള്ളിയിലെത്തിയപ്പോൾ അബൂസഅ്ദ എന്നറിയപ്പെടുന്ന ഉസാമത്തുബ്നു ഖതാദ എന്നയാൾ എഴുന്നേറ്റു നിന്ന് പറഞ്ഞു: നിങ്ങൾ ചോദിച്ച സഅദ് സൈന്യത്തോടൊപ്പം പുറപ്പെടാറില്ല, മുതൽ തുല്യമായി വീതിക്കാറില്ല, വിധി പറയുന്നതിൽ നീതി പാലിക്കാറില്ല. സഅദ് പറഞ്ഞു: അല്ലാഹുവാണെ, ഞാൻ മൂന്നുകാര്യം കൊണ്ട് പ്രാർത്ഥിക്കുന്നു; അല്ലാഹുവെ, നിന്റെ ഈ അടിമ പറഞ്ഞത് കളവും ലോകപ്രശസ്തിക്കും മാന്യതക്കും വേണ്ടി പറഞ്ഞതാണെങ്കിൽ അദ്ദേഹത്തിന്റെ വയസ്സ് ദീർഘിപ്പിക്കേണമേ, ദാരിദ്ര്യത്തെ വർദ്ധിപ്പിക്കേണമേ, ബുദ്ധിമുട്ടുകളിൽ അകപ്പെടുത്തേണമേ. (കാലങ്ങൾക്കു) ശേഷം ഇദ്ദേഹത്തോട് (ഇവ്വിഷയകമായി) ചോദിക്കുമ്പോൾ ഇയാൾ പറയുമായിരുന്നു; അതിവൃദ്ധനും, കുഴപ്പത്തിലകപ്പെട്ടവനുമാണ് ഞാൻ. എനിക്ക് സഅ്ദിന്റെ പ്രാർത്ഥന ഏറ്റിരിക്കുന്നു. ജാബിറിൽ നിന്ന് റിപ്പോർട്ട് ചെയ്യുന്ന റാവി അബ്ദുൽ മലിക് പറയുന്നു: ഇതിനു ശേഷം ഞാനദ്ദേഹത്തെ കണ്ടിരുന്നു. വാർദ്ധക്യത്താൽ അദ്ദേഹത്തിന്റെ കണ്ണുകളുടെ മേൽ പുരികം വീണിരുന്നു. അദ്ദേഹം വഴിയിലുള്ള പെൺകുട്ടികളുടെ നേരെ ചെന്ന് അവരെ തോണ്ടുമായിരുന്നു. (ബു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 435, 436, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ بِفَاتِحَةِ الْكِتَابِ". (خ)', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ): നബി(സ) പറഞ്ഞു: "ഫാത്തിഹ ഓതാത്തവന് നിസ്കാരമില്ല." (ബു)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 436, 436, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ الْمَسْجِدَ فَدَخَلَ رَجُلٌ، فَصَلَّى، فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَدَّ وَقَالَ: "ارْجِعْ فَصَلِّ، فَإِنَّكَ لَمْ تُصَلِّ". فَرَجَعَ يُصَلِّي كَمَا صَلَّى، ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "ارْجِعْ فَصَلِّ، فَإِنَّكَ لَمْ تُصَلِّ" ثَلَاثًا فَقَالَ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، مَا أُحْسِنُ غَيْرَهُ فَعَلِّمْنِي. فَقَالَ: "إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ، ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنَ الْقُرْآنِ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا، ثُمَّ ارْفَعْ حَتَّى تَعْدِلَ قَائِمًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا، وَافْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا". (خ)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോൾ ഒരാൾ പള്ളിയിൽ വന്ന് നിസ്കരിച്ചു. നബി(സ)യോട് സലാം പറഞ്ഞു. നബി(സ) സലാം മടക്കിക്കൊണ്ട് പറഞ്ഞു: "നീ നിന്റെ നിസ്കാരം മടക്കുക. കാരണം, നീ നിസ്കരിച്ചിട്ടില്ല." അദ്ദേഹം മുമ്പ് നിസ്കരിച്ച പോലെ വീണ്ടും നിസ്കരിച്ചു. പിന്നീടദ്ദേഹം വരികയും, നബി(സ)യോട് സലാം പറയുകയും ചെയ്തു. നബി(സ) അപ്പോഴും നിസ്കാരം മടക്കാൻ പറഞ്ഞു. നബി(സ) മൂന്നുപ്രാവശ്യം ഇക്കാര്യം ആവർത്തിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: താങ്കളെ സത്യവുമായി നിയോഗിച്ചവനാണെ സത്യം, എനിക്ക് ഇപ്രകാരമല്ലാതെ നിസ്കരിക്കാനറിയില്ല. അതിനാൽ എന്നെ പഠിപ്പിക്കുക. നബി(സ) പറഞ്ഞു: "നീ നിസ്കാരത്തിനു നിന്നാൽ തക്ബീർ ചൊല്ലുക, പിന്നെ ഖുർആനിൽനിന്ന് എളുപ്പമായത് പാരായണം ചെയ്യുക. ശേഷം റുകൂഅ് ചെയ്യുകയും, കുറച്ചു സമയം അടങ്ങിത്താമസിക്കുകയും ചെയ്യുക. ശേഷം റുകൂഇൽ നിന്നുയർന്ന് വടിവൊത്ത് നിൽക്കുകയും ചെയ്യുക. പിന്നീട് സുജൂദ് ചെയ്യുകയും അതിൽ അടങ്ങിത്താമസിക്കുകയും ചെയ്യുക. പിന്നെ ഉയരുകയും, അടങ്ങിയൊതുങ്ങി ഇരിക്കുകയും ചെയ്യുക. ഇപ്രകാരം നിസ്കാരം മുഴുവൻ ചെയ്യുക." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 436, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَفِي كُلِّ صَلَاةٍ قِرَاءَةٌ؟ قَالَ: "نَعَمْ". قَالَ رَجُلٌ مِنَ الْأَنْصَارِ: وَجَبَتْ هَذِهِ. فَالْتَفَتَ إِلَيَّ – وَكُنْتُ أَقْرَبَ الْقَوْمِ مِنْهُ – فَقَالَ: مَا أَرَى الْإِمَامَ إِذَا أَمَّ الْقَوْمَ إِلَّا قَدْ كَفَاهُمْ. (ن)', 'അബൂദർദാഅ്(റ): ''എല്ലാ നിസ്കാരങ്ങളിലും പാരായണം ചെയ്യേതുമോ?'' എന്ന് നബി(സ)യോടു ചോദിച്ചപ്പോൾ തിരുമേനി(സ) ''അതെ'' എന്നു മറുപടി നൽകി. അപ്പോൾ അൻസാരികളിൽപ്പെട്ട ഒരാൾ പറഞ്ഞു: ''ഇതു നിർബ്ബന്ധമായി'' അപ്പോൾ അബുദ്ദർദാഅ്(റ) എന്നിലേക്കു തിരിഞ്ഞു നോക്കി. ഞാനാകട്ടെ മറ്റുള്ളവരെക്കാൾ അദ്ദേഹത്തോട് അടുത്തായിരുന്നു - അദ്ദേഹം പറഞ്ഞു: ഒരു ഇമാം തന്റെ സമൂഹത്തിന് നേതൃത്വം നൽകി (നിസ്കരിക്കുമ്പോൾ) അവർക്ക് അതു (അദ്ദേഹത്തിന്റെ പാരായണം) മതിയാകും എന്നാണ് ഞാൻ അഭിപ്രായപ്പെടുന്നത് (ഇവിടെ തിരിഞ്ഞു നേക്കിയതും, ''അവർക്ക് ഇമാമിന്റെ പാരായണം മതിയാകും'' എന്ന് അഭിപ്രായപ്പെട്ടതും പ്രവാചകർ(സ)യല്ല മറിച്ച് റിപ്പോർട്ടറായ അബുദ്ദർദാഅ്(റ) ആണ് എന്നാണ് ഇമാം നസാഇയുടെ കാഴ്ച്ചപ്പാട്) (ന)', 'أَبِي الدَّرْدَاءِ', 'അബൂദർദാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 437, 437, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ غَزَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَبُوكَ، قَالَ الْمُغِيرَةُ: فَتَبَرَّزَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْلَ الْغَائِطِ، فَحَمَلْتُ مَعَهُ إِدَاوَةً، قَبْلَ صَلَاةِ الفجر، فَلَمَّا رَجَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيَّ أَخَذْتُ أُهَرِيقُ عَلَى يَدَيْهِ مِنَ الْإِدَاوَةِ، وَغَسَلَ يَدَيْهِ ثَلَاثَ مَرَّاتٍ، ثُمَّ غَسَلَ وَجْهَهُ، ثُمَّ ذَهَبَ يُخْرِجُ جُبَّتَهُ عَنْ ذِرَاعَيْهِ، فَضَاقَ كُمَّا جُبَّتِهِ، فَأَدْخَلَ يَدَيْهِ فِي الْجُبَّةِ، حَتَّى أَخْرَجَ ذِرَاعَيْهِ مِنْ أَسْفَلِ الْجُبَّةِ، وَغَسَلَ ذِرَاعَيْهِ إِلَى الْمِرْفَقَيْنِ، ثُمَّ تَوَضَّأَ عَلَى خُفَّيْهِ، ثُمَّ أَقْبَلَ، قَالَ الْمُغِيرَةُ: فَأَقْبَلْتُ مَعَهُ حَتَّى نَجِدَ النَّاسَ قَدْ قَدَّمُوا عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ فَصَلَّى لَهُمْ، فَأَدْرَكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِحْدَى الرَّكْعَتَيْنِ، فَصَلَّى مَعَ النَّاسِ الرَّكْعَةَ الْآخِرَةَ، فَلَمَّا سَلَّمَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ رَضِيَ اللهُ عَنْهُ قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُتِمُّ صَلَاتَهُ، فَأَفْزَعَ ذَلِكَ الْمُسْلِمِينَ، فَأَكْثَرُوا التَّسْبِيحَ، فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ أَقْبَلَ عَلَيْهِمْ، ثُمَّ قَالَ: "أَحْسَنْتُمْ". أَوْ قَالَ: "قَدْ أَصَبْتُمْ". يَغْبِطُهُمْ أَنْ صَلَّوُا الصَّلَاةَ لِوَقْتِهَا. (م)', 'ഉർവത് ബ്നുമുഗീറ: തന്റെ പിതാവ് മുഗീറത് ബ്നുശുഅ്ബ(റ)യിൽനിന്ന് നിവേദനം: മുഗീറ: നബി(സ)യുടെ കൂടെ തബൂക്ക് യുദ്ധത്തിൽ പങ്കെടുത്തിരുന്നു. (മുഗീറ(റ) പറയുന്നു): നബി(സ) സുബ്ഹി നിസ്കാരത്തിന് മുമ്പായി മലമൂത്രവിസർജ്ജനത്തിനായി പോയപ്പോൾ, ഒരു പാത്രം വെള്ളം കയ്യിൽ പിടിച്ച് ഞാനും പുറപ്പെട്ടു. നബി(സ) വിസർജ്ജനം കഴിഞ്ഞശേഷം എന്റെ അടുക്കൽ തിരിച്ചുവന്നപ്പോൾ (വുദുവുണ്ടാക്കാൻ) ഞാൻ പാത്രത്തിൽനിന്ന് വെള്ളം അദ്ദേഹത്തിന്റെ കൈകളിലേക്ക് ഒഴിച്ചുകൊടുത്തു. അവിടുന്ന് കൈകൾ മൂന്നുപ്രാവശ്യം കഴുകയും, പിന്നീട് മുഖം കഴുകകയും ചെയ്തു. അനന്തരം ജുബ്ബക്കുള്ളിൽ നിന്നും കൈകൾ പുറത്തെടുക്കാൻ ഒരുങ്ങിയപ്പോൾ ജുബ്ബയുടെ കൈപത്തിയുടെ ഭാഗം ഇടുങ്ങിയത് കാരണം സാധിക്കാതെ വരികയും, ജുബ്ബയുടെ അടിഭാഗം ഇരുകൈകളിൽ നിന്നും മാറ്റി മുട്ടുവരെ കൈകൾ രണ്ടും കഴുകകയും ചെയ്തു. പിന്നീട് ഖുഫയുടെമേൽ തടവുകയും (നമസ്കാരത്തിനായി) മുന്നോട്ട് നീങ്ങുകയും ചെയ്തു. അപ്പോഴേക്കും ജനങ്ങൾ അബ്ദുറഹ്മാനുബ്നു ഔഫി(റ)നെ ഇമാമാക്കി നിസ്കാരം ആരംഭിച്ചിരുന്നു. നബി(സ) ഒരു റക്അത്ത് ഇമാമിന്റെ കൂടെയും, ബാക്കി ജനങ്ങളുടെ കൂടെയും നിന്നും നിസ്കരിച്ചു. അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ) സലാം വീട്ടിയപ്പോൾ നിസ്കാരം പൂർത്തിയാക്കാൻ വേണ്ടി നബി(സ) എഴുന്നേറ്റ് നിന്നിരുന്നു. അത് മുസ്ലിംകൾക്ക് മനഃപ്രയാസമുണ്ടാക്കി. അവർ കൂടുതൽ തസ്ബീഹ് ചൊല്ലാൻ തുടങ്ങി. നിസ്കാരം പൂർത്തിയാക്കിയപ്പോൾ നബി(സ) അവരുടെ നേരെ വന്നുകൊണ്ട് പറഞ്ഞു: ''നിങ്ങൾ ചെയ്തത് വളരെ നന്നായി''. അഥവാ നിസ്കാരം കൃത്യസമത്തുതന്നെ നിർവ്വഹിച്ചതിൽ നബി(സ) പ്രശംസിക്കുകയായിരുന്നു. (മു)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'ഉർവത് ബ്നുമുഗീറ', null, null, array['م']::text[], array['മു']::text[], null, null, 437, 438, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النِّسَاءُ يُصَلِّينَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْفَجْرَ، فَكَانَ إِذَا سَلَّمَ انْصَرَفْنَ مُتَلَفِّعَاتٍ بِمُرُوطِهِنَّ، فَلَا يُعْرَفْنَ مِنَ الْغَلَسِ. (ق,د,ت,ن)', 'ആഇശ(റ): നബി(സ)യോടൊപ്പം സ്ത്രീകൾ ഫജ്ർ നിസ്കരിച്ചിരുന്നു. സലാം വീട്ടിയാൽ അവർ പിരിഞ്ഞ് പോകും, അവരുടെ മൂടുപടം കൊണ്ട് മറച്ചു കൊണ്ട് ഇരുട്ടിന്റെ നിഴൽ ഉള്ളതിനാൽ അവർ തിരിച്ചറിയപ്പെട്ടിരുന്നില്ല. (ബു,മു,ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 438, 438, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=19 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
